-- ============================================================================
-- Zoiko Suite — complete Supabase schema for the 20 finished services.
--
-- Generated by supabase/build-combined.sh from supabase/migrations/*.sql.
-- Do not hand-edit: change the per-service migration and regenerate.
--
-- Creates 21 schemas (`app` plus one per service) and 42 tables. Safe to run
-- as a single statement batch in the Supabase SQL editor.
--
-- BEFORE YOU RUN THIS, and BEFORE any service connects:
--
--   1. Rotate the zoiko_backend password. The foundation section creates the
--      role with a placeholder:
--        ALTER ROLE zoiko_backend WITH PASSWORD '<from your secret manager>';
--
--   2. Point the Go services at zoiko_backend, NOT at the postgres user and
--      NOT at the service_role key. Both bypass row-level security, which
--      would reproduce the exact gap this migration exists to close: on the
--      compose estate every service connects as the superuser, so all 119 RLS
--      policies are present, correct, and have never executed.
--
--   3. Expose the schemas you want reachable through PostgREST in your
--      project's API settings. `secret_vault_integration` deliberately grants
--      the `authenticated` role nothing and should not be exposed at all.
-- ============================================================================



-- ============================================================================
-- FILE: 0001_platform_foundation.sql
-- ============================================================================

-- 0001_platform_foundation.sql
-- Zoiko Suite on Supabase — shared foundation.
--
-- Applied ONCE, before any service migration. Every per-service migration in
-- this directory depends on the roles, schemas and helper functions created
-- here and will fail without it.
--
-- ── Why this file exists ─────────────────────────────────────────────────────
--
-- On the docker-compose estate every service connects as the Postgres
-- SUPERUSER, and a superuser bypasses row-level security unconditionally. The
-- 119 RLS policies across the estate are therefore present, correctly written,
-- and never executed. Moving to Supabase is the opportunity to make them
-- load-bearing, but only if the backend stops connecting as a bypassing role —
-- so this file creates `zoiko_backend`, a plain NOSUPERUSER / NOBYPASSRLS role
-- that the Go services use instead.
--
-- Note the same trap exists on Supabase in a new costume: the `service_role`
-- key used by supabase-js has BYPASSRLS. Anything that connects with the
-- service-role key is exactly as unprotected as the old superuser. Backend
-- services must use the `zoiko_backend` connection string, not that key.

-- ── Roles ────────────────────────────────────────────────────────────────────

-- The role every Go service connects as. NOT a superuser and NOT BYPASSRLS,
-- which is the entire point: FORCE ROW LEVEL SECURITY on the service tables
-- then applies to it, and the tenant policies actually run.
--
-- Password is set here as a placeholder and MUST be rotated before this is
-- pointed at anything real:
--   ALTER ROLE zoiko_backend WITH PASSWORD '<from your secret manager>';
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'zoiko_backend') THEN
        CREATE ROLE zoiko_backend LOGIN PASSWORD 'change_me_before_use'
            NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOBYPASSRLS;
    END IF;
END
$$;

-- ── app schema: helpers, not data ────────────────────────────────────────────

CREATE SCHEMA IF NOT EXISTS app;
COMMENT ON SCHEMA app IS
    'Platform helper functions. Owns no tables — service data lives in one schema per service.';

GRANT USAGE ON SCHEMA app TO zoiko_backend, authenticated, anon;

-- ── Identity helpers ─────────────────────────────────────────────────────────
--
-- Both helpers resolve identity from two sources, in order:
--
--   1. The PostgREST JWT claims (`request.jwt.claims`) — how a request arriving
--      through Supabase's own API surface carries identity.
--   2. `app.tenant_id` / `app.principal_id` set with set_config(...) on the
--      transaction — how the Go services already do it today, in withRLS /
--      withTenantTx.
--
-- Source 2 is a deliberate compatibility bridge. It means a service can be
-- pointed at Supabase WITHOUT rewriting its store layer, and the policies still
-- constrain it. Drop the fallback once every service authenticates through the
-- gateway with a real JWT.
--
-- STABLE, not IMMUTABLE: the value is fixed within a statement but varies
-- between transactions. Marking it IMMUTABLE would let the planner cache a
-- tenant across transactions, which would be a cross-tenant leak.

CREATE OR REPLACE FUNCTION app.current_tenant_id()
RETURNS TEXT
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = ''
AS $$
    SELECT COALESCE(
        NULLIF(current_setting('request.jwt.claims', true)::jsonb -> 'app_metadata' ->> 'tenant_id', ''),
        NULLIF(current_setting('request.jwt.claims', true)::jsonb ->> 'tenant_id', ''),
        NULLIF(current_setting('app.tenant_id', true), '')
    );
$$;

COMMENT ON FUNCTION app.current_tenant_id() IS
    'Caller tenant, from the JWT claim or from set_config(''app.tenant_id''). NULL when neither is set — policies must treat NULL as "match nothing", never as "match all".';

CREATE OR REPLACE FUNCTION app.current_principal_id()
RETURNS TEXT
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = ''
AS $$
    SELECT COALESCE(
        NULLIF(current_setting('request.jwt.claims', true)::jsonb ->> 'sub', ''),
        NULLIF(current_setting('app.principal_id', true), '')
    );
$$;

COMMENT ON FUNCTION app.current_principal_id() IS
    'Verified caller principal. Use as a column DEFAULT for created_by/actor columns so attribution cannot be supplied by the request body.';

GRANT EXECUTE ON FUNCTION app.current_tenant_id() TO zoiko_backend, authenticated, anon;
GRANT EXECUTE ON FUNCTION app.current_principal_id() TO zoiko_backend, authenticated, anon;

-- ── Append-only enforcement ──────────────────────────────────────────────────
--
-- Several services own evidence tables that are documented as append-only —
-- governance decisions, replay manifests, purchase-order amendments, document
-- access logs. Withholding the UPDATE/DELETE grant is enough to stop an
-- ordinary role such as zoiko_backend, and that is how most of them are
-- protected.
--
-- It is NOT enough for a privileged one. A superuser bypasses privilege checks
-- and row-level security entirely, and Supabase's `service_role` key carries
-- BYPASSRLS — so on the tables where mutation would destroy evidence rather
-- than merely corrupt state, a BEFORE trigger is used as well. A trigger is not
-- bypassed by any role, which makes it the only control in this database that
-- still binds the service-role key.
--
-- SECURITY INVOKER (the default) is deliberate: this must run with the caller's
-- rights and simply refuse, never act on anyone's behalf.

CREATE OR REPLACE FUNCTION app.reject_mutation()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION '%.% is append-only: % is not permitted',
        TG_TABLE_SCHEMA, TG_TABLE_NAME, TG_OP;
END;
$$;

COMMENT ON FUNCTION app.reject_mutation() IS
    'Refuses UPDATE and DELETE on append-only evidence tables. A trigger is used because it binds even a BYPASSRLS role such as Supabase''s service_role, which no policy or grant in this database does.';

-- ── Convention notes for the per-service migrations ──────────────────────────
--
-- 1. ONE SCHEMA PER SERVICE. The estate has 63 databases today; Supabase is a
--    single database. Schema-per-service preserves the ownership boundary and
--    keeps the five colliding table names apart — `obligations`,
--    `filing_requirements`, `access_decision_log`, `delegated_authorities` and
--    `principal_role_assignments` are each defined by two different services
--    and would overwrite each other in a flat `public`.
--
-- 2. EVERY TENANT-SCOPED TABLE GETS *BOTH* `ENABLE` AND `FORCE` ROW LEVEL
--    SECURITY. Ten of the twenty finished services enable without forcing,
--    which does nothing at all when the connecting role owns the table.
--
-- 3. POLICIES FAIL CLOSED ON A MISSING TENANT. Written as
--       tenant_id = app.current_tenant_id()
--    which is NULL-safe by accident of SQL semantics: NULL = anything is NULL,
--    not true, so a connection that never set a tenant sees zero rows. Never
--    write `app.current_tenant_id() IS NULL OR tenant_id = ...` — that is the
--    document-vault defect, a filter that switches itself off when the header
--    is absent.
--
-- 4. EVERY POLICY CARRIES `WITH CHECK`, not just `USING`. USING governs which
--    rows are visible; WITH CHECK governs which rows may be written. A policy
--    with only USING lets a caller INSERT a row into another tenant that it
--    then cannot see — the write-side integrity gap already open in
--    obligations-svc.


-- ============================================================================
-- FILE: 0002_jurisdiction_rules_svc.sql
-- ============================================================================

-- 0002_jurisdiction_rules_svc.sql
-- jurisdiction-rules-svc → schema `jurisdiction_rules`
--
-- Squashed end state of the service's four compose-era migrations:
--   000001_initial_schema, 000002_add_audit_columns,
--   000003_add_data_classification, 000004_add_rule_code_index
--
-- This is a NEW database, so the history is squashed rather than replayed —
-- the four files exist to get an already-running volume to this shape, and
-- nothing here needs that. The compose migrations remain the source of truth
-- for the docker estate until it is retired.
--
-- Three tables: jurisdictions, jurisdiction_rules, jurisdiction_rule_drift_events.
--
-- ── Tenancy ──────────────────────────────────────────────────────────────────
-- This service owns PLATFORM-WIDE REFERENCE DATA. There is no tenant_id column
-- on any of its tables, and that is deliberate — 000001 says so explicitly. So
-- the tenant policies used by the other nineteen services do not apply here.
--
-- RLS is still enabled and forced, because the read/write asymmetry matters:
-- these tables are readable by any authenticated principal and writable only by
-- the backend. Without RLS, exposing this schema through PostgREST would let
-- any logged-in console user rewrite the jurisdiction registry every other
-- service resolves against.

CREATE SCHEMA IF NOT EXISTS jurisdiction_rules;

COMMENT ON SCHEMA jurisdiction_rules IS
    'jurisdiction-rules-svc. Platform-wide reference data: jurisdiction identities and effective-dated applicability rules. No tenant dimension by design.';

GRANT USAGE ON SCHEMA jurisdiction_rules TO zoiko_backend, authenticated;

-- ── jurisdictions ────────────────────────────────────────────────────────────

CREATE TABLE jurisdiction_rules.jurisdictions (
    jurisdiction_id         UUID        PRIMARY KEY DEFAULT gen_random_uuid(),

    -- Human-readable code — data only, never used as switch/case (doctrine).
    jurisdiction_code       VARCHAR(32) NOT NULL,
    jurisdiction_name       TEXT        NOT NULL,

    -- VARCHAR, not an enum, so new values are a data migration and not a code
    -- change: COUNTRY, STATE_PROVINCE, TAX_AUTHORITY, LABOR_LAW_BOUNDARY,
    -- FILING_AUTHORITY, DATA_RESIDENCY_BOUNDARY.
    jurisdiction_type       VARCHAR(64) NOT NULL,

    -- Self-referential hierarchy of arbitrary depth (country → state → tax
    -- authority). NULL = root.
    parent_jurisdiction_id  UUID        REFERENCES jurisdiction_rules.jurisdictions(jurisdiction_id),

    -- FEDERAL, STATE, MUNICIPAL, SUPRANATIONAL — data driven.
    authority_type          VARCHAR(64) NOT NULL,

    -- Effective dating. NULL effective_to = currently valid. End-dating, never
    -- deletion.
    effective_from          TIMESTAMPTZ NOT NULL,
    effective_to            TIMESTAMPTZ,

    -- Operational deactivation, not a soft delete: the row is preserved and
    -- stays visible to GET /v1/jurisdictions so a register can still explain a
    -- historical record. It does stop resolving — the single-jurisdiction
    -- lookup is ACTIVE-ONLY and 404s once this is false, which is deliberate
    -- and consequential for records ALREADY bound to it.
    active_flag             BOOLEAN     NOT NULL DEFAULT TRUE,

    -- Audit
    created_at              TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_by_principal_id TEXT        NOT NULL DEFAULT app.current_principal_id(),
    updated_at              TIMESTAMPTZ,
    updated_by_principal_id TEXT,
    schema_version          VARCHAR(16) NOT NULL DEFAULT '1.0',

    -- PUBLIC tier: names, region codes, country codes.
    data_classification     VARCHAR(32) NOT NULL DEFAULT 'PUBLIC'
);

-- Idempotent creation key: same code + type + parent = same jurisdiction.
-- COALESCE so a NULL parent participates rather than making every root row
-- distinct from every other.
CREATE UNIQUE INDEX idx_jurisdictions_code_type_parent_unique
    ON jurisdiction_rules.jurisdictions (
        jurisdiction_code,
        jurisdiction_type,
        COALESCE(parent_jurisdiction_id, '00000000-0000-0000-0000-000000000000'::UUID)
    );

CREATE INDEX idx_jurisdictions_code   ON jurisdiction_rules.jurisdictions (jurisdiction_code);
CREATE INDEX idx_jurisdictions_parent ON jurisdiction_rules.jurisdictions (parent_jurisdiction_id)
    WHERE parent_jurisdiction_id IS NOT NULL;
CREATE INDEX idx_jurisdictions_active ON jurisdiction_rules.jurisdictions (active_flag)
    WHERE active_flag = TRUE;

-- ── jurisdiction_rules ───────────────────────────────────────────────────────

CREATE TABLE jurisdiction_rules.jurisdiction_rules (
    jurisdiction_rule_id    UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    jurisdiction_id         UUID         NOT NULL
                                         REFERENCES jurisdiction_rules.jurisdictions(jurisdiction_id),

    -- Domain tag — data driven: PAYROLL, TAX, EMPLOYMENT, FILING, RETENTION,
    -- BENEFITS. Never a code switch/case.
    rule_domain             VARCHAR(64)  NOT NULL,

    rule_code               VARCHAR(128) NOT NULL,
    rule_name               TEXT         NOT NULL,

    -- Point-in-time queries use the half-open interval:
    --   effective_from <= $at AND (effective_to IS NULL OR effective_to > $at)
    effective_from          TIMESTAMPTZ  NOT NULL,
    effective_to            TIMESTAMPTZ,

    -- Applicability METADATA only — never computation values (thresholds,
    -- rates, bands), which belong to the Tax and Payroll services.
    rule_payload            JSONB        NOT NULL DEFAULT '{}',

    -- Citation: legislative act, regulation, statutory instrument.
    source_reference        TEXT,

    -- ACTIVE | SUPERSEDED | DRAFT | RETIRED
    rule_status             VARCHAR(32)  NOT NULL DEFAULT 'DRAFT',

    external_feed_reference TEXT,

    -- Current state only. Full transition history is append-only in
    -- jurisdiction_rule_drift_events. CURRENT | DRIFTED | UNDER_REVIEW
    legal_drift_state       VARCHAR(32)  NOT NULL DEFAULT 'CURRENT',

    -- Audit
    created_at              TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    created_by_principal_id TEXT         NOT NULL DEFAULT app.current_principal_id(),
    updated_at              TIMESTAMPTZ,
    updated_by_principal_id TEXT,
    schema_version          VARCHAR(16)  NOT NULL DEFAULT '1.0',

    -- INTERNAL tier: rule domain settings, legislative metadata.
    data_classification     VARCHAR(32)  NOT NULL DEFAULT 'INTERNAL'
);

-- Dedup key for idempotent rule creation.
CREATE UNIQUE INDEX idx_jrules_jurisdiction_code_effective_from_unique
    ON jurisdiction_rules.jurisdiction_rules (jurisdiction_id, rule_code, effective_from);

-- Primary lookup: rules for a jurisdiction + domain.
CREATE INDEX idx_jrules_jurisdiction_domain
    ON jurisdiction_rules.jurisdiction_rules (jurisdiction_id, rule_domain);

-- Point-in-time resolution.
CREATE INDEX idx_jrules_effective
    ON jurisdiction_rules.jurisdiction_rules (jurisdiction_id, rule_domain, effective_from, effective_to);

CREATE INDEX idx_jrules_status
    ON jurisdiction_rules.jurisdiction_rules (rule_status)
    WHERE rule_status = 'ACTIVE';

CREATE INDEX idx_jrules_drift
    ON jurisdiction_rules.jurisdiction_rules (legal_drift_state)
    WHERE legal_drift_state != 'CURRENT';

-- Serves hasOverlappingRule (filters on jurisdiction_id + rule_domain +
-- rule_code before comparing periods, on every create and every transition
-- into a live status) and FindRulePack's DISTINCT ON across an ancestor chain.
-- idx_jrules_effective cannot serve either — rule_code is not in it.
CREATE INDEX idx_jrules_domain_code
    ON jurisdiction_rules.jurisdiction_rules (jurisdiction_id, rule_domain, rule_code, effective_from);

-- ── jurisdiction_rule_drift_events ───────────────────────────────────────────
-- Append-only history of legal_drift_state transitions. The column on
-- jurisdiction_rules holds current state; this preserves the full chain without
-- overwriting. "Append-only" is enforced below by granting INSERT and SELECT
-- and no policy for UPDATE or DELETE, rather than by convention.

CREATE TABLE jurisdiction_rules.jurisdiction_rule_drift_events (
    drift_event_id           UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    jurisdiction_rule_id     UUID        NOT NULL
                                         REFERENCES jurisdiction_rules.jurisdiction_rules(jurisdiction_rule_id),
    from_state               VARCHAR(32) NOT NULL,
    to_state                 VARCHAR(32) NOT NULL,
    reason                   TEXT,
    effective_at             TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    recorded_by_principal_id TEXT        NOT NULL DEFAULT app.current_principal_id(),
    correlation_id           TEXT,
    schema_version           VARCHAR(16) NOT NULL DEFAULT '1.0'
);

CREATE INDEX idx_drift_events_rule
    ON jurisdiction_rules.jurisdiction_rule_drift_events (jurisdiction_rule_id, effective_at DESC);

-- ── Row-level security ───────────────────────────────────────────────────────
-- ENABLE *and* FORCE on all three. FORCE is what makes the policies apply to
-- the role that owns the tables; without it the owner bypasses them and the
-- policies below would be decorative.

ALTER TABLE jurisdiction_rules.jurisdictions                    ENABLE ROW LEVEL SECURITY;
ALTER TABLE jurisdiction_rules.jurisdictions                    FORCE  ROW LEVEL SECURITY;
ALTER TABLE jurisdiction_rules.jurisdiction_rules               ENABLE ROW LEVEL SECURITY;
ALTER TABLE jurisdiction_rules.jurisdiction_rules               FORCE  ROW LEVEL SECURITY;
ALTER TABLE jurisdiction_rules.jurisdiction_rule_drift_events   ENABLE ROW LEVEL SECURITY;
ALTER TABLE jurisdiction_rules.jurisdiction_rule_drift_events   FORCE  ROW LEVEL SECURITY;

-- Read: any authenticated principal. This is reference data every other
-- service resolves against, and it carries no tenant dimension, so there is
-- nothing to partition reads by. `anon` is deliberately NOT granted — an
-- unauthenticated caller has no business enumerating the registry.
CREATE POLICY reference_data_read ON jurisdiction_rules.jurisdictions
    FOR SELECT TO authenticated, zoiko_backend USING (true);

CREATE POLICY reference_data_read ON jurisdiction_rules.jurisdiction_rules
    FOR SELECT TO authenticated, zoiko_backend USING (true);

CREATE POLICY reference_data_read ON jurisdiction_rules.jurisdiction_rule_drift_events
    FOR SELECT TO authenticated, zoiko_backend USING (true);

-- Write: backend only. Authorization for these routes is decided by
-- authorization-svc against the JURISDICTION_* / JURISDICTION_RULE_* actions;
-- the database's job is to ensure the write arrived through the service that
-- performs that check, not directly from a console session.
CREATE POLICY backend_write ON jurisdiction_rules.jurisdictions
    FOR INSERT TO zoiko_backend WITH CHECK (true);
CREATE POLICY backend_update ON jurisdiction_rules.jurisdictions
    FOR UPDATE TO zoiko_backend USING (true) WITH CHECK (true);

CREATE POLICY backend_write ON jurisdiction_rules.jurisdiction_rules
    FOR INSERT TO zoiko_backend WITH CHECK (true);
CREATE POLICY backend_update ON jurisdiction_rules.jurisdiction_rules
    FOR UPDATE TO zoiko_backend USING (true) WITH CHECK (true);

-- Drift events get INSERT and no UPDATE/DELETE policy, for anyone. An append-
-- only register that can be edited is not one.
CREATE POLICY backend_append ON jurisdiction_rules.jurisdiction_rule_drift_events
    FOR INSERT TO zoiko_backend WITH CHECK (true);

-- ── Grants ───────────────────────────────────────────────────────────────────
-- RLS narrows what a role may touch; it does not grant access in the first
-- place. Both are required.

GRANT SELECT ON ALL TABLES IN SCHEMA jurisdiction_rules TO authenticated;

GRANT SELECT, INSERT, UPDATE ON
    jurisdiction_rules.jurisdictions,
    jurisdiction_rules.jurisdiction_rules
    TO zoiko_backend;

-- No UPDATE, no DELETE — append-only, enforced by the grant as well as by the
-- absent policy.
GRANT SELECT, INSERT ON jurisdiction_rules.jurisdiction_rule_drift_events TO zoiko_backend;

-- DELETE is granted to nobody on any table in this schema. The service has no
-- delete route by design: deactivation is active_flag + effective_to.


-- ============================================================================
-- FILE: 0003_delegated_authority_svc.sql
-- ============================================================================

-- 0003_delegated_authority_svc.sql
-- delegated-authority-svc → schema `delegated_authority`
--
-- Squashed end state of 000001_initial_schema and 000002 (the FORCE RLS +
-- invariants pass). One table: delegation_grants.
--
-- ── This is the tenant-scoped template ───────────────────────────────────────
-- jurisdiction-rules (the previous migration) is platform reference data with
-- no tenant dimension. This file is the shape the other eighteen services
-- follow: a tenant_id column, ENABLE + FORCE row-level security, and a policy
-- with BOTH a USING and a WITH CHECK clause written against
-- app.current_tenant_id().
--
-- ── Two deliberate departures from the compose migrations ────────────────────
--
-- 1. The CHECK constraints are added VALID here, not NOT VALID.
--    000002 added them NOT VALID on purpose: the dev database holds real
--    history, and a migration must not rewrite an append-then-transition
--    register to make a constraint pass. That reasoning is about an EXISTING
--    table with a backlog. This is an empty database, so there is no history to
--    protect and no reason to ship a constraint that has never been verified
--    against its own table. The open "run VALIDATE CONSTRAINT once the backlog
--    is clean" item does not carry over to Supabase.
--
-- 2. The policy reads app.current_tenant_id() rather than
--    current_setting('app.tenant_id', true) directly, so the same policy serves
--    a Go service that calls set_config and a PostgREST request carrying a JWT
--    claim. See the foundation migration for why both are accepted.

CREATE SCHEMA IF NOT EXISTS delegated_authority;

COMMENT ON SCHEMA delegated_authority IS
    'delegated-authority-svc. Register of which principal may act for which other principal, on which action, for how long.';

GRANT USAGE ON SCHEMA delegated_authority TO zoiko_backend, authenticated;

-- ── delegation_grants ────────────────────────────────────────────────────────

CREATE TABLE delegated_authority.delegation_grants (
    delegation_id            UUID         PRIMARY KEY DEFAULT gen_random_uuid(),

    tenant_id                VARCHAR(255) NOT NULL,
    legal_entity_id          VARCHAR(255) NOT NULL,

    -- Who is handing authority over, and to whom.
    delegator_principal_id   VARCHAR(255) NOT NULL,
    delegate_principal_id    VARCHAR(255) NOT NULL,

    action_type              VARCHAR(100) NOT NULL,

    effective_from           TIMESTAMPTZ  NOT NULL,
    effective_to             TIMESTAMPTZ  NOT NULL,

    -- ACTIVE | REVOKED | EXPIRED
    status                   VARCHAR(20)  NOT NULL,

    -- Attribution defaults to the VERIFIED principal rather than whatever the
    -- request body carried. Fail-closed: with no principal on the connection
    -- this resolves NULL and the NOT NULL rejects the insert.
    created_by_principal_id  VARCHAR(255) NOT NULL DEFAULT app.current_principal_id(),

    correlation_id           VARCHAR(255) NOT NULL,
    created_at               TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at               TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    revoked_by_principal_id  VARCHAR(255),
    revoked_at               TIMESTAMPTZ,
    expired_at               TIMESTAMPTZ,

    CONSTRAINT delegation_grants_period_ordered
        CHECK (effective_to > effective_from),

    -- The status vocabulary the domain defines. Enforced in Go today and
    -- nowhere else, so any other writer — a fix-up script, a future service —
    -- could otherwise leave a status no consumer knows how to read.
    CONSTRAINT delegation_grants_status_known
        CHECK (status IN ('ACTIVE', 'REVOKED', 'EXPIRED')),

    -- A terminal state must carry its evidence. A REVOKED grant with no
    -- revoked_at/revoked_by is a record that someone withdrew an authority with
    -- no account of who or when — which is the only thing that row is for.
    --
    -- Written as an equivalence in both directions so a revoked_at cannot
    -- linger on a row later rewritten to ACTIVE.
    CONSTRAINT delegation_grants_revoked_has_evidence
        CHECK ((status = 'REVOKED') = (revoked_at IS NOT NULL AND revoked_by_principal_id IS NOT NULL)),

    CONSTRAINT delegation_grants_expired_has_evidence
        CHECK ((status = 'EXPIRED') = (expired_at IS NOT NULL)),

    -- A delegation delegates authority to someone ELSE. A grant whose delegator
    -- and delegate are the same principal is not a delegation, it is a no-op
    -- that reads as one — and it is the shape a self-elevation attempt takes.
    CONSTRAINT delegation_grants_delegate_differs
        CHECK (delegator_principal_id <> delegate_principal_id)
);

-- Idempotency: a retried create with the same (tenant_id, correlation_id) must
-- resolve to the original record, never a duplicate.
CREATE UNIQUE INDEX idx_delegation_grants_tenant_correlation
    ON delegated_authority.delegation_grants (tenant_id, correlation_id);

CREATE INDEX idx_delegation_grants_tenant_entity_status
    ON delegated_authority.delegation_grants (tenant_id, legal_entity_id, status);

CREATE INDEX idx_delegation_grants_tenant_delegate
    ON delegated_authority.delegation_grants (tenant_id, delegate_principal_id, status);

-- Serves the lazy-expiry sweep (status = 'ACTIVE' AND effective_to < now()).
CREATE INDEX idx_delegation_grants_tenant_active_effective_to
    ON delegated_authority.delegation_grants (tenant_id, effective_to)
    WHERE status = 'ACTIVE';

-- The register is read newest-first and paged. created_at alone is not a total
-- order, so the index carries the primary key as a tiebreaker for the same
-- reason the ORDER BY does — without it two grants created in the same
-- transaction can straddle a page boundary and be returned twice, or not at all.
CREATE INDEX idx_delegation_grants_tenant_created
    ON delegated_authority.delegation_grants (tenant_id, created_at DESC, delegation_id DESC);

-- ── Row-level security ───────────────────────────────────────────────────────

ALTER TABLE delegated_authority.delegation_grants ENABLE ROW LEVEL SECURITY;
ALTER TABLE delegated_authority.delegation_grants FORCE  ROW LEVEL SECURITY;

-- USING governs which rows are visible; WITH CHECK governs which rows may be
-- written. Both are required. With only USING, a caller can INSERT a row into
-- another tenant that it then cannot see — a write-side integrity gap that is
-- still open in obligations-svc on the compose estate.
--
-- NULL-safe by SQL semantics rather than by an explicit guard: when no tenant
-- is installed, app.current_tenant_id() is NULL, `tenant_id = NULL` is NULL,
-- and NULL is not true — so a connection that never set a tenant sees nothing
-- and can write nothing. Never rewrite this as
-- `app.current_tenant_id() IS NULL OR tenant_id = ...`; that is a filter which
-- switches itself off exactly when identity is missing.
CREATE POLICY tenant_isolation ON delegated_authority.delegation_grants
    FOR ALL
    TO zoiko_backend
    USING      (tenant_id = app.current_tenant_id())
    WITH CHECK (tenant_id = app.current_tenant_id());

-- Console sessions read their own tenant's register and never write it: every
-- mutation is authorized by authorization-svc against DELEGATION_CREATE /
-- DELEGATION_REVOKE and must arrive through the service that performs that check.
CREATE POLICY tenant_read ON delegated_authority.delegation_grants
    FOR SELECT
    TO authenticated
    USING (tenant_id = app.current_tenant_id());

-- ── Grants ───────────────────────────────────────────────────────────────────
-- RLS narrows what a role may touch; it does not grant access in the first
-- place. Both are required.

GRANT SELECT ON delegated_authority.delegation_grants TO authenticated;

-- No DELETE. The register is append-then-transition: a grant is revoked or
-- expired, never removed, because its history is the evidence of what authority
-- was held and when.
GRANT SELECT, INSERT, UPDATE ON delegated_authority.delegation_grants TO zoiko_backend;


-- ============================================================================
-- FILE: 0004_accounts_payable_svc.sql
-- ============================================================================

-- 0004_accounts_payable_svc.sql
-- accounts-payable-svc → schema `accounts_payable`
--
-- Squashed end state of 000001_initial_schema, 000002_add_idempotency_index
-- and 000003_add_source_contract_id. One table: vendor_invoices.
--
-- ── A note the compose migration's own header makes, now obsolete ────────────
-- 000001 says RLS here is "defense-in-depth, not the sole isolation guarantee"
-- because the services connect as a Postgres superuser which bypasses RLS
-- unconditionally — a fact found through a real CI failure, not theory. Under
-- `zoiko_backend` that is no longer true: the policy below is load-bearing. The
-- store layer's explicit `tenant_id = $1` predicates stay as belt and braces.
--
-- ── Tenant comparison is done as TEXT ────────────────────────────────────────
-- tenant_id is UUID here, and the compose policy cast the setting with
-- `current_setting('app.tenant_id')::UUID`. Two problems carried by that form:
-- it omits the missing_ok flag, so an unset tenant RAISES rather than returning
-- NULL; and a non-UUID value raises on the cast. Comparing
-- `tenant_id::text = app.current_tenant_id()` degrades to "matches nothing"
-- instead of erroring, which is the fail-closed behaviour wanted.

CREATE SCHEMA IF NOT EXISTS accounts_payable;

COMMENT ON SCHEMA accounts_payable IS
    'accounts-payable-svc. Vendor invoice headers through the create → validate → approve → request-payment lifecycle.';

GRANT USAGE ON SCHEMA accounts_payable TO zoiko_backend, authenticated;

-- ── vendor_invoices ──────────────────────────────────────────────────────────
-- No vendors table: no Vendor Master service exists anywhere on the platform,
-- so vendor_id is a plain, unvalidated string column.

CREATE TABLE accounts_payable.vendor_invoices (
    invoice_id                        UUID          PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id                         UUID          NOT NULL,
    legal_entity_id                   UUID          NOT NULL,

    vendor_id                         VARCHAR(255)  NOT NULL,
    invoice_number                    VARCHAR(255)  NOT NULL,
    amount                            NUMERIC(18,2) NOT NULL,
    currency_code                     VARCHAR(3)    NOT NULL,
    due_date                          DATE          NOT NULL,

    -- RECEIVED | VALIDATED | APPROVED | PAYMENT_REQUESTED
    status                            VARCHAR(20)   NOT NULL,

    -- Which contract (if any) this invoice was issued against. Nullable
    -- because not every vendor invoice is tied to one; nothing fabricates a
    -- contract_id when there is no real contract behind an invoice.
    source_contract_id                UUID,

    -- Attribution defaults to the verified principal rather than the request
    -- body. Fail-closed: NULL principal + NOT NULL column rejects the write.
    created_by_principal_id           VARCHAR(255)  NOT NULL DEFAULT app.current_principal_id(),
    validated_by_principal_id         VARCHAR(255),
    approved_by_principal_id          VARCHAR(255),
    payment_requested_by_principal_id VARCHAR(255),

    correlation_id                    VARCHAR(255)  NOT NULL,
    created_at                        TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
    validated_at                      TIMESTAMPTZ,
    approved_at                       TIMESTAMPTZ,
    payment_requested_at              TIMESTAMPTZ,

    UNIQUE (tenant_id, vendor_id, invoice_number)
);

CREATE INDEX idx_vendor_invoices_tenant        ON accounts_payable.vendor_invoices (tenant_id);
CREATE INDEX idx_vendor_invoices_entity_vendor ON accounts_payable.vendor_invoices (legal_entity_id, vendor_id);
CREATE INDEX idx_vendor_invoices_status        ON accounts_payable.vendor_invoices (status);

-- Idempotency: a retried CreateInvoice — after a client-side timeout on a POST
-- that actually succeeded server-side — must resolve to the ORIGINAL invoice
-- rather than create a duplicate liability.
--
-- Partial (WHERE correlation_id != '') is kept from the compose migration. On a
-- fresh database there are no legacy blank rows, but the service still permits
-- an empty correlation_id, and several such rows must not collide as false
-- duplicates.
CREATE UNIQUE INDEX idx_vendor_invoices_tenant_correlation
    ON accounts_payable.vendor_invoices (tenant_id, correlation_id)
    WHERE correlation_id != '';

-- ── Row-level security ───────────────────────────────────────────────────────

ALTER TABLE accounts_payable.vendor_invoices ENABLE ROW LEVEL SECURITY;
ALTER TABLE accounts_payable.vendor_invoices FORCE  ROW LEVEL SECURITY;

CREATE POLICY tenant_isolation ON accounts_payable.vendor_invoices
    FOR ALL
    TO zoiko_backend
    USING      (tenant_id::text = app.current_tenant_id())
    WITH CHECK (tenant_id::text = app.current_tenant_id());

CREATE POLICY tenant_read ON accounts_payable.vendor_invoices
    FOR SELECT
    TO authenticated
    USING (tenant_id::text = app.current_tenant_id());

-- ── Grants ───────────────────────────────────────────────────────────────────

GRANT SELECT ON accounts_payable.vendor_invoices TO authenticated;

-- No DELETE: an invoice is a liability record and transitions through statuses;
-- it is never removed.
GRANT SELECT, INSERT, UPDATE ON accounts_payable.vendor_invoices TO zoiko_backend;


-- ============================================================================
-- FILE: 0005_purchase_request_svc.sql
-- ============================================================================

-- 0005_purchase_request_svc.sql
-- purchase-request-svc → schema `purchase_request`
--
-- Squashed end state of 000001_initial_schema and 000002_add_idempotency_index.
-- One table: purchase_requests.

CREATE SCHEMA IF NOT EXISTS purchase_request;

COMMENT ON SCHEMA purchase_request IS
    'purchase-request-svc. Purchase request headers through the create → approve/reject lifecycle.';

GRANT USAGE ON SCHEMA purchase_request TO zoiko_backend, authenticated;

-- ── purchase_requests ────────────────────────────────────────────────────────

CREATE TABLE purchase_request.purchase_requests (
    request_id                UUID          PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id                 UUID          NOT NULL,
    legal_entity_id           UUID          NOT NULL,

    -- The requester is the verified caller, not a body field.
    requested_by_principal_id VARCHAR(255)  NOT NULL DEFAULT app.current_principal_id(),

    description               TEXT          NOT NULL,
    amount                    NUMERIC(18,2) NOT NULL,
    currency_code             VARCHAR(3)    NOT NULL,

    -- PENDING | APPROVED | REJECTED
    status                    VARCHAR(20)   NOT NULL,

    approved_by_principal_id  VARCHAR(255),
    rejected_by_principal_id  VARCHAR(255),
    rejection_reason          TEXT,

    correlation_id            VARCHAR(255)  NOT NULL,
    created_at                TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
    approved_at               TIMESTAMPTZ,
    rejected_at               TIMESTAMPTZ,

    -- A terminal state must carry its evidence, and must not carry the other
    -- state's. Not present on the compose estate, where the table has real
    -- history that could not be guaranteed to satisfy it; an empty database
    -- has no such backlog. Same reasoning as the delegated-authority pass.
    CONSTRAINT purchase_requests_approved_has_evidence
        CHECK ((status = 'APPROVED') = (approved_at IS NOT NULL AND approved_by_principal_id IS NOT NULL)),
    CONSTRAINT purchase_requests_rejected_has_evidence
        CHECK ((status = 'REJECTED') = (rejected_at IS NOT NULL AND rejected_by_principal_id IS NOT NULL))
);

CREATE INDEX idx_purchase_requests_tenant ON purchase_request.purchase_requests (tenant_id);
CREATE INDEX idx_purchase_requests_entity ON purchase_request.purchase_requests (legal_entity_id);
CREATE INDEX idx_purchase_requests_status ON purchase_request.purchase_requests (status);

-- Idempotency: a retried CreateRequest resolves to the ORIGINAL request rather
-- than creating a duplicate. Partial for the same reason as accounts-payable's.
CREATE UNIQUE INDEX idx_purchase_requests_tenant_correlation
    ON purchase_request.purchase_requests (tenant_id, correlation_id)
    WHERE correlation_id != '';

-- ── Row-level security ───────────────────────────────────────────────────────

ALTER TABLE purchase_request.purchase_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE purchase_request.purchase_requests FORCE  ROW LEVEL SECURITY;

CREATE POLICY tenant_isolation ON purchase_request.purchase_requests
    FOR ALL
    TO zoiko_backend
    USING      (tenant_id::text = app.current_tenant_id())
    WITH CHECK (tenant_id::text = app.current_tenant_id());

CREATE POLICY tenant_read ON purchase_request.purchase_requests
    FOR SELECT
    TO authenticated
    USING (tenant_id::text = app.current_tenant_id());

-- ── Grants ───────────────────────────────────────────────────────────────────

GRANT SELECT ON purchase_request.purchase_requests TO authenticated;
GRANT SELECT, INSERT, UPDATE ON purchase_request.purchase_requests TO zoiko_backend;


-- ============================================================================
-- FILE: 0006_bank_reconciliation_svc.sql
-- ============================================================================

-- 0006_bank_reconciliation_svc.sql
-- bank-reconciliation-svc → schema `bank_reconciliation`
--
-- Squashed end state of 000001_initial_schema, 000002_add_idempotency_index
-- and 000003_add_gl_cash_account_code. One table: statement_lines.

CREATE SCHEMA IF NOT EXISTS bank_reconciliation;

COMMENT ON SCHEMA bank_reconciliation IS
    'bank-reconciliation-svc. Bank statement lines and their match / exception state against the general ledger.';

GRANT USAGE ON SCHEMA bank_reconciliation TO zoiko_backend, authenticated;

-- ── statement_lines ──────────────────────────────────────────────────────────

CREATE TABLE bank_reconciliation.statement_lines (
    statement_line_id       UUID          PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id               UUID          NOT NULL,
    legal_entity_id         UUID          NOT NULL,
    bank_account_id         UUID          NOT NULL,

    statement_date          DATE          NOT NULL,
    amount                  NUMERIC(18,2) NOT NULL,
    currency_code           VARCHAR(3)    NOT NULL,
    bank_reference          VARCHAR(255)  NOT NULL,

    -- UNMATCHED | MATCHED | EXCEPTION
    status                  VARCHAR(20)   NOT NULL,

    -- Which general-ledger account represents this bank account. Required to
    -- verify the DIRECTION of a match, and that is not a nicety:
    --
    -- Matching used to compare magnitudes — abs(journal net) against
    -- abs(statement amount). A journal's net was the sum of one side of a
    -- balanced double-entry journal, always positive, carrying no direction at
    -- all. So a statement line of -500.00 (money leaving the account)
    -- reconciled cleanly against a journal that moved 500.00 IN. A payment out
    -- matching a receipt in is precisely the error, or the concealment, that
    -- reconciling exists to surface.
    --
    -- Direction cannot be recovered from the journal alone — it depends on
    -- which side the CASH line falls on, so the account code IS the missing
    -- fact. Nullable because nothing on the platform maps a bank_account_id to
    -- a ledger account code; a NULL is NOT "skip the check", the handler
    -- refuses to match such a line at all with a distinct error.
    gl_cash_account_code    VARCHAR(50),

    matched_journal_id      UUID,
    matched_by_principal_id VARCHAR(255),
    matched_at              TIMESTAMPTZ,

    exception_reason        VARCHAR(500),
    flagged_by_principal_id VARCHAR(255),
    flagged_at              TIMESTAMPTZ,

    correlation_id          VARCHAR(255)  NOT NULL,
    created_at              TIMESTAMPTZ   NOT NULL DEFAULT NOW(),

    -- Terminal states carry their evidence. New here for the same reason as
    -- the other services in this migration set: an empty database has no
    -- backlog that would force these to be added NOT VALID.
    CONSTRAINT statement_lines_matched_has_evidence
        CHECK ((status = 'MATCHED') = (matched_at IS NOT NULL AND matched_journal_id IS NOT NULL)),
    CONSTRAINT statement_lines_exception_has_reason
        CHECK (status <> 'EXCEPTION' OR (exception_reason IS NOT NULL AND exception_reason <> ''))
);

COMMENT ON COLUMN bank_reconciliation.statement_lines.gl_cash_account_code IS
    'general-ledger account code representing this bank account. Required to verify the direction of a match; a line without one cannot be matched.';

CREATE INDEX idx_statement_lines_tenant ON bank_reconciliation.statement_lines (tenant_id);
CREATE INDEX idx_statement_lines_status ON bank_reconciliation.statement_lines (status);

-- Serves the statement-completion check: "any UNMATCHED lines left for this
-- bank account + statement date?"
CREATE INDEX idx_statement_lines_account_date
    ON bank_reconciliation.statement_lines (tenant_id, bank_account_id, statement_date);

-- Idempotency: a retried ingest resolves to the ORIGINAL line.
CREATE UNIQUE INDEX idx_statement_lines_tenant_correlation
    ON bank_reconciliation.statement_lines (tenant_id, correlation_id)
    WHERE correlation_id != '';

-- ── Row-level security ───────────────────────────────────────────────────────

ALTER TABLE bank_reconciliation.statement_lines ENABLE ROW LEVEL SECURITY;
ALTER TABLE bank_reconciliation.statement_lines FORCE  ROW LEVEL SECURITY;

CREATE POLICY tenant_isolation ON bank_reconciliation.statement_lines
    FOR ALL
    TO zoiko_backend
    USING      (tenant_id::text = app.current_tenant_id())
    WITH CHECK (tenant_id::text = app.current_tenant_id());

CREATE POLICY tenant_read ON bank_reconciliation.statement_lines
    FOR SELECT
    TO authenticated
    USING (tenant_id::text = app.current_tenant_id());

-- ── Grants ───────────────────────────────────────────────────────────────────

GRANT SELECT ON bank_reconciliation.statement_lines TO authenticated;
GRANT SELECT, INSERT, UPDATE ON bank_reconciliation.statement_lines TO zoiko_backend;


-- ============================================================================
-- FILE: 0007_notification_svc.sql
-- ============================================================================

-- 0007_notification_svc.sql
-- notification-svc → schema `notification`
--
-- Squashed end state of 000001_initial_schema and
-- 000002_force_rls_and_constraints. One table: notifications.
--
-- ── The NOT VALID constraints become VALID here ──────────────────────────────
-- 000002 added every CHECK as NOT VALID for a specific reason: the dev database
-- holds rows the old delivery adapter wrote when it treated an unrecognised
-- channel as a delivery failure — e.g. (channel 'PIGEON', status 'FAILED',
-- failure_reason 'unsupported channel: PIGEON'). Those rows are the audit trail
-- of what the service actually did, wrong as it was, and a migration must not
-- quietly rewrite them to make a constraint pass.
--
-- That is an argument about an existing table with a backlog. This database has
-- none, so the constraints are declared normally and the open "run VALIDATE
-- CONSTRAINT once the backlog is dealt with" item does not travel here.
--
-- ── Still true on Supabase ───────────────────────────────────────────────────
-- Delivery goes through a documented STUB adapter. No real provider is wired,
-- so a row reading SENT means "recorded and accepted by the stub", not
-- "delivered". Nothing in this migration changes that.

CREATE SCHEMA IF NOT EXISTS notification;

COMMENT ON SCHEMA notification IS
    'notification-svc. Register of notifications and their delivery outcome. Delivery is via a stub adapter — SENT means accepted by the stub, not delivered.';

GRANT USAGE ON SCHEMA notification TO zoiko_backend, authenticated;

-- ── notifications ────────────────────────────────────────────────────────────

CREATE TABLE notification.notifications (
    notification_id         UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id               VARCHAR(255) NOT NULL,
    legal_entity_id         VARCHAR(255) NOT NULL,

    recipient_principal_id  VARCHAR(255) NOT NULL,

    -- EMAIL | SMS | IN_APP | WEBHOOK
    channel                 VARCHAR(20)  NOT NULL,

    subject                 VARCHAR(255) NOT NULL,
    body                    TEXT         NOT NULL,

    -- PENDING | SENT | FAILED
    status                  VARCHAR(20)  NOT NULL,

    source_event_type       VARCHAR(100),
    source_reference        VARCHAR(255),
    correlation_id          VARCHAR(255) NOT NULL,
    failure_reason          TEXT,

    created_by_principal_id VARCHAR(255) NOT NULL DEFAULT app.current_principal_id(),
    created_at              TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    sent_at                 TIMESTAMPTZ,

    -- The vocabulary the domain defines, enforced in Go and — before these —
    -- nowhere else, so any other writer could leave a value no consumer knows
    -- how to read.
    CONSTRAINT notifications_channel_known
        CHECK (channel IN ('EMAIL', 'SMS', 'IN_APP', 'WEBHOOK')),
    CONSTRAINT notifications_status_known
        CHECK (status IN ('PENDING', 'SENT', 'FAILED')),

    -- A concluded delivery must say when it concluded, and a FAILED one must
    -- say why. A FAILED row with no reason is a record that something did not
    -- go out and no account of what happened — which is the only thing that
    -- row is for.
    CONSTRAINT notifications_concluded_has_timestamp
        CHECK (status = 'PENDING' OR sent_at IS NOT NULL),
    CONSTRAINT notifications_failed_has_reason
        CHECK (status <> 'FAILED' OR (failure_reason IS NOT NULL AND failure_reason <> ''))
);

-- Idempotency: a retried send resolves to the original notification, never a
-- duplicate send.
CREATE UNIQUE INDEX idx_notifications_tenant_correlation
    ON notification.notifications (tenant_id, correlation_id);

CREATE INDEX idx_notifications_tenant_entity
    ON notification.notifications (tenant_id, legal_entity_id);
CREATE INDEX idx_notifications_tenant_recipient
    ON notification.notifications (tenant_id, recipient_principal_id);
CREATE INDEX idx_notifications_tenant_status
    ON notification.notifications (tenant_id, status);

-- The register is read newest-first and paged; created_at alone is not a total
-- order, so the index carries the primary key as a tiebreaker for the same
-- reason the ORDER BY does.
CREATE INDEX idx_notifications_tenant_created
    ON notification.notifications (tenant_id, created_at DESC, notification_id DESC);

-- ── Row-level security ───────────────────────────────────────────────────────

ALTER TABLE notification.notifications ENABLE ROW LEVEL SECURITY;
ALTER TABLE notification.notifications FORCE  ROW LEVEL SECURITY;

CREATE POLICY tenant_isolation ON notification.notifications
    FOR ALL
    TO zoiko_backend
    USING      (tenant_id = app.current_tenant_id())
    WITH CHECK (tenant_id = app.current_tenant_id());

-- A recipient's own notifications are readable by that recipient; everything
-- else in the tenant is not. Tighter than the other services' tenant-wide read
-- because the body of a notification is addressed to one person.
CREATE POLICY recipient_read ON notification.notifications
    FOR SELECT
    TO authenticated
    USING (
        tenant_id = app.current_tenant_id()
        AND recipient_principal_id = app.current_principal_id()
    );

-- ── Grants ───────────────────────────────────────────────────────────────────

GRANT SELECT ON notification.notifications TO authenticated;

-- No DELETE: the register is the account of what was sent, including what
-- failed to send.
GRANT SELECT, INSERT, UPDATE ON notification.notifications TO zoiko_backend;


-- ============================================================================
-- FILE: 0008_schema_registry_svc.sql
-- ============================================================================

-- 0008_schema_registry_svc.sql
-- schema-registry-svc → schema `schema_registry`
--
-- Squashed end state of 000001_initial_schema, 000002_add_compatibility_mode
-- and 000003_registry_invariants. One table: event_schemas.
--
-- ── No tenant dimension ──────────────────────────────────────────────────────
-- Like jurisdiction-rules, this is platform-wide reference data: event
-- contracts belong to the platform, not to a tenant. RLS is still enabled and
-- forced to keep the read/write asymmetry — readable by any authenticated
-- principal, writable only by the backend.
--
-- ── Append-only, enforced rather than asserted ───────────────────────────────
-- Doctrine: a schema version is never edited or deleted once registered.
-- Evolution always INSERTs a new (event_name, version) row. Here that is a
-- grant of SELECT and INSERT only, with no UPDATE or DELETE to anyone — the
-- compose estate stated the rule in a comment and left the table fully
-- writable.

CREATE SCHEMA IF NOT EXISTS schema_registry;

COMMENT ON SCHEMA schema_registry IS
    'schema-registry-svc. Append-only registry of event contract versions. Platform-wide, no tenant dimension.';

GRANT USAGE ON SCHEMA schema_registry TO zoiko_backend, authenticated;

-- ── event_schemas ────────────────────────────────────────────────────────────

CREATE TABLE schema_registry.event_schemas (
    event_name         VARCHAR(255) NOT NULL,
    version            INT          NOT NULL,
    json_schema        JSONB        NOT NULL,

    -- The discipline this version was accepted under. VARCHAR not enum, per
    -- platform doctrine: new modes arrive by data migration, not code change.
    --
    --   BACKWARD — a new version must not break existing consumers. The
    --              default, and what the service once applied unconditionally
    --              to everything whatever its author intended.
    --   NONE     — evolution unchecked. Deliberately available for a contract
    --              under controlled rollout; recording the mode on the row
    --              makes the exemption visible rather than assumed.
    compatibility_mode VARCHAR(32)  NOT NULL DEFAULT 'BACKWARD',

    -- Without this the registry can say a contract changed but not who is
    -- responsible for it — the first question asked when one breaks.
    owning_service     VARCHAR(255),

    registered_by      VARCHAR(255) DEFAULT app.current_principal_id(),
    registered_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    PRIMARY KEY (event_name, version),

    -- json_schema is JSONB, so Postgres guarantees well-formed JSON — and
    -- nothing more. `123`, `"a string"`, `null` and `[]` are all valid JSONB,
    -- and the service's own check was json.Valid, which accepts every one.
    --
    -- A first version stored as `123` cannot be evolved: the next registration
    -- runs the compatibility check, the stored baseline fails to parse into a
    -- shape, and every future version of that event answers 400 forever. The
    -- registry accepted a value that permanently bricked the contract it
    -- recorded.
    CONSTRAINT event_schemas_json_schema_is_object
        CHECK (jsonb_typeof(json_schema) = 'object'),

    -- `{}` is an object that constrains nothing. A contract permitting every
    -- payload is not a contract, and recording one lets a producer claim its
    -- events are governed when nothing about them is specified.
    CONSTRAINT event_schemas_json_schema_not_empty
        CHECK (json_schema <> '{}'::jsonb),

    -- Versions are assigned by the registry and start at 1.
    CONSTRAINT event_schemas_version_positive
        CHECK (version >= 1),

    CONSTRAINT event_schemas_compatibility_mode_known
        CHECK (compatibility_mode IN ('BACKWARD', 'NONE')),

    -- The event name is this registry's primary key and was free text: any
    -- non-empty string was accepted. The convention every publisher on the
    -- platform already follows is dotted lowercase with at least two segments
    -- (jurisdiction.rule.updated).
    CONSTRAINT event_schemas_event_name_wellformed
        CHECK (event_name ~ '^[a-z][a-z0-9]*(\.[a-z0-9]+)+$')
);

CREATE INDEX idx_event_schemas_event_name
    ON schema_registry.event_schemas (event_name);

-- Serves "which contracts are exempt from compatibility checking" — the
-- question a governance reader asks of this table.
CREATE INDEX idx_event_schemas_compatibility_mode
    ON schema_registry.event_schemas (compatibility_mode)
    WHERE compatibility_mode <> 'BACKWARD';

CREATE INDEX idx_event_schemas_owning_service
    ON schema_registry.event_schemas (owning_service)
    WHERE owning_service IS NOT NULL;

-- ── Row-level security ───────────────────────────────────────────────────────

ALTER TABLE schema_registry.event_schemas ENABLE ROW LEVEL SECURITY;
ALTER TABLE schema_registry.event_schemas FORCE  ROW LEVEL SECURITY;

CREATE POLICY registry_read ON schema_registry.event_schemas
    FOR SELECT TO authenticated, zoiko_backend USING (true);

CREATE POLICY registry_append ON schema_registry.event_schemas
    FOR INSERT TO zoiko_backend WITH CHECK (true);

-- ── Grants ───────────────────────────────────────────────────────────────────

GRANT SELECT ON schema_registry.event_schemas TO authenticated;

-- SELECT and INSERT only. No UPDATE, no DELETE, to anyone — that is what
-- append-only means, and it is now enforced by the grant rather than asserted
-- in a comment.
GRANT SELECT, INSERT ON schema_registry.event_schemas TO zoiko_backend;


-- ============================================================================
-- FILE: 0009_governance_decision_log_svc.sql
-- ============================================================================

-- 0009_governance_decision_log_svc.sql
-- governance-decision-log-svc → schema `governance_decision_log`
--
-- Squashed end state of 000001_initial_schema, 000002_add_rls,
-- 000003_enforce_immutability, 000004_add_event_linkage_keys and
-- 000005_add_replay_manifests. Two tables: governance_decisions,
-- replay_manifests.
--
-- ── Why the immutability TRIGGERS are kept, not replaced by grants ───────────
-- Both tables are append-only evidence. Elsewhere in this migration set that is
-- enforced by withholding the UPDATE/DELETE grant, which is sufficient because
-- zoiko_backend is an ordinary role. It is NOT sufficient here, and 000003 says
-- why: a privileged role bypasses privilege checks and row-level security
-- entirely, but it does NOT bypass a BEFORE trigger.
--
-- On Supabase that argument gets stronger rather than weaker. The `service_role`
-- key carries BYPASSRLS, so anything holding it is exempt from every policy in
-- this file — and these triggers are the only control in the whole schema that
-- still binds it. On the platform's canonical governance evidence log, that is
-- worth the cost of a trigger.
--
-- ── One gap this migration does NOT close ────────────────────────────────────
-- The service's CreateDecision handler takes tenant_id, actor_id AND decided_at
-- from the REQUEST BODY, authorising against X-Principal-Id but never
-- reconciling any of the three with it. So an authorised principal can append a
-- decision to any tenant, attributed to anyone, dated anything. The DEFAULT on
-- actor_id below is a backstop for other writers only — it cannot fire while
-- the handler passes an explicit value. Fixing it is a handler change.

CREATE SCHEMA IF NOT EXISTS governance_decision_log;

COMMENT ON SCHEMA governance_decision_log IS
    'governance-decision-log-svc. Append-only governance evidence: decisions and the replay manifests that reproduce them.';

GRANT USAGE ON SCHEMA governance_decision_log TO zoiko_backend, authenticated;

-- ── governance_decisions ─────────────────────────────────────────────────────
-- Append-only. No UPDATE, no DELETE — ever. A correction is a NEW decision
-- record referencing the original through evaluation_context, never a mutation
-- of this row.

CREATE TABLE governance_decision_log.governance_decisions (
    decision_id          VARCHAR(64)  PRIMARY KEY,
    tenant_id            VARCHAR(64)  NOT NULL,
    legal_entity_id      VARCHAR(64)  NOT NULL,

    -- See the header: the handler supplies this from the body today, so the
    -- default is a backstop for direct writers rather than the live behaviour.
    actor_id             VARCHAR(64)  NOT NULL DEFAULT app.current_principal_id(),

    action_type          VARCHAR(128) NOT NULL,
    outcome              VARCHAR(32)  NOT NULL,
    rule_basis           VARCHAR(256) NOT NULL,
    evaluation_context   JSONB,
    correlation_id       VARCHAR(64)  NOT NULL,

    -- Event Linkage Keys. Previously buried in the evaluation_context JSONB
    -- catch-all; promoted to columns because "find every decision made during
    -- workflow instance X" and "find the decision this event caused" are real
    -- queries on the platform's canonical evidence log and nothing could answer
    -- them without a JSONB scan. Both nullable — a decision may not be
    -- workflow-triggered, and causation is not always known.
    workflow_instance_id TEXT,
    causation_id         TEXT,

    decided_at           TIMESTAMPTZ  NOT NULL,
    stored_at            TIMESTAMPTZ  NOT NULL DEFAULT NOW()
);

-- Serves the five-filter query contract: actor, entity, action, rule basis,
-- time range.
CREATE INDEX idx_governance_decisions_tenant_entity
    ON governance_decision_log.governance_decisions (tenant_id, legal_entity_id);
CREATE INDEX idx_governance_decisions_actor
    ON governance_decision_log.governance_decisions (actor_id);
CREATE INDEX idx_governance_decisions_action_type
    ON governance_decision_log.governance_decisions (action_type);
CREATE INDEX idx_governance_decisions_rule_basis
    ON governance_decision_log.governance_decisions (rule_basis);
CREATE INDEX idx_governance_decisions_decided_at
    ON governance_decision_log.governance_decisions (decided_at);
CREATE INDEX idx_governance_decisions_workflow_instance
    ON governance_decision_log.governance_decisions (workflow_instance_id)
    WHERE workflow_instance_id IS NOT NULL;

-- ── replay_manifests ─────────────────────────────────────────────────────────
-- A governance decision's basis must be REPRODUCIBLE: replayable against the
-- exact policy version and facts that produced it, not against whatever policy
-- is active now. rule_basis already encodes "policy_code:policy_version_id" and
-- evaluation_context already stores the facts; this table records that a replay
-- happened and whether it reproduced the original outcome.

CREATE TABLE governance_decision_log.replay_manifests (
    replay_manifest_id       UUID        PRIMARY KEY DEFAULT gen_random_uuid(),

    decision_id              VARCHAR(64) NOT NULL
        REFERENCES governance_decision_log.governance_decisions(decision_id),

    -- The exact policy version replayed against — parsed from the decision's
    -- rule_basis at replay time and stored explicitly, so a manifest is
    -- self-describing without re-parsing rule_basis later.
    policy_version_id        VARCHAR(64) NOT NULL,

    -- Same vocabulary as governance_decisions.outcome. Data only.
    replayed_outcome         VARCHAR(64) NOT NULL,
    original_outcome         VARCHAR(64) NOT NULL,

    -- Denormalised from (replayed_outcome = original_outcome) at write time. A
    -- manifest is a permanent record of what was FOUND, not a live comparison
    -- that could drift if either column were later reinterpreted.
    outcomes_match           BOOLEAN     NOT NULL,

    replay_notes             TEXT,
    replayed_at              TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    replayed_by_principal_id TEXT        NOT NULL DEFAULT app.current_principal_id()
);

CREATE INDEX idx_replay_manifests_decision
    ON governance_decision_log.replay_manifests (decision_id, replayed_at DESC);

-- ── Immutability ─────────────────────────────────────────────────────────────
-- app.reject_mutation() is defined once in the platform foundation rather than
-- copied per service, which is what the compose migrations grew into — two
-- near-identical functions in this service alone. TG_TABLE_SCHEMA and
-- TG_TABLE_NAME keep the message specific without a per-table copy.

CREATE TRIGGER governance_decisions_immutable
    BEFORE UPDATE OR DELETE ON governance_decision_log.governance_decisions
    FOR EACH ROW EXECUTE FUNCTION app.reject_mutation();

CREATE TRIGGER replay_manifests_immutable
    BEFORE UPDATE OR DELETE ON governance_decision_log.replay_manifests
    FOR EACH ROW EXECUTE FUNCTION app.reject_mutation();

-- ── Row-level security ───────────────────────────────────────────────────────
-- tenant_id is NOT NULL on every decision — no global or shared decisions
-- exist — so the policy is a plain equality with no NULL carve-out.
--
-- replay_manifests carries no tenant_id of its own. It is reachable only
-- through a decision_id, so its policy is an EXISTS against the parent, which
-- is itself subject to the policy above: a manifest whose decision is invisible
-- to this tenant is invisible too.

ALTER TABLE governance_decision_log.governance_decisions ENABLE ROW LEVEL SECURITY;
ALTER TABLE governance_decision_log.governance_decisions FORCE  ROW LEVEL SECURITY;
ALTER TABLE governance_decision_log.replay_manifests     ENABLE ROW LEVEL SECURITY;
ALTER TABLE governance_decision_log.replay_manifests     FORCE  ROW LEVEL SECURITY;

CREATE POLICY tenant_isolation ON governance_decision_log.governance_decisions
    FOR ALL
    TO zoiko_backend
    USING      (tenant_id = app.current_tenant_id())
    WITH CHECK (tenant_id = app.current_tenant_id());

CREATE POLICY tenant_read ON governance_decision_log.governance_decisions
    FOR SELECT
    TO authenticated
    USING (tenant_id = app.current_tenant_id());

CREATE POLICY tenant_isolation ON governance_decision_log.replay_manifests
    FOR ALL
    TO zoiko_backend
    USING (EXISTS (
        SELECT 1 FROM governance_decision_log.governance_decisions d
        WHERE d.decision_id = replay_manifests.decision_id))
    WITH CHECK (EXISTS (
        SELECT 1 FROM governance_decision_log.governance_decisions d
        WHERE d.decision_id = replay_manifests.decision_id));

CREATE POLICY tenant_read ON governance_decision_log.replay_manifests
    FOR SELECT
    TO authenticated
    USING (EXISTS (
        SELECT 1 FROM governance_decision_log.governance_decisions d
        WHERE d.decision_id = replay_manifests.decision_id));

-- ── Grants ───────────────────────────────────────────────────────────────────

GRANT SELECT ON governance_decision_log.governance_decisions TO authenticated;
GRANT SELECT ON governance_decision_log.replay_manifests     TO authenticated;

-- SELECT and INSERT only. The triggers above would refuse a mutation anyway;
-- withholding the grant means an ordinary role is refused before the trigger is
-- even reached, and the trigger remains as the backstop for privileged ones.
GRANT SELECT, INSERT ON governance_decision_log.governance_decisions TO zoiko_backend;
GRANT SELECT, INSERT ON governance_decision_log.replay_manifests     TO zoiko_backend;


-- ============================================================================
-- FILE: 0010_configuration_feature_flag_svc.sql
-- ============================================================================

-- 0010_configuration_feature_flag_svc.sql
-- configuration-feature-flag-svc → schema `configuration_feature_flag`
--
-- End state of 000001_initial_schema (the service's only migration).
-- Two tables: config_entries, feature_flags.
--
-- ── Design carried over ──────────────────────────────────────────────────────
--   - No soft-delete and no UPDATE/DELETE on either table. A "change" is always
--     end-date the currently-effective row for a (key, environment, tenant_id)
--     scope and insert a new one, in the same transaction.
--   - tenant_id is NULLABLE: NULL means the global default for that environment.
--   - The partial unique index is a CONCURRENCY BACKSTOP the upsert transaction
--     relies on, not an optimisation.
--
-- ── The nullable tenant_id needs a policy shaped differently ─────────────────
-- Every other service in this set has NOT NULL tenant_id and a plain equality
-- policy. Here a NULL means "global", so reads must return global rows as well
-- as the caller's own — and that makes the WRITE side the interesting half.
--
-- If the write policy simply mirrored the read policy, ANY tenant could insert
-- a row with tenant_id NULL and change a global default for every other tenant.
-- That is a privilege escalation dressed as a config write. So the two clauses
-- are deliberately asymmetric:
--
--   USING      — global rows OR my own tenant's rows.
--   WITH CHECK — my own tenant's rows; a GLOBAL row may be written only by a
--                connection that has installed NO tenant at all.
--
-- The second half of that WITH CHECK is a narrow, deliberate carve-out to the
-- fail-closed rule the rest of this migration set follows. It is safe because
-- it grants strictly less than the alternative: a tenant connection can never
-- write a global, and a no-tenant connection can write ONLY globals (its own
-- tenant clause is NULL, which is not true). Platform-level config therefore
-- requires an explicitly platform-level connection.

CREATE SCHEMA IF NOT EXISTS configuration_feature_flag;

COMMENT ON SCHEMA configuration_feature_flag IS
    'configuration-feature-flag-svc. Versioned, effective-dated runtime config and feature flags. NULL tenant_id = global default for the environment.';

GRANT USAGE ON SCHEMA configuration_feature_flag TO zoiko_backend, authenticated;

-- ── config_entries ───────────────────────────────────────────────────────────

CREATE TABLE configuration_feature_flag.config_entries (
    config_id               UUID         PRIMARY KEY DEFAULT gen_random_uuid(),

    key                     VARCHAR(255) NOT NULL,

    -- JSONB over TEXT so structured values (objects, arrays, numbers, booleans)
    -- need no caller-side encoding tricks.
    value                   JSONB        NOT NULL,

    environment             VARCHAR(64)  NOT NULL,

    -- NULL = global default for this environment.
    tenant_id               UUID,

    -- The row with effective_to IS NULL for a given scope is the currently
    -- effective one.
    effective_from          TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    effective_to            TIMESTAMPTZ,

    created_by_principal_id TEXT         NOT NULL DEFAULT app.current_principal_id(),
    created_at              TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    CONSTRAINT config_entries_period_ordered
        CHECK (effective_to IS NULL OR effective_to > effective_from)
);

-- At most one currently-effective row per (key, environment, tenant_id) scope.
-- COALESCE so a NULL tenant participates rather than making every global row
-- distinct from every other — without it the "one effective global" rule would
-- not hold at all.
CREATE UNIQUE INDEX idx_config_entries_one_effective_per_scope
    ON configuration_feature_flag.config_entries (
        key,
        environment,
        COALESCE(tenant_id, '00000000-0000-0000-0000-000000000000'::UUID)
    )
    WHERE effective_to IS NULL;

CREATE INDEX idx_config_entries_scope
    ON configuration_feature_flag.config_entries (key, environment, tenant_id);

-- ── feature_flags ────────────────────────────────────────────────────────────

CREATE TABLE configuration_feature_flag.feature_flags (
    flag_id                 UUID         PRIMARY KEY DEFAULT gen_random_uuid(),

    key                     VARCHAR(255) NOT NULL,
    enabled                 BOOLEAN      NOT NULL,
    environment             VARCHAR(64)  NOT NULL,

    -- NULL = global default for this environment.
    tenant_id               UUID,

    rollout_percentage      INTEGER      NOT NULL DEFAULT 100
        CONSTRAINT chk_feature_flags_rollout_percentage_range
            CHECK (rollout_percentage BETWEEN 0 AND 100),

    effective_from          TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    effective_to            TIMESTAMPTZ,

    created_by_principal_id TEXT         NOT NULL DEFAULT app.current_principal_id(),
    created_at              TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    CONSTRAINT feature_flags_period_ordered
        CHECK (effective_to IS NULL OR effective_to > effective_from)
);

CREATE UNIQUE INDEX idx_feature_flags_one_effective_per_scope
    ON configuration_feature_flag.feature_flags (
        key,
        environment,
        COALESCE(tenant_id, '00000000-0000-0000-0000-000000000000'::UUID)
    )
    WHERE effective_to IS NULL;

CREATE INDEX idx_feature_flags_scope
    ON configuration_feature_flag.feature_flags (key, environment, tenant_id);

-- ── Row-level security ───────────────────────────────────────────────────────

ALTER TABLE configuration_feature_flag.config_entries ENABLE ROW LEVEL SECURITY;
ALTER TABLE configuration_feature_flag.config_entries FORCE  ROW LEVEL SECURITY;
ALTER TABLE configuration_feature_flag.feature_flags  ENABLE ROW LEVEL SECURITY;
ALTER TABLE configuration_feature_flag.feature_flags  FORCE  ROW LEVEL SECURITY;

CREATE POLICY tenant_isolation ON configuration_feature_flag.config_entries
    FOR ALL
    TO zoiko_backend
    USING (
        tenant_id IS NULL
        OR tenant_id::text = app.current_tenant_id()
    )
    WITH CHECK (
        (tenant_id IS NOT NULL AND tenant_id::text = app.current_tenant_id())
        OR (tenant_id IS NULL AND app.current_tenant_id() IS NULL)
    );

CREATE POLICY tenant_read ON configuration_feature_flag.config_entries
    FOR SELECT
    TO authenticated
    USING (tenant_id IS NULL OR tenant_id::text = app.current_tenant_id());

CREATE POLICY tenant_isolation ON configuration_feature_flag.feature_flags
    FOR ALL
    TO zoiko_backend
    USING (
        tenant_id IS NULL
        OR tenant_id::text = app.current_tenant_id()
    )
    WITH CHECK (
        (tenant_id IS NOT NULL AND tenant_id::text = app.current_tenant_id())
        OR (tenant_id IS NULL AND app.current_tenant_id() IS NULL)
    );

CREATE POLICY tenant_read ON configuration_feature_flag.feature_flags
    FOR SELECT
    TO authenticated
    USING (tenant_id IS NULL OR tenant_id::text = app.current_tenant_id());

-- ── Grants ───────────────────────────────────────────────────────────────────

GRANT SELECT ON configuration_feature_flag.config_entries TO authenticated;
GRANT SELECT ON configuration_feature_flag.feature_flags  TO authenticated;

-- UPDATE is granted because a change end-dates the currently-effective row
-- (setting effective_to) and inserts its replacement in the same transaction.
-- DELETE is granted to nobody: there is no soft-delete and no hard delete.
GRANT SELECT, INSERT, UPDATE ON configuration_feature_flag.config_entries TO zoiko_backend;
GRANT SELECT, INSERT, UPDATE ON configuration_feature_flag.feature_flags  TO zoiko_backend;


-- ============================================================================
-- FILE: 0011_purchase_order_svc.sql
-- ============================================================================

-- 0011_purchase_order_svc.sql
-- purchase-order-svc → schema `purchase_order`
--
-- End state of 000001_initial_schema (the service's only migration).
-- Two tables: purchase_orders, purchase_order_amendments. Plus the
-- purchase_order_number_seq sequence behind po_number.

CREATE SCHEMA IF NOT EXISTS purchase_order;

COMMENT ON SCHEMA purchase_order IS
    'purchase-order-svc. PO issuance, amendment and close, with an append-only amendment ledger.';

GRANT USAGE ON SCHEMA purchase_order TO zoiko_backend, authenticated;

CREATE SEQUENCE purchase_order.purchase_order_number_seq;

-- ── purchase_orders ──────────────────────────────────────────────────────────

CREATE TABLE purchase_order.purchase_orders (
    purchase_order_id      UUID          PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id              UUID          NOT NULL,
    legal_entity_id        UUID          NOT NULL,

    purchase_request_id    UUID,
    vendor_profile_id      UUID,

    po_number              VARCHAR(32)   NOT NULL,

    -- ISSUED | AMENDED | CLOSED
    po_status              VARCHAR(20)   NOT NULL,

    total_amount           NUMERIC(18,2) NOT NULL,
    currency_code          VARCHAR(3)    NOT NULL,

    -- Bumped on each amendment; the amendment ledger records from/to.
    version                INTEGER       NOT NULL DEFAULT 1,

    issued_by_principal_id VARCHAR(255)  NOT NULL DEFAULT app.current_principal_id(),
    closed_by_principal_id VARCHAR(255),

    correlation_id         VARCHAR(255)  NOT NULL,
    created_at             TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
    issued_at              TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
    closed_at              TIMESTAMPTZ,

    CONSTRAINT purchase_orders_version_positive
        CHECK (version >= 1),

    -- A closed order must say who closed it and when.
    CONSTRAINT purchase_orders_closed_has_evidence
        CHECK ((po_status = 'CLOSED') = (closed_at IS NOT NULL AND closed_by_principal_id IS NOT NULL))
);

CREATE INDEX idx_purchase_orders_tenant  ON purchase_order.purchase_orders (tenant_id);
CREATE INDEX idx_purchase_orders_entity  ON purchase_order.purchase_orders (legal_entity_id);
CREATE INDEX idx_purchase_orders_status  ON purchase_order.purchase_orders (po_status);
CREATE INDEX idx_purchase_orders_request ON purchase_order.purchase_orders (purchase_request_id);

-- Idempotency: a retried Issue must return the ORIGINAL order, never mint a
-- second one.
CREATE UNIQUE INDEX idx_purchase_orders_tenant_correlation
    ON purchase_order.purchase_orders (tenant_id, correlation_id);

-- po_number is human-facing and unique per TENANT, not globally — two tenants
-- may legitimately land on the same sequence value.
CREATE UNIQUE INDEX idx_purchase_orders_tenant_po_number
    ON purchase_order.purchase_orders (tenant_id, po_number);

-- Composite key the amendment ledger's foreign key points at, so an amendment
-- cannot reference an order belonging to a different tenant. See below.
CREATE UNIQUE INDEX idx_purchase_orders_id_tenant
    ON purchase_order.purchase_orders (purchase_order_id, tenant_id);

-- ── purchase_order_amendments ────────────────────────────────────────────────
-- Append-only. One row per amendment, preserving the full before/after value
-- rather than destructively overwriting total_amount.

CREATE TABLE purchase_order.purchase_order_amendments (
    amendment_id            UUID          PRIMARY KEY DEFAULT gen_random_uuid(),
    purchase_order_id       UUID          NOT NULL,
    tenant_id               UUID          NOT NULL,

    from_version            INTEGER       NOT NULL,
    to_version              INTEGER       NOT NULL,
    previous_total_amount   NUMERIC(18,2) NOT NULL,
    new_total_amount        NUMERIC(18,2) NOT NULL,
    reason                  TEXT          NOT NULL,

    amended_by_principal_id VARCHAR(255)  NOT NULL DEFAULT app.current_principal_id(),
    amended_at              TIMESTAMPTZ   NOT NULL DEFAULT NOW(),

    -- The compose schema referenced purchase_orders(purchase_order_id) alone
    -- and carried its own tenant_id, with nothing tying the two together — so
    -- an amendment could name one tenant while its order belonged to another,
    -- and the row would be invisible to the tenant whose order actually
    -- changed. The composite reference makes that unrepresentable.
    CONSTRAINT purchase_order_amendments_order_fk
        FOREIGN KEY (purchase_order_id, tenant_id)
        REFERENCES purchase_order.purchase_orders (purchase_order_id, tenant_id),

    CONSTRAINT purchase_order_amendments_version_advances
        CHECK (to_version > from_version)
);

CREATE INDEX idx_po_amendments_order  ON purchase_order.purchase_order_amendments (purchase_order_id);
CREATE INDEX idx_po_amendments_tenant ON purchase_order.purchase_order_amendments (tenant_id);

-- Material history: mutation here would destroy the record of what the order
-- was before, so this gets the trigger as well as the withheld grant.
CREATE TRIGGER purchase_order_amendments_immutable
    BEFORE UPDATE OR DELETE ON purchase_order.purchase_order_amendments
    FOR EACH ROW EXECUTE FUNCTION app.reject_mutation();

-- ── Row-level security ───────────────────────────────────────────────────────

ALTER TABLE purchase_order.purchase_orders            ENABLE ROW LEVEL SECURITY;
ALTER TABLE purchase_order.purchase_orders            FORCE  ROW LEVEL SECURITY;
ALTER TABLE purchase_order.purchase_order_amendments  ENABLE ROW LEVEL SECURITY;
ALTER TABLE purchase_order.purchase_order_amendments  FORCE  ROW LEVEL SECURITY;

CREATE POLICY tenant_isolation ON purchase_order.purchase_orders
    FOR ALL
    TO zoiko_backend
    USING      (tenant_id::text = app.current_tenant_id())
    WITH CHECK (tenant_id::text = app.current_tenant_id());

CREATE POLICY tenant_read ON purchase_order.purchase_orders
    FOR SELECT
    TO authenticated
    USING (tenant_id::text = app.current_tenant_id());

CREATE POLICY tenant_isolation ON purchase_order.purchase_order_amendments
    FOR ALL
    TO zoiko_backend
    USING      (tenant_id::text = app.current_tenant_id())
    WITH CHECK (tenant_id::text = app.current_tenant_id());

CREATE POLICY tenant_read ON purchase_order.purchase_order_amendments
    FOR SELECT
    TO authenticated
    USING (tenant_id::text = app.current_tenant_id());

-- ── Grants ───────────────────────────────────────────────────────────────────

GRANT SELECT ON purchase_order.purchase_orders           TO authenticated;
GRANT SELECT ON purchase_order.purchase_order_amendments TO authenticated;

GRANT SELECT, INSERT, UPDATE ON purchase_order.purchase_orders TO zoiko_backend;

-- Append-only: SELECT and INSERT only.
GRANT SELECT, INSERT ON purchase_order.purchase_order_amendments TO zoiko_backend;

GRANT USAGE ON SEQUENCE purchase_order.purchase_order_number_seq TO zoiko_backend;


-- ============================================================================
-- FILE: 0012_spend_controls_svc.sql
-- ============================================================================

-- 0012_spend_controls_svc.sql
-- spend-controls-svc → schema `spend_controls`
--
-- End state of 000001_initial_schema (the service's only migration).
-- Two tables: spend_policies, spend_consumptions.
--
-- ── The cross-currency comparison, made unrepresentable ──────────────────────
-- A consumption carries its own currency_code and so does the policy it is
-- recorded against, and nothing tied the two together: a 5,000 JPY spend could
-- be checked against a 5,000 GBP threshold and reported ALLOWED. Comparing two
-- amounts in different currencies is not a threshold check, it is a coincidence
-- of digits.
--
-- The composite foreign key below makes that shape impossible to store: a
-- consumption may only reference a policy whose currency is its own. It is a
-- backstop rather than the fix — the service should still refuse the request
-- with a clear error rather than a foreign-key violation — but the database no
-- longer holds a row asserting a comparison that was never valid.

CREATE SCHEMA IF NOT EXISTS spend_controls;

COMMENT ON SCHEMA spend_controls IS
    'spend-controls-svc. Spend thresholds by category and period, and the consumption ledger checked against them.';

GRANT USAGE ON SCHEMA spend_controls TO zoiko_backend, authenticated;

-- ── spend_policies ───────────────────────────────────────────────────────────

CREATE TABLE spend_controls.spend_policies (
    spend_policy_id         UUID          PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id               VARCHAR(255)  NOT NULL,
    legal_entity_id         VARCHAR(255)  NOT NULL,

    category                VARCHAR(100)  NOT NULL,

    -- PER_TRANSACTION | MONTHLY | ANNUAL
    period                  VARCHAR(20)   NOT NULL,

    threshold_amount        NUMERIC(18,4) NOT NULL CHECK (threshold_amount > 0),
    currency_code           VARCHAR(10)   NOT NULL,

    active_flag             BOOLEAN       NOT NULL DEFAULT TRUE,

    created_by_principal_id VARCHAR(255)  NOT NULL DEFAULT app.current_principal_id(),
    created_at              TIMESTAMPTZ   NOT NULL DEFAULT NOW(),
    updated_at              TIMESTAMPTZ   NOT NULL DEFAULT NOW(),

    CONSTRAINT spend_policies_period_known
        CHECK (period IN ('PER_TRANSACTION', 'MONTHLY', 'ANNUAL'))
);

CREATE INDEX idx_spend_policies_tenant_entity_category
    ON spend_controls.spend_policies (tenant_id, legal_entity_id, category);

-- Composite keys the consumption ledger's foreign key points at: one binds the
-- currency, the other binds the tenant. Both are needed to keep a consumption
-- from referencing a policy it has no business being measured against.
CREATE UNIQUE INDEX idx_spend_policies_id_currency
    ON spend_controls.spend_policies (spend_policy_id, currency_code);
CREATE UNIQUE INDEX idx_spend_policies_id_tenant
    ON spend_controls.spend_policies (spend_policy_id, tenant_id);

-- ── spend_consumptions ───────────────────────────────────────────────────────

CREATE TABLE spend_controls.spend_consumptions (
    consumption_id           UUID          PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id                VARCHAR(255)  NOT NULL,
    legal_entity_id          VARCHAR(255)  NOT NULL,

    spend_policy_id          UUID          NOT NULL,

    amount                   NUMERIC(18,4) NOT NULL CHECK (amount > 0),
    currency_code            VARCHAR(10)   NOT NULL,

    source_reference         VARCHAR(255),
    correlation_id           VARCHAR(255)  NOT NULL,

    -- ALLOWED | BLOCKED
    decision_outcome         VARCHAR(20)   NOT NULL,

    recorded_by_principal_id VARCHAR(255)  NOT NULL DEFAULT app.current_principal_id(),
    recorded_at              TIMESTAMPTZ   NOT NULL DEFAULT NOW(),

    CONSTRAINT spend_consumptions_outcome_known
        CHECK (decision_outcome IN ('ALLOWED', 'BLOCKED')),

    -- A consumption may only be recorded against a policy in the SAME currency.
    CONSTRAINT spend_consumptions_policy_currency_fk
        FOREIGN KEY (spend_policy_id, currency_code)
        REFERENCES spend_controls.spend_policies (spend_policy_id, currency_code)
        ON DELETE CASCADE,

    -- ...and only against a policy belonging to the SAME tenant. The compose
    -- schema referenced the policy id alone and carried its own tenant_id, so
    -- a consumption could be booked against another tenant's threshold.
    CONSTRAINT spend_consumptions_policy_tenant_fk
        FOREIGN KEY (spend_policy_id, tenant_id)
        REFERENCES spend_controls.spend_policies (spend_policy_id, tenant_id)
        ON DELETE CASCADE
);

-- Idempotency: a retried spend-check resolves to the original consumption
-- record, never a duplicate — which would otherwise consume the budget twice.
CREATE UNIQUE INDEX idx_spend_consumptions_tenant_correlation
    ON spend_controls.spend_consumptions (tenant_id, correlation_id);

CREATE INDEX idx_spend_consumptions_tenant_policy
    ON spend_controls.spend_consumptions (tenant_id, spend_policy_id, recorded_at);

-- ── Row-level security ───────────────────────────────────────────────────────

ALTER TABLE spend_controls.spend_policies     ENABLE ROW LEVEL SECURITY;
ALTER TABLE spend_controls.spend_policies     FORCE  ROW LEVEL SECURITY;
ALTER TABLE spend_controls.spend_consumptions ENABLE ROW LEVEL SECURITY;
ALTER TABLE spend_controls.spend_consumptions FORCE  ROW LEVEL SECURITY;

CREATE POLICY tenant_isolation ON spend_controls.spend_policies
    FOR ALL
    TO zoiko_backend
    USING      (tenant_id = app.current_tenant_id())
    WITH CHECK (tenant_id = app.current_tenant_id());

CREATE POLICY tenant_read ON spend_controls.spend_policies
    FOR SELECT
    TO authenticated
    USING (tenant_id = app.current_tenant_id());

CREATE POLICY tenant_isolation ON spend_controls.spend_consumptions
    FOR ALL
    TO zoiko_backend
    USING      (tenant_id = app.current_tenant_id())
    WITH CHECK (tenant_id = app.current_tenant_id());

CREATE POLICY tenant_read ON spend_controls.spend_consumptions
    FOR SELECT
    TO authenticated
    USING (tenant_id = app.current_tenant_id());

-- ── Grants ───────────────────────────────────────────────────────────────────

GRANT SELECT ON spend_controls.spend_policies     TO authenticated;
GRANT SELECT ON spend_controls.spend_consumptions TO authenticated;

GRANT SELECT, INSERT, UPDATE ON spend_controls.spend_policies TO zoiko_backend;

-- The consumption ledger is the record of what was checked and decided; a row
-- is never edited after the fact.
GRANT SELECT, INSERT ON spend_controls.spend_consumptions TO zoiko_backend;


-- ============================================================================
-- FILE: 0013_vendor_due_diligence_svc.sql
-- ============================================================================

-- 0013_vendor_due_diligence_svc.sql
-- vendor-due-diligence-svc → schema `vendor_due_diligence`
--
-- Squashed end state of 000001_initial_schema and 000002_screening_source.
-- Two tables: vendor_dd_checks, vendor_dd_evidence.
--
-- The two backfill UPDATEs in 000002 are dropped rather than translated: one
-- stamped screening_source on already-COMPLETED rows, the other normalised
-- empty-string document_reference to NULL. Both correct data written before
-- those rules existed, and this database has none.

CREATE SCHEMA IF NOT EXISTS vendor_due_diligence;

COMMENT ON SCHEMA vendor_due_diligence IS
    'vendor-due-diligence-svc. Counterparty screening checks and the evidence recorded against them.';

GRANT USAGE ON SCHEMA vendor_due_diligence TO zoiko_backend, authenticated;

-- ── vendor_dd_checks ─────────────────────────────────────────────────────────

CREATE TABLE vendor_due_diligence.vendor_dd_checks (
    check_id                  UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id                 VARCHAR(255) NOT NULL,
    legal_entity_id           VARCHAR(255) NOT NULL,

    counterparty_id           VARCHAR(255) NOT NULL,
    vendor_name               VARCHAR(255) NOT NULL,

    -- STARTED | COMPLETED | FAILED
    status                    VARCHAR(20)  NOT NULL,

    -- CLEAR | FLAGGED — NULL until the check concludes.
    risk_outcome              VARCHAR(20),

    screening_basis           TEXT,

    -- WHICH screening produced the outcome. Without it, CLEAR is
    -- indistinguishable from a real sanctions clearance — and it is not one:
    -- the only screening this service performs is an exact, case-insensitive
    -- match against a hardcoded list of two names. There is no sanctions feed
    -- on the platform to call (external-data-feed-svc carries MARKET_DATA,
    -- CREDIT_SCORE, COMPANY_INFO, FX_RATE and ESG_DATA only).
    --
    -- A consumer cannot avoid over-reading CLEAR unless the record says what
    -- ran, and parsing that out of screening_basis prose is not a contract.
    -- When a real feed is integrated it becomes a second value here and every
    -- historical row stays honest about having been screened by the stub.
    screening_source          VARCHAR(50),

    correlation_id            VARCHAR(255) NOT NULL,
    initiated_by_principal_id VARCHAR(255) NOT NULL DEFAULT app.current_principal_id(),
    started_at                TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    completed_at              TIMESTAMPTZ,

    -- The state machine the handler applies, enforced. Without it a partially
    -- applied conclusion is representable — and one was: a completion that
    -- failed midway left STARTED rows the register could not distinguish from
    -- anything else.
    --
    -- `risk_outcome IS NOT NULL` is NOT redundant beside the IN list. A CHECK
    -- rejects a row only when its expression is FALSE, and
    -- `NULL IN ('CLEAR','FLAGGED')` is NULL — so with the IN test alone the
    -- COMPLETED branch went NULL, the disjunction went FALSE OR FALSE OR NULL
    -- = NULL, and a COMPLETED check carrying no outcome at all was accepted.
    -- Which is exactly the state this constraint exists to forbid.
    CONSTRAINT vendor_dd_checks_outcome_requires_conclusion
        CHECK (
            (status = 'STARTED'   AND risk_outcome IS NULL AND completed_at IS NULL)
         OR (status = 'FAILED'    AND risk_outcome IS NULL AND completed_at IS NOT NULL)
         OR (status = 'COMPLETED' AND risk_outcome IS NOT NULL
                                  AND risk_outcome IN ('CLEAR', 'FLAGGED')
                                  AND completed_at IS NOT NULL)
        ),

    -- A concluded check must say what screened it. New here: on the compose
    -- estate the column is nullable for rows that predate it, which this
    -- database has none of.
    CONSTRAINT vendor_dd_checks_concluded_names_source
        CHECK (status = 'STARTED' OR screening_source IS NOT NULL),

    -- A blank vendor name is not a vendor. The service refuses one at the
    -- boundary; this is the backstop for any other writer.
    CONSTRAINT vendor_dd_checks_vendor_name_present
        CHECK (btrim(vendor_name) <> '')
);

-- Idempotency: a retried start resolves to the original check, never a second,
-- divergent one.
CREATE UNIQUE INDEX idx_vendor_dd_checks_tenant_correlation
    ON vendor_due_diligence.vendor_dd_checks (tenant_id, correlation_id);

CREATE INDEX idx_vendor_dd_checks_tenant_entity
    ON vendor_due_diligence.vendor_dd_checks (tenant_id, legal_entity_id);
CREATE INDEX idx_vendor_dd_checks_tenant_counterparty
    ON vendor_due_diligence.vendor_dd_checks (tenant_id, counterparty_id);

-- Composite key the evidence table's foreign key points at, so a piece of
-- evidence cannot be attached to another tenant's check.
CREATE UNIQUE INDEX idx_vendor_dd_checks_id_tenant
    ON vendor_due_diligence.vendor_dd_checks (check_id, tenant_id);

-- ── vendor_dd_evidence ───────────────────────────────────────────────────────

CREATE TABLE vendor_due_diligence.vendor_dd_evidence (
    evidence_id        UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    check_id           UUID         NOT NULL,
    tenant_id          VARCHAR(255) NOT NULL,

    evidence_type      VARCHAR(100) NOT NULL,
    description        TEXT         NOT NULL,

    -- NULL means "no document", not "a document whose reference is blank".
    -- 000001 shipped this column with nothing ever writing to it, so every row
    -- held the empty string and the two cases were indistinguishable. The
    -- constraint keeps them apart from here on.
    document_reference VARCHAR(255),

    recorded_at        TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    CONSTRAINT vendor_dd_evidence_document_reference_not_blank
        CHECK (document_reference IS NULL OR btrim(document_reference) <> ''),

    -- Composite, so evidence and its check always agree on the tenant.
    CONSTRAINT vendor_dd_evidence_check_fk
        FOREIGN KEY (check_id, tenant_id)
        REFERENCES vendor_due_diligence.vendor_dd_checks (check_id, tenant_id)
        ON DELETE CASCADE
);

CREATE INDEX idx_vendor_dd_evidence_check
    ON vendor_due_diligence.vendor_dd_evidence (check_id);

-- ── Row-level security ───────────────────────────────────────────────────────

ALTER TABLE vendor_due_diligence.vendor_dd_checks   ENABLE ROW LEVEL SECURITY;
ALTER TABLE vendor_due_diligence.vendor_dd_checks   FORCE  ROW LEVEL SECURITY;
ALTER TABLE vendor_due_diligence.vendor_dd_evidence ENABLE ROW LEVEL SECURITY;
ALTER TABLE vendor_due_diligence.vendor_dd_evidence FORCE  ROW LEVEL SECURITY;

CREATE POLICY tenant_isolation ON vendor_due_diligence.vendor_dd_checks
    FOR ALL
    TO zoiko_backend
    USING      (tenant_id = app.current_tenant_id())
    WITH CHECK (tenant_id = app.current_tenant_id());

CREATE POLICY tenant_read ON vendor_due_diligence.vendor_dd_checks
    FOR SELECT
    TO authenticated
    USING (tenant_id = app.current_tenant_id());

CREATE POLICY tenant_isolation ON vendor_due_diligence.vendor_dd_evidence
    FOR ALL
    TO zoiko_backend
    USING      (tenant_id = app.current_tenant_id())
    WITH CHECK (tenant_id = app.current_tenant_id());

CREATE POLICY tenant_read ON vendor_due_diligence.vendor_dd_evidence
    FOR SELECT
    TO authenticated
    USING (tenant_id = app.current_tenant_id());

-- ── Grants ───────────────────────────────────────────────────────────────────

GRANT SELECT ON vendor_due_diligence.vendor_dd_checks   TO authenticated;
GRANT SELECT ON vendor_due_diligence.vendor_dd_evidence TO authenticated;

GRANT SELECT, INSERT, UPDATE ON vendor_due_diligence.vendor_dd_checks TO zoiko_backend;

-- Evidence is recorded, not revised: a conclusion must not be able to outlive
-- the evidence that supported it.
GRANT SELECT, INSERT ON vendor_due_diligence.vendor_dd_evidence TO zoiko_backend;


-- ============================================================================
-- FILE: 0014_evidence_requirements_svc.sql
-- ============================================================================

-- 0014_evidence_requirements_svc.sql
-- evidence-requirements-svc → schema `evidence_requirements`
--
-- End state of 000001_initial_schema (the service's only migration).
-- Two tables: evidence_requirements, evidence_evaluations.

CREATE SCHEMA IF NOT EXISTS evidence_requirements;

COMMENT ON SCHEMA evidence_requirements IS
    'evidence-requirements-svc. Evidence preconditions per (entity, domain, action) and the append-only ledger of gate determinations.';

GRANT USAGE ON SCHEMA evidence_requirements TO zoiko_backend, authenticated;

-- ── evidence_requirements ────────────────────────────────────────────────────

CREATE TABLE evidence_requirements.evidence_requirements (
    evidence_requirement_id UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id               UUID         NOT NULL,

    -- NULLABLE, and the NULL is meaningful: the requirement applies
    -- tenant-wide. A non-NULL value scopes it to one legal entity, which is
    -- what an entity-specific regulatory precondition needs.
    legal_entity_id         UUID,

    domain_code             VARCHAR(64)  NOT NULL,
    action_type             VARCHAR(64)  NOT NULL,
    evidence_type           VARCHAR(64)  NOT NULL,

    -- Sufficiency parameters as DATA (minimum_count, artifact_subtype,
    -- description). This column is what keeps the doctrine rule "no service may
    -- hardcode a country, jurisdiction, currency or tax-rule value as a code
    -- constant, enum or switch/case branch" satisfiable: adding a jurisdiction
    -- that demands a notarised signature is an INSERT, never a redeploy.
    requirement_payload     JSONB        NOT NULL DEFAULT '{}',

    -- Effective dating is the retirement mechanism. There is no is_deleted flag
    -- and no DELETE path.
    effective_from          TIMESTAMPTZ  NOT NULL,
    effective_to            TIMESTAMPTZ,

    -- Provenance: a governance rule whose author is unknown is not useful
    -- evidence.
    created_at              TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    created_by_principal_id VARCHAR(255) NOT NULL DEFAULT app.current_principal_id(),
    retired_by_principal_id VARCHAR(255),
    retired_reason          TEXT,

    correlation_id          VARCHAR(255) NOT NULL,

    CONSTRAINT evidence_requirements_period_ordered
        CHECK (effective_to IS NULL OR effective_to > effective_from),

    -- A retired requirement must say who retired it. Retirement IS the
    -- end-dating, so the two travel together.
    CONSTRAINT evidence_requirements_retired_has_actor
        CHECK (effective_to IS NULL OR retired_by_principal_id IS NOT NULL)
);

CREATE INDEX idx_evidence_requirements_tenant
    ON evidence_requirements.evidence_requirements (tenant_id);
CREATE INDEX idx_evidence_requirements_entity
    ON evidence_requirements.evidence_requirements (legal_entity_id);

-- The evaluator's hot path: every requirement in force for one
-- (tenant, domain, action) at a point in time.
CREATE INDEX idx_evidence_requirements_lookup
    ON evidence_requirements.evidence_requirements
       (tenant_id, domain_code, action_type, effective_from, effective_to);

-- Idempotency: a retried create returns the original requirement rather than
-- minting a second. A real DB-level constraint, not a convention — most
-- services on this platform store correlation_id without constraining it, so
-- their retries silently duplicate.
CREATE UNIQUE INDEX idx_evidence_requirements_tenant_correlation
    ON evidence_requirements.evidence_requirements (tenant_id, correlation_id);

-- Natural key: one requirement per (entity scope, domain, action, evidence
-- type) per effective_from.
--
-- COALESCE is load-bearing. Postgres treats NULLs as distinct in a unique
-- index, so naming legal_entity_id directly would allow unlimited duplicate
-- tenant-wide rows for the same triple — exactly what this index exists to
-- prevent. Folding NULL onto the zero UUID makes tenant-wide rows compare
-- equal to each other.
CREATE UNIQUE INDEX idx_evidence_requirements_natural_key
    ON evidence_requirements.evidence_requirements (
        tenant_id,
        COALESCE(legal_entity_id, '00000000-0000-0000-0000-000000000000'::UUID),
        domain_code,
        action_type,
        evidence_type,
        effective_from
    );

-- ── evidence_evaluations ─────────────────────────────────────────────────────
-- Append-only determination ledger. This table is why the service is evidential
-- about ITSELF rather than only enforcing evidence on others: every gate
-- decision is recorded with the requirements that were unmet and the artifacts
-- the caller asserted, frozen at decision time so the record stays truthful
-- after the catalogue changes underneath it.

CREATE TABLE evidence_requirements.evidence_evaluations (
    evaluation_id              UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id                  UUID         NOT NULL,
    legal_entity_id            UUID         NOT NULL,
    domain_code                VARCHAR(64)  NOT NULL,
    action_type                VARCHAR(64)  NOT NULL,

    -- SATISFIED | MISSING | NO_REQUIREMENTS_DEFINED. The third value is
    -- deliberate: an empty catalogue is a legitimate data state and must not be
    -- recorded as SATISFIED, which would make "nobody configured this yet"
    -- indistinguishable from "verified complete".
    outcome                    VARCHAR(32)  NOT NULL,

    unmet_payload              JSONB        NOT NULL DEFAULT '[]',
    present_artifacts_payload  JSONB        NOT NULL DEFAULT '[]',

    evaluated_at               TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    evaluated_for_principal_id VARCHAR(255) NOT NULL,
    correlation_id             VARCHAR(255) NOT NULL,

    -- The gate used to fail OPEN on anything it did not recognise; naming the
    -- vocabulary keeps an unknown outcome from being stored and later read as
    -- a pass.
    CONSTRAINT evidence_evaluations_outcome_known
        CHECK (outcome IN ('SATISFIED', 'MISSING', 'NO_REQUIREMENTS_DEFINED')),

    -- A MISSING determination must say what was missing, or it is not a
    -- determination.
    CONSTRAINT evidence_evaluations_missing_names_unmet
        CHECK (outcome <> 'MISSING' OR jsonb_array_length(unmet_payload) > 0)
);

CREATE INDEX idx_evidence_evaluations_tenant
    ON evidence_requirements.evidence_evaluations (tenant_id);
CREATE INDEX idx_evidence_evaluations_action
    ON evidence_requirements.evidence_evaluations
       (tenant_id, domain_code, action_type, evaluated_at DESC);
CREATE INDEX idx_evidence_evaluations_outcome
    ON evidence_requirements.evidence_evaluations (outcome);

-- Replay safety: an evaluation retried with the same correlation_id returns the
-- original determination and does not republish its event.
CREATE UNIQUE INDEX idx_evidence_evaluations_tenant_correlation
    ON evidence_requirements.evidence_evaluations (tenant_id, correlation_id);

-- A determination is evidence of what was decided at a moment. Mutating one
-- rewrites the answer a gate gave, so this carries the trigger as well as the
-- withheld grant.
CREATE TRIGGER evidence_evaluations_immutable
    BEFORE UPDATE OR DELETE ON evidence_requirements.evidence_evaluations
    FOR EACH ROW EXECUTE FUNCTION app.reject_mutation();

-- ── Row-level security ───────────────────────────────────────────────────────

ALTER TABLE evidence_requirements.evidence_requirements ENABLE ROW LEVEL SECURITY;
ALTER TABLE evidence_requirements.evidence_requirements FORCE  ROW LEVEL SECURITY;
ALTER TABLE evidence_requirements.evidence_evaluations  ENABLE ROW LEVEL SECURITY;
ALTER TABLE evidence_requirements.evidence_evaluations  FORCE  ROW LEVEL SECURITY;

CREATE POLICY tenant_isolation ON evidence_requirements.evidence_requirements
    FOR ALL
    TO zoiko_backend
    USING      (tenant_id::text = app.current_tenant_id())
    WITH CHECK (tenant_id::text = app.current_tenant_id());

CREATE POLICY tenant_read ON evidence_requirements.evidence_requirements
    FOR SELECT
    TO authenticated
    USING (tenant_id::text = app.current_tenant_id());

CREATE POLICY tenant_isolation ON evidence_requirements.evidence_evaluations
    FOR ALL
    TO zoiko_backend
    USING      (tenant_id::text = app.current_tenant_id())
    WITH CHECK (tenant_id::text = app.current_tenant_id());

CREATE POLICY tenant_read ON evidence_requirements.evidence_evaluations
    FOR SELECT
    TO authenticated
    USING (tenant_id::text = app.current_tenant_id());

-- ── Grants ───────────────────────────────────────────────────────────────────

GRANT SELECT ON evidence_requirements.evidence_requirements TO authenticated;
GRANT SELECT ON evidence_requirements.evidence_evaluations  TO authenticated;

-- UPDATE on requirements is the retirement path (setting effective_to and
-- retired_by); there is no DELETE.
GRANT SELECT, INSERT, UPDATE ON evidence_requirements.evidence_requirements TO zoiko_backend;
GRANT SELECT, INSERT         ON evidence_requirements.evidence_evaluations  TO zoiko_backend;


-- ============================================================================
-- FILE: 0015_general_ledger_svc.sql
-- ============================================================================

-- 0015_general_ledger_svc.sql
-- general-ledger-svc → schema `general_ledger`
--
-- Squashed end state of 000001_initial_schema, 000002_add_idempotency_index
-- and 000003_add_atomic_linking. Two tables: journal_headers, journal_lines.
--
-- No chart_of_accounts table: no Chart-of-Accounts service exists anywhere on
-- the platform, so account_code is a plain, unvalidated string — a documented
-- v1 gap, not an oversight.

CREATE SCHEMA IF NOT EXISTS general_ledger;

COMMENT ON SCHEMA general_ledger IS
    'general-ledger-svc. Double-entry journal headers and their append-only lines. Corrections are reversing journals, never edits.';

GRANT USAGE ON SCHEMA general_ledger TO zoiko_backend, authenticated;

-- ── journal_headers ──────────────────────────────────────────────────────────

CREATE TABLE general_ledger.journal_headers (
    journal_id                UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id                 UUID         NOT NULL,
    legal_entity_id           UUID         NOT NULL,

    fiscal_period             VARCHAR(20)  NOT NULL,

    -- DRAFT | VALIDATED | POSTED | REVERSED
    status                    VARCHAR(20)  NOT NULL,

    -- The link from a reversing journal back to what it reverses. Without it a
    -- reversal is just another journal that happens to carry opposite signs,
    -- and nothing can state which entry corrected which.
    reversal_of_journal_id    UUID         REFERENCES general_ledger.journal_headers(journal_id),

    description               TEXT         NOT NULL,

    created_by_principal_id   VARCHAR(255) NOT NULL DEFAULT app.current_principal_id(),
    validated_by_principal_id VARCHAR(255),
    posted_by_principal_id    VARCHAR(255),
    reversed_by_principal_id  VARCHAR(255),

    -- Atomic Linking: carry the upstream event and the governing decision that
    -- caused this posting WHERE ONE EXISTS. Both nullable — a manually entered
    -- journal has neither, and Atomic Linking means "carry the link when there
    -- is one", not "fabricate one when there isn't".
    source_event_id           TEXT,
    governance_decision_id    TEXT,

    correlation_id            VARCHAR(255) NOT NULL,
    created_at                TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    validated_at              TIMESTAMPTZ,
    posted_at                 TIMESTAMPTZ,
    reversed_at               TIMESTAMPTZ,

    -- Each transition must carry its evidence. A POSTED journal with no
    -- posted_at or no posting principal is an entry in the books that nobody
    -- is recorded as having made.
    CONSTRAINT journal_headers_validated_has_evidence
        CHECK (validated_at IS NULL OR validated_by_principal_id IS NOT NULL),
    CONSTRAINT journal_headers_posted_has_evidence
        CHECK (posted_at IS NULL OR posted_by_principal_id IS NOT NULL),
    CONSTRAINT journal_headers_reversed_has_evidence
        CHECK (reversed_at IS NULL OR reversed_by_principal_id IS NOT NULL),

    -- A journal cannot reverse itself.
    CONSTRAINT journal_headers_not_self_reversal
        CHECK (reversal_of_journal_id IS NULL OR reversal_of_journal_id <> journal_id)
);

CREATE INDEX idx_journal_headers_tenant
    ON general_ledger.journal_headers (tenant_id);
CREATE INDEX idx_journal_headers_entity_period
    ON general_ledger.journal_headers (legal_entity_id, fiscal_period);
CREATE INDEX idx_journal_headers_status
    ON general_ledger.journal_headers (status);

-- Idempotency: a retried CreateJournal returns the ORIGINAL journal rather than
-- posting a second one. Partial because correlation_id was once optional and an
-- empty string must never collide across genuinely different journals.
CREATE UNIQUE INDEX idx_journal_headers_tenant_correlation
    ON general_ledger.journal_headers (tenant_id, correlation_id)
    WHERE correlation_id != '';

-- A journal may be reversed once. Without this, two concurrent reversals of the
-- same entry both succeed and the books are corrected twice — the non-atomic
-- reversal that double-counted.
CREATE UNIQUE INDEX idx_journal_headers_one_reversal_per_journal
    ON general_ledger.journal_headers (reversal_of_journal_id)
    WHERE reversal_of_journal_id IS NOT NULL;

-- Composite key journal_lines points at, so a line and its header always agree
-- on the tenant.
CREATE UNIQUE INDEX idx_journal_headers_id_tenant
    ON general_ledger.journal_headers (journal_id, tenant_id);

-- ── journal_lines ────────────────────────────────────────────────────────────
-- Append-only: lines are written once at journal creation and never updated.
-- Corrections happen only through a new reversing journal — no finalised
-- journal may be hard-edited.

CREATE TABLE general_ledger.journal_lines (
    journal_line_id       UUID          PRIMARY KEY DEFAULT gen_random_uuid(),
    journal_id            UUID          NOT NULL,
    tenant_id             UUID          NOT NULL,

    line_number           INTEGER       NOT NULL,
    account_code          VARCHAR(64)   NOT NULL,
    debit_amount          NUMERIC(18,2) NOT NULL DEFAULT 0,
    credit_amount         NUMERIC(18,2) NOT NULL DEFAULT 0,
    description           TEXT,

    -- A line with a tax basis carries the immutable snapshot it was computed
    -- from. No TaxLogicSnapshot-producing service exists on the platform yet,
    -- so this is always NULL in practice — a documented v1 gap.
    tax_code              VARCHAR(64),
    tax_logic_snapshot_id TEXT,

    UNIQUE (journal_id, line_number),

    CONSTRAINT journal_lines_line_number_positive
        CHECK (line_number >= 1),

    -- Amounts are magnitudes; direction is which column they land in.
    CONSTRAINT journal_lines_amounts_non_negative
        CHECK (debit_amount >= 0 AND credit_amount >= 0),

    -- Exactly one side. A line carrying both a debit and a credit, or neither,
    -- is not a double-entry line — it is two entries or none pretending to be
    -- one, and it makes the journal's balance unverifiable line by line.
    CONSTRAINT journal_lines_exactly_one_side
        CHECK ((debit_amount > 0) <> (credit_amount > 0)),

    -- Composite, so a line cannot be attached to another tenant's journal.
    CONSTRAINT journal_lines_header_fk
        FOREIGN KEY (journal_id, tenant_id)
        REFERENCES general_ledger.journal_headers (journal_id, tenant_id)
);

CREATE INDEX idx_journal_lines_journal ON general_ledger.journal_lines (journal_id);

-- NOTE ON BALANCE. That sum(debit) = sum(credit) for a journal is a
-- cross-row invariant, so it is not expressible as a CHECK. It is enforced by
-- the service before a journal is posted. Making the database the authority
-- would need a DEFERRABLE constraint trigger firing at COMMIT — worth doing,
-- but it is a behaviour change rather than a schema translation, so it is not
-- smuggled in here.

CREATE TRIGGER journal_lines_immutable
    BEFORE UPDATE OR DELETE ON general_ledger.journal_lines
    FOR EACH ROW EXECUTE FUNCTION app.reject_mutation();

-- ── Row-level security ───────────────────────────────────────────────────────

ALTER TABLE general_ledger.journal_headers ENABLE ROW LEVEL SECURITY;
ALTER TABLE general_ledger.journal_headers FORCE  ROW LEVEL SECURITY;
ALTER TABLE general_ledger.journal_lines   ENABLE ROW LEVEL SECURITY;
ALTER TABLE general_ledger.journal_lines   FORCE  ROW LEVEL SECURITY;

CREATE POLICY tenant_isolation ON general_ledger.journal_headers
    FOR ALL
    TO zoiko_backend
    USING      (tenant_id::text = app.current_tenant_id())
    WITH CHECK (tenant_id::text = app.current_tenant_id());

CREATE POLICY tenant_read ON general_ledger.journal_headers
    FOR SELECT
    TO authenticated
    USING (tenant_id::text = app.current_tenant_id());

CREATE POLICY tenant_isolation ON general_ledger.journal_lines
    FOR ALL
    TO zoiko_backend
    USING      (tenant_id::text = app.current_tenant_id())
    WITH CHECK (tenant_id::text = app.current_tenant_id());

CREATE POLICY tenant_read ON general_ledger.journal_lines
    FOR SELECT
    TO authenticated
    USING (tenant_id::text = app.current_tenant_id());

-- ── Grants ───────────────────────────────────────────────────────────────────

GRANT SELECT ON general_ledger.journal_headers TO authenticated;
GRANT SELECT ON general_ledger.journal_lines   TO authenticated;

-- Headers transition (DRAFT → VALIDATED → POSTED → REVERSED), so UPDATE is
-- granted. Lines never change.
GRANT SELECT, INSERT, UPDATE ON general_ledger.journal_headers TO zoiko_backend;
GRANT SELECT, INSERT         ON general_ledger.journal_lines   TO zoiko_backend;


-- ============================================================================
-- FILE: 0016_financial_close_svc.sql
-- ============================================================================

-- 0016_financial_close_svc.sql
-- financial-close-svc → schema `financial_close`
--
-- End state of 000001_initial_schema (the service's only migration).
-- Two tables: fiscal_periods, close_evidences.

CREATE SCHEMA IF NOT EXISTS financial_close;

COMMENT ON SCHEMA financial_close IS
    'financial-close-svc. Fiscal periods and their close state, with the signed trial-balance evidence produced at close.';

GRANT USAGE ON SCHEMA financial_close TO zoiko_backend, authenticated;

-- ── fiscal_periods ───────────────────────────────────────────────────────────

CREATE TABLE financial_close.fiscal_periods (
    fiscal_period_id     UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id            VARCHAR(255) NOT NULL,
    legal_entity_id      VARCHAR(255) NOT NULL,

    period_name          VARCHAR(50)  NOT NULL,
    period_start         TIMESTAMPTZ  NOT NULL,
    period_end           TIMESTAMPTZ  NOT NULL,

    -- OPEN | CLOSED | LOCKED
    close_status         VARCHAR(50)  NOT NULL,
    close_locked_at      TIMESTAMPTZ,

    evidence_document_id TEXT,

    UNIQUE (tenant_id, legal_entity_id, period_name),

    CONSTRAINT fiscal_periods_status_known
        CHECK (close_status IN ('OPEN', 'CLOSED', 'LOCKED')),

    CONSTRAINT fiscal_periods_period_ordered
        CHECK (period_end > period_start),

    -- A locked period must say when it was locked, and an open one must not
    -- claim to have been. Written as an equivalence so a stale close_locked_at
    -- cannot linger on a period later reopened.
    CONSTRAINT fiscal_periods_locked_has_timestamp
        CHECK ((close_status = 'LOCKED') = (close_locked_at IS NOT NULL))
);

CREATE INDEX idx_fiscal_periods_tenant_entity
    ON financial_close.fiscal_periods (tenant_id, legal_entity_id);

-- Composite key close_evidences points at, so evidence and its period always
-- agree on the tenant.
CREATE UNIQUE INDEX idx_fiscal_periods_id_tenant
    ON financial_close.fiscal_periods (fiscal_period_id, tenant_id);

-- ── close_evidences ──────────────────────────────────────────────────────────
-- The signed trial balance produced when a period closes. This is the artefact
-- an auditor is handed, so it is append-only: a close whose evidence can be
-- regenerated after the fact evidences nothing.

CREATE TABLE financial_close.close_evidences (
    evidence_id        UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id          VARCHAR(255) NOT NULL,
    fiscal_period_id   UUID         NOT NULL,

    trial_balance_hash VARCHAR(255) NOT NULL,
    signature          VARCHAR(255) NOT NULL,
    generated_at       TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    -- A hash and a signature that are present but empty are not evidence; they
    -- are the shape of evidence.
    CONSTRAINT close_evidences_hash_present
        CHECK (btrim(trial_balance_hash) <> ''),
    CONSTRAINT close_evidences_signature_present
        CHECK (btrim(signature) <> ''),

    CONSTRAINT close_evidences_period_fk
        FOREIGN KEY (fiscal_period_id, tenant_id)
        REFERENCES financial_close.fiscal_periods (fiscal_period_id, tenant_id)
        ON DELETE CASCADE
);

CREATE INDEX idx_close_evidences_tenant
    ON financial_close.close_evidences (tenant_id);
CREATE INDEX idx_close_evidences_period
    ON financial_close.close_evidences (fiscal_period_id, generated_at DESC);

CREATE TRIGGER close_evidences_immutable
    BEFORE UPDATE OR DELETE ON financial_close.close_evidences
    FOR EACH ROW EXECUTE FUNCTION app.reject_mutation();

-- ── Row-level security ───────────────────────────────────────────────────────

ALTER TABLE financial_close.fiscal_periods  ENABLE ROW LEVEL SECURITY;
ALTER TABLE financial_close.fiscal_periods  FORCE  ROW LEVEL SECURITY;
ALTER TABLE financial_close.close_evidences ENABLE ROW LEVEL SECURITY;
ALTER TABLE financial_close.close_evidences FORCE  ROW LEVEL SECURITY;

CREATE POLICY tenant_isolation ON financial_close.fiscal_periods
    FOR ALL
    TO zoiko_backend
    USING      (tenant_id = app.current_tenant_id())
    WITH CHECK (tenant_id = app.current_tenant_id());

CREATE POLICY tenant_read ON financial_close.fiscal_periods
    FOR SELECT
    TO authenticated
    USING (tenant_id = app.current_tenant_id());

CREATE POLICY tenant_isolation ON financial_close.close_evidences
    FOR ALL
    TO zoiko_backend
    USING      (tenant_id = app.current_tenant_id())
    WITH CHECK (tenant_id = app.current_tenant_id());

CREATE POLICY tenant_read ON financial_close.close_evidences
    FOR SELECT
    TO authenticated
    USING (tenant_id = app.current_tenant_id());

-- ── Grants ───────────────────────────────────────────────────────────────────

GRANT SELECT ON financial_close.fiscal_periods  TO authenticated;
GRANT SELECT ON financial_close.close_evidences TO authenticated;

-- Periods transition OPEN → CLOSED → LOCKED, so UPDATE is granted. There is no
-- DELETE: a period is locked, never removed.
GRANT SELECT, INSERT, UPDATE ON financial_close.fiscal_periods  TO zoiko_backend;
GRANT SELECT, INSERT         ON financial_close.close_evidences TO zoiko_backend;


-- ============================================================================
-- FILE: 0017_board_resolutions_svc.sql
-- ============================================================================

-- 0017_board_resolutions_svc.sql
-- board-resolutions-svc → schema `board_resolutions`
--
-- Squashed end state of 000001_initial_schema and
-- 000002_force_rls_and_constraints. Two tables: board_meetings,
-- board_resolutions.
--
-- The CHECK constraints are VALID here. 000002 added them NOT VALID because
-- board minutes and resolutions are the record of what a board decided, and a
-- migration that rewrites them to fit a rule written afterwards is worse than
-- one that constrains everything from now on. That protects an existing
-- backlog; this database has none.
--
-- Both tables keep their COMPOSITE primary keys (id, tenant_id) from 000001 —
-- unusual across this migration set, and worth keeping: it makes a row's tenant
-- part of its identity, so a resolution cannot be re-pointed at another tenant
-- by an UPDATE.

CREATE SCHEMA IF NOT EXISTS board_resolutions;

COMMENT ON SCHEMA board_resolutions IS
    'board-resolutions-svc. Board meetings and the resolutions passed at them.';

GRANT USAGE ON SCHEMA board_resolutions TO zoiko_backend, authenticated;

-- ── board_meetings ───────────────────────────────────────────────────────────

CREATE TABLE board_resolutions.board_meetings (
    meeting_id      TEXT        NOT NULL,
    tenant_id       TEXT        NOT NULL,
    legal_entity_id TEXT        NOT NULL,

    title           TEXT        NOT NULL,
    scheduled_at    TIMESTAMPTZ NOT NULL,
    location        TEXT,

    -- SCHEDULED | IN_PROGRESS | ADJOURNED | CANCELLED
    status          TEXT        NOT NULL DEFAULT 'SCHEDULED',
    minutes_summary TEXT,

    effective_from  DATE        NOT NULL,
    effective_to    DATE,

    -- Attribution is the verified caller. The handler additionally refuses a
    -- created_by that disagrees with the principal (requireSelfAttribution) —
    -- this service is the only one on the estate that does, and the default
    -- here is the database-side half of the same rule.
    created_by      TEXT        NOT NULL DEFAULT app.current_principal_id(),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

    PRIMARY KEY (meeting_id, tenant_id),

    CONSTRAINT board_meetings_status_known
        CHECK (status IN ('SCHEDULED', 'IN_PROGRESS', 'ADJOURNED', 'CANCELLED')),

    CONSTRAINT board_meetings_period_ordered
        CHECK (effective_to IS NULL OR effective_to >= effective_from)
);

CREATE INDEX idx_meetings_tenant_entity
    ON board_resolutions.board_meetings (tenant_id, legal_entity_id);
CREATE INDEX idx_meetings_tenant_scheduled
    ON board_resolutions.board_meetings (tenant_id, scheduled_at DESC, meeting_id DESC);

-- ── board_resolutions ────────────────────────────────────────────────────────

CREATE TABLE board_resolutions.board_resolutions (
    resolution_id     TEXT        NOT NULL,
    meeting_id        TEXT        NOT NULL,
    tenant_id         TEXT        NOT NULL,
    legal_entity_id   TEXT        NOT NULL,

    resolution_number TEXT        NOT NULL,
    title             TEXT        NOT NULL,
    content           TEXT        NOT NULL,

    -- GOVERNANCE | FINANCIAL | OPERATIONAL | EXECUTIVE | STATUTORY.
    -- This is sent to evidence-requirements-svc as the domain_code, so an
    -- unrecognised value asks the catalogue about a domain that does not exist
    -- and comes back with no requirements — an evidence gate bypassed by a typo.
    category          TEXT        NOT NULL,

    -- PROPOSED | PASSED | REJECTED | RESCINDED
    status            TEXT        NOT NULL DEFAULT 'PROPOSED',

    votes_for         INTEGER     NOT NULL DEFAULT 0,
    votes_against     INTEGER     NOT NULL DEFAULT 0,
    abstentions       INTEGER     NOT NULL DEFAULT 0,

    passed_at         TIMESTAMPTZ,
    passed_by         TEXT,

    document_vault_id TEXT,

    effective_from    DATE        NOT NULL,
    effective_to      DATE,

    created_by        TEXT        NOT NULL DEFAULT app.current_principal_id(),
    created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at        TIMESTAMPTZ NOT NULL DEFAULT now(),

    PRIMARY KEY (resolution_id, tenant_id),

    -- Vote tallies are counts of people. Nothing stopped a negative one being
    -- stored, so a resolution could carry -5 votes against and its arithmetic
    -- would still "work".
    CONSTRAINT board_resolutions_votes_non_negative
        CHECK (votes_for >= 0 AND votes_against >= 0 AND abstentions >= 0),

    CONSTRAINT board_resolutions_status_known
        CHECK (status IN ('PROPOSED', 'PASSED', 'REJECTED', 'RESCINDED')),

    CONSTRAINT board_resolutions_category_known
        CHECK (category IN ('GOVERNANCE', 'FINANCIAL', 'OPERATIONAL', 'EXECUTIVE', 'STATUTORY')),

    -- A PASSED resolution is the record that the board put something into
    -- force. Both halves must be present: passed_at without passed_by is an
    -- unattributed finalisation, which is exactly what segregation of duties
    -- exists to prevent.
    CONSTRAINT board_resolutions_passed_is_attributed
        CHECK (status <> 'PASSED' OR (passed_by IS NOT NULL AND passed_at IS NOT NULL)),

    CONSTRAINT board_resolutions_period_ordered
        CHECK (effective_to IS NULL OR effective_to >= effective_from),

    -- A resolution belongs to a meeting in the same tenant. The composite
    -- primary key on board_meetings makes this expressible; 000001 had no
    -- foreign key at all, so a resolution could name a meeting that did not
    -- exist, or one belonging to someone else.
    CONSTRAINT board_resolutions_meeting_fk
        FOREIGN KEY (meeting_id, tenant_id)
        REFERENCES board_resolutions.board_meetings (meeting_id, tenant_id)
);

CREATE INDEX idx_resolutions_tenant_entity
    ON board_resolutions.board_resolutions (tenant_id, legal_entity_id);
CREATE INDEX idx_resolutions_meeting_id
    ON board_resolutions.board_resolutions (meeting_id);
CREATE INDEX idx_resolutions_status
    ON board_resolutions.board_resolutions (status);
CREATE INDEX idx_resolutions_tenant_meeting
    ON board_resolutions.board_resolutions (tenant_id, meeting_id);
CREATE INDEX idx_resolutions_tenant_created
    ON board_resolutions.board_resolutions (tenant_id, created_at DESC, resolution_id DESC);

-- ── Row-level security ───────────────────────────────────────────────────────

ALTER TABLE board_resolutions.board_meetings    ENABLE ROW LEVEL SECURITY;
ALTER TABLE board_resolutions.board_meetings    FORCE  ROW LEVEL SECURITY;
ALTER TABLE board_resolutions.board_resolutions ENABLE ROW LEVEL SECURITY;
ALTER TABLE board_resolutions.board_resolutions FORCE  ROW LEVEL SECURITY;

CREATE POLICY tenant_isolation ON board_resolutions.board_meetings
    FOR ALL
    TO zoiko_backend
    USING      (tenant_id = app.current_tenant_id())
    WITH CHECK (tenant_id = app.current_tenant_id());

CREATE POLICY tenant_read ON board_resolutions.board_meetings
    FOR SELECT
    TO authenticated
    USING (tenant_id = app.current_tenant_id());

CREATE POLICY tenant_isolation ON board_resolutions.board_resolutions
    FOR ALL
    TO zoiko_backend
    USING      (tenant_id = app.current_tenant_id())
    WITH CHECK (tenant_id = app.current_tenant_id());

CREATE POLICY tenant_read ON board_resolutions.board_resolutions
    FOR SELECT
    TO authenticated
    USING (tenant_id = app.current_tenant_id());

-- ── Grants ───────────────────────────────────────────────────────────────────

GRANT SELECT ON board_resolutions.board_meetings    TO authenticated;
GRANT SELECT ON board_resolutions.board_resolutions TO authenticated;

-- Both transition (a meeting is adjourned, a resolution voted on and passed),
-- so UPDATE is granted. Neither is ever deleted — a rescinded resolution is
-- RESCINDED, not removed.
GRANT SELECT, INSERT, UPDATE ON board_resolutions.board_meetings    TO zoiko_backend;
GRANT SELECT, INSERT, UPDATE ON board_resolutions.board_resolutions TO zoiko_backend;


-- ============================================================================
-- FILE: 0018_obligations_svc.sql
-- ============================================================================

-- 0018_obligations_svc.sql
-- obligations-svc → schema `obligations`
--
-- Squashed end state of 000001_initial_schema,
-- 000002_add_applicability_decisions and 000003_tenant_scoping_and_invariants.
-- Three tables: obligations, filing_requirements, applicability_decisions.
--
-- ── tenant_id is a column from the start here ────────────────────────────────
-- 000003 had to ADD it: this service had no tenant column at all — not a
-- missing filter, a missing dimension. The sharpest edge was the dedup key.
-- obligation_code carried a GLOBAL unique index and creation is idempotent on
-- it, so a second tenant registering an ordinary code like "VAT-Q1-2026" did
-- not create their obligation — it silently returned the FIRST tenant's, with
-- that tenant's legal entity, due date and source reference, as a 200. One
-- tenant's compliance register answering with another's record, through the
-- documented happy path.
--
-- The nullable-add / backfill / SET NOT NULL dance and its hardcoded demo
-- tenant do not travel here; the column is simply NOT NULL. That backfill was
-- flagged in 000003 as unsafe for a deployment with real multi-tenant history,
-- and this migration removes the question.
--
-- ── applicability_decisions GETS a tenant column ─────────────────────────────
-- This is the one open gap in known-gaps.md that this migration closes rather
-- than carries. The table arrived from origin/main independently of the
-- tenant-scoping pass, so it has no tenant_id, is not covered by the row-level
-- security 000003 installed, and its store names no tenant in any of its three
-- statements. It is reachable only through an obligation_id, which IS
-- tenant-scoped, but the queries never join back — so an obligation_id
-- belonging to another tenant returns that tenant's applicability decisions,
-- including facts_used and who decided.
--
-- The fix here is the one the note prescribes: a tenant_id column, a composite
-- foreign key that keeps it agreeing with the parent obligation, and FORCE RLS
-- with a WITH CHECK policy.
--
-- ── Still open after this migration ──────────────────────────────────────────
-- Nothing verifies that an obligation's legal_entity_id belongs to the caller's
-- tenant. Authorization is scoped to the entity and rows are scoped by tenant,
-- and the two are never reconciled — a database-side fix is not available,
-- because no service on the platform calls tenant-entity-registry-svc at all.

CREATE SCHEMA IF NOT EXISTS obligations;

COMMENT ON SCHEMA obligations IS
    'obligations-svc. Statutory, regulatory, contractual and internal-policy obligations, their filing requirements, and the append-only applicability decision log.';

GRANT USAGE ON SCHEMA obligations TO zoiko_backend, authenticated;

-- ── obligations ──────────────────────────────────────────────────────────────

CREATE TABLE obligations.obligations (
    obligation_id           UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id               UUID         NOT NULL,

    -- Critical constraint: entity-bound and jurisdiction-bound, always.
    legal_entity_id         UUID         NOT NULL,
    jurisdiction_id         UUID         NOT NULL,

    -- Identifies the originating record (CONTRACT_CLAUSE, FILING_RULE,
    -- POLICY_MANDATE, JURISDICTION_RULE) and its id in whatever service owns
    -- that source. Not a foreign key — the source may live elsewhere entirely.
    obligation_source_type  VARCHAR(64)  NOT NULL,
    obligation_source_id    TEXT         NOT NULL,

    -- Stable human-readable identifier and the idempotent-creation dedup key.
    -- DATA ONLY, never a code switch/case.
    obligation_code         VARCHAR(128) NOT NULL,

    obligation_type         VARCHAR(64)  NOT NULL,

    -- OPEN | IN_PROGRESS | OVERDUE | CLOSED
    obligation_status       VARCHAR(32)  NOT NULL DEFAULT 'OPEN',

    due_date                TIMESTAMPTZ  NOT NULL,
    severity_level          VARCHAR(32)  NOT NULL,
    responsible_function    TEXT         NOT NULL,

    -- Atomic Linking — every obligation points to its originating source.
    source_reference        TEXT         NOT NULL,

    created_at              TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    created_by_principal_id TEXT         NOT NULL DEFAULT app.current_principal_id(),
    updated_at              TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    -- Nil until transitioned to CLOSED; set exactly once, never unset.
    closed_at               TIMESTAMPTZ,

    CONSTRAINT obligations_status_known
        CHECK (obligation_status IN ('OPEN', 'IN_PROGRESS', 'OVERDUE', 'CLOSED')),

    -- CLOSED is terminal and stamps closed_at; the two must agree, or the
    -- register shows an obligation that is closed with no record of when.
    CONSTRAINT obligations_closed_has_timestamp
        CHECK ((obligation_status = 'CLOSED') = (closed_at IS NOT NULL)),

    CONSTRAINT obligations_source_reference_present
        CHECK (btrim(source_reference) <> '')
);

-- An obligation code is unique WITHIN a tenant. Two tenants may both have a
-- "VAT-Q1-2026" and they are different obligations.
CREATE UNIQUE INDEX idx_obligations_tenant_code_unique
    ON obligations.obligations (tenant_id, obligation_code);

CREATE INDEX idx_obligations_legal_entity ON obligations.obligations (legal_entity_id);
CREATE INDEX idx_obligations_jurisdiction ON obligations.obligations (jurisdiction_id);
CREATE INDEX idx_obligations_status       ON obligations.obligations (obligation_status);
CREATE INDEX idx_obligations_due_date     ON obligations.obligations (due_date);

-- Every read is tenant-first, so the single-column indexes above are the wrong
-- shape for the register's own queries.
CREATE INDEX idx_obligations_tenant_entity ON obligations.obligations (tenant_id, legal_entity_id);
CREATE INDEX idx_obligations_tenant_status ON obligations.obligations (tenant_id, obligation_status);
CREATE INDEX idx_obligations_tenant_due    ON obligations.obligations (tenant_id, due_date);

-- The register is read newest-first and paged; due_date alone is not a total
-- order, so the primary key rides along as the tiebreaker for stable paging.
CREATE INDEX idx_obligations_tenant_due_id
    ON obligations.obligations (tenant_id, due_date DESC, obligation_id DESC);

-- Composite key the two child tables reference, so neither can disagree with
-- its parent about which tenant owns it.
CREATE UNIQUE INDEX idx_obligations_id_tenant
    ON obligations.obligations (obligation_id, tenant_id);

-- ── filing_requirements ──────────────────────────────────────────────────────
-- Carries its own tenant_id so a query can be scoped without a join — and,
-- more importantly, so row-level security applies to it directly. A policy that
-- has to join to find its tenant is a policy that does not run on a bare SELECT.

CREATE TABLE obligations.filing_requirements (
    filing_requirement_id UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    obligation_id         UUID         NOT NULL,
    tenant_id             UUID         NOT NULL,

    filing_type           VARCHAR(64)  NOT NULL,
    filing_authority      VARCHAR(128) NOT NULL,
    submission_channel    VARCHAR(64)  NOT NULL,

    -- PENDING | SUBMITTED | ACCEPTED | REJECTED
    filing_status         VARCHAR(32)  NOT NULL DEFAULT 'PENDING',

    created_at            TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    CONSTRAINT filing_requirements_status_known
        CHECK (filing_status IN ('PENDING', 'SUBMITTED', 'ACCEPTED', 'REJECTED')),

    CONSTRAINT filing_requirements_obligation_fk
        FOREIGN KEY (obligation_id, tenant_id)
        REFERENCES obligations.obligations (obligation_id, tenant_id)
);

CREATE INDEX idx_filing_requirements_obligation
    ON obligations.filing_requirements (obligation_id);
CREATE INDEX idx_filing_requirements_tenant
    ON obligations.filing_requirements (tenant_id, obligation_id);

-- ── applicability_decisions ──────────────────────────────────────────────────
-- Append-only decision log for one obligation's applicability in a given
-- jurisdiction / entity / activity / product scope. "Versioned" means new facts
-- or rules always produce a NEW row, never an UPDATE of a prior decision.
-- "Current" applicability is derived by querying the latest row whose effective
-- window covers now.
--
-- UNASSESSED (no decision has ever been made) and NOT_APPLICABLE (a decision
-- was made and concluded the obligation does not apply) are two deliberately
-- DISTINCT values. A row always represents a decision that WAS made, so
-- UNASSESSED is never stored — it is the application-level answer when no row
-- exists for a scope at all, and must never be silently coerced into
-- NOT_APPLICABLE.

CREATE TABLE obligations.applicability_decisions (
    applicability_decision_id UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    obligation_id             UUID         NOT NULL,

    -- Added by this migration; see the header.
    tenant_id                 UUID         NOT NULL,

    jurisdiction_code         VARCHAR(64)  NOT NULL,
    entity_ref                VARCHAR(255) NOT NULL,

    -- Optional finer-grained facts this decision was scoped against.
    activity_ref              VARCHAR(255),
    product_process_ref       VARCHAR(255),

    -- APPLICABLE | NOT_APPLICABLE | UNCERTAIN
    decision                  VARCHAR(32)  NOT NULL,

    -- Which approved source rule justified this decision, and its version.
    source_rule_ref           VARCHAR(255) NOT NULL,
    source_rule_version       VARCHAR(64)  NOT NULL,

    effective_from            TIMESTAMPTZ  NOT NULL,
    effective_to              TIMESTAMPTZ,

    -- The facts actually used to reach this decision. JSONB so the shape can
    -- vary by jurisdiction or obligation type without a schema change.
    facts_used                JSONB        NOT NULL DEFAULT '{}',

    confidence                NUMERIC(5,4),
    uncertainty_notes         TEXT,

    -- Exactly one of these is set: a human decided it, or a rule engine did.
    decided_by_principal_id   TEXT,
    decided_by_system         VARCHAR(128),

    -- A decision can require human review even after being reached — an
    -- UNCERTAIN outcome, or a low-confidence one.
    review_required           BOOLEAN      NOT NULL DEFAULT FALSE,

    created_at                TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    created_by_principal_id   TEXT         NOT NULL DEFAULT app.current_principal_id(),

    CONSTRAINT chk_applicability_decisions_actor_or_system
        CHECK (decided_by_principal_id IS NOT NULL OR decided_by_system IS NOT NULL),

    CONSTRAINT applicability_decisions_decision_known
        CHECK (decision IN ('APPLICABLE', 'NOT_APPLICABLE', 'UNCERTAIN')),

    CONSTRAINT applicability_decisions_confidence_range
        CHECK (confidence IS NULL OR (confidence >= 0 AND confidence <= 1)),

    CONSTRAINT applicability_decisions_period_ordered
        CHECK (effective_to IS NULL OR effective_to > effective_from),

    CONSTRAINT applicability_decisions_obligation_fk
        FOREIGN KEY (obligation_id, tenant_id)
        REFERENCES obligations.obligations (obligation_id, tenant_id)
);

-- Primary lookup: current applicability for an obligation + scope, most recent
-- effective_from first.
CREATE INDEX idx_applicability_decisions_scope
    ON obligations.applicability_decisions
       (obligation_id, jurisdiction_code, entity_ref, effective_from DESC);
CREATE INDEX idx_applicability_decisions_tenant
    ON obligations.applicability_decisions (tenant_id, obligation_id);

CREATE TRIGGER applicability_decisions_immutable
    BEFORE UPDATE OR DELETE ON obligations.applicability_decisions
    FOR EACH ROW EXECUTE FUNCTION app.reject_mutation();

-- ── Row-level security ───────────────────────────────────────────────────────

ALTER TABLE obligations.obligations              ENABLE ROW LEVEL SECURITY;
ALTER TABLE obligations.obligations              FORCE  ROW LEVEL SECURITY;
ALTER TABLE obligations.filing_requirements      ENABLE ROW LEVEL SECURITY;
ALTER TABLE obligations.filing_requirements      FORCE  ROW LEVEL SECURITY;
ALTER TABLE obligations.applicability_decisions  ENABLE ROW LEVEL SECURITY;
ALTER TABLE obligations.applicability_decisions  FORCE  ROW LEVEL SECURITY;

CREATE POLICY tenant_isolation ON obligations.obligations
    FOR ALL
    TO zoiko_backend
    USING      (tenant_id::text = app.current_tenant_id())
    WITH CHECK (tenant_id::text = app.current_tenant_id());

CREATE POLICY tenant_read ON obligations.obligations
    FOR SELECT
    TO authenticated
    USING (tenant_id::text = app.current_tenant_id());

CREATE POLICY tenant_isolation ON obligations.filing_requirements
    FOR ALL
    TO zoiko_backend
    USING      (tenant_id::text = app.current_tenant_id())
    WITH CHECK (tenant_id::text = app.current_tenant_id());

CREATE POLICY tenant_read ON obligations.filing_requirements
    FOR SELECT
    TO authenticated
    USING (tenant_id::text = app.current_tenant_id());

CREATE POLICY tenant_isolation ON obligations.applicability_decisions
    FOR ALL
    TO zoiko_backend
    USING      (tenant_id::text = app.current_tenant_id())
    WITH CHECK (tenant_id::text = app.current_tenant_id());

CREATE POLICY tenant_read ON obligations.applicability_decisions
    FOR SELECT
    TO authenticated
    USING (tenant_id::text = app.current_tenant_id());

-- ── Grants ───────────────────────────────────────────────────────────────────

GRANT SELECT ON obligations.obligations             TO authenticated;
GRANT SELECT ON obligations.filing_requirements     TO authenticated;
GRANT SELECT ON obligations.applicability_decisions TO authenticated;

-- No DELETE on any of the three: an obligation is CLOSED, never removed.
GRANT SELECT, INSERT, UPDATE ON obligations.obligations         TO zoiko_backend;
GRANT SELECT, INSERT, UPDATE ON obligations.filing_requirements TO zoiko_backend;
GRANT SELECT, INSERT         ON obligations.applicability_decisions TO zoiko_backend;


-- ============================================================================
-- FILE: 0019_document_vault_svc.sql
-- ============================================================================

-- 0019_document_vault_svc.sql
-- document-vault-svc → schema `document_vault`
--
-- Squashed end state of 000001_initial_schema and
-- 000002_force_rls_and_invariants. Three tables: documents, document_versions,
-- document_access_log.
--
-- "ZoikoSuite does not merely store documents. It preserves documentary
-- evidence as part of operational truth" — hence the strict split: `documents`
-- holds the current pointer and metadata, `document_versions` is an append-only
-- lineage (a new version is always a new row), and `document_access_log` is an
-- append-only record of every read.
--
-- ── The bytes are not in here ────────────────────────────────────────────────
-- document_versions.storage_key is a POINTER. On the compose estate it names an
-- object in the service's own storage; on Supabase the natural home is Supabase
-- Storage, and the key becomes the object path in a bucket. This migration
-- creates no bucket and takes no position on which — it only preserves the
-- column and the checksum that validates whatever it points at.
--
-- ── What 000002 had to correct, and is simply correct here ───────────────────
-- These three tables had NO row security at all — no policy, and nothing that
-- would fail closed if the application's own tenant predicate were wrong or
-- absent. It WAS absent: the store's predicate read
-- `($2::uuid IS NULL OR tenant_id = $2::uuid)`, which disables itself when the
-- request carries no X-Tenant-Id. On a vault holding CONFIDENTIAL and
-- RESTRICTED documents there was no tenant boundary of any kind for a caller
-- who simply omitted the header.
--
-- The CHECK constraints are VALID here rather than NOT VALID. 000002 had to
-- preserve rows recording 'unknown' as the accessing principal — the true
-- record of what the service did, which a migration must not rewrite. This
-- database has no such backlog.

CREATE SCHEMA IF NOT EXISTS document_vault;

COMMENT ON SCHEMA document_vault IS
    'document-vault-svc. Governed documents with append-only version lineage and access history. Bytes live in object storage; storage_key points at them.';

GRANT USAGE ON SCHEMA document_vault TO zoiko_backend, authenticated;

-- ── documents ────────────────────────────────────────────────────────────────

CREATE TABLE document_vault.documents (
    document_id             UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id               UUID         NOT NULL,
    legal_entity_id         UUID         NOT NULL,

    title                   VARCHAR(500) NOT NULL,

    classification          VARCHAR(20)  NOT NULL
        CHECK (classification IN ('PUBLIC', 'INTERNAL', 'CONFIDENTIAL', 'RESTRICTED')),

    -- A named policy code, NOT a retention engine. Nothing enforces it: no
    -- purge is scheduled by it, no delete is blocked by it, and there is no
    -- delete route at all. ErrRetentionActive is defined in the domain and
    -- never returned. A document marked for a seven-year hold is not held by
    -- anything in this vault — the label records an intention some other system
    -- would have to honour. Recorded here so the column is not over-read.
    retention_policy        VARCHAR(50)  NOT NULL DEFAULT 'DEFAULT',

    -- Jurisdiction-aware residency. Nullable: not every document is
    -- residency-constrained. A region code, not a cross-service foreign key.
    residency_region_code   VARCHAR(20),

    current_version         INT          NOT NULL DEFAULT 1,

    status                  VARCHAR(20)  NOT NULL DEFAULT 'ACTIVE'
        CHECK (status IN ('ACTIVE', 'RETAINED', 'PURGE_PENDING')),

    created_by_principal_id VARCHAR(255) NOT NULL DEFAULT app.current_principal_id(),
    created_at              TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at              TIMESTAMPTZ  NOT NULL DEFAULT now(),

    -- The handler used to substitute the literal 'unknown' when a request
    -- carried no identity, so a record meant to say who created a document
    -- could say nothing and read as though it had said something.
    CONSTRAINT documents_created_by_identified
        CHECK (created_by_principal_id <> '' AND created_by_principal_id <> 'unknown'),

    -- A document claiming version 0 or a negative one points at a version row
    -- that cannot exist.
    CONSTRAINT documents_current_version_positive
        CHECK (current_version >= 1)
);

CREATE INDEX idx_documents_tenant
    ON document_vault.documents (tenant_id, legal_entity_id);
CREATE INDEX idx_documents_tenant_created
    ON document_vault.documents (tenant_id, created_at DESC, document_id DESC);

-- ── document_versions ────────────────────────────────────────────────────────
-- Append-only. A document "update" NEVER updates this table — it inserts a new
-- row and bumps documents.current_version. Integrity validation is the SHA-256
-- checksum, computed on write and re-checked on every read.

CREATE TABLE document_vault.document_versions (
    document_version_id     UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    document_id             UUID         NOT NULL REFERENCES document_vault.documents(document_id),

    version                 INT          NOT NULL,
    checksum_sha256         VARCHAR(64)  NOT NULL,

    -- Pointer to the stored object, not the bytes themselves.
    storage_key             VARCHAR(500) NOT NULL,

    size_bytes              BIGINT       NOT NULL,
    content_type            VARCHAR(255) NOT NULL,

    created_by_principal_id VARCHAR(255) NOT NULL DEFAULT app.current_principal_id(),
    created_at              TIMESTAMPTZ  NOT NULL DEFAULT now(),

    UNIQUE (document_id, version),

    CONSTRAINT document_versions_created_by_identified
        CHECK (created_by_principal_id <> '' AND created_by_principal_id <> 'unknown'),
    CONSTRAINT document_versions_version_positive
        CHECK (version >= 1),

    -- A checksum IS the integrity control, recomputed on every read. A row with
    -- a blank or short one has no integrity control at all.
    CONSTRAINT document_versions_checksum_present
        CHECK (length(checksum_sha256) = 64),
    CONSTRAINT document_versions_size_nonnegative
        CHECK (size_bytes >= 0)
);

CREATE INDEX idx_document_versions_document
    ON document_vault.document_versions (document_id, version);

CREATE TRIGGER document_versions_immutable
    BEFORE UPDATE OR DELETE ON document_vault.document_versions
    FOR EACH ROW EXECUTE FUNCTION app.reject_mutation();

-- ── document_access_log ──────────────────────────────────────────────────────
-- Append-only record of every read.
--
-- OPEN GAP, carried over unchanged: GET /{id} and /{id}/content append a row
-- here; the register LIST route does not. So the log is a complete account of
-- DOWNLOADS and single-document reads only, and understates who has seen
-- metadata. Recording one row per document per list call would make the log
-- unreadable for its actual purpose, and a "LIST" access type covering a result
-- set is a schema decision rather than a bug fix — so access_type keeps its two
-- values here and the question stays open.

CREATE TABLE document_vault.document_access_log (
    access_log_id            UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    document_id              UUID         NOT NULL REFERENCES document_vault.documents(document_id),
    document_version_id      UUID         REFERENCES document_vault.document_versions(document_version_id),

    accessed_by_principal_id VARCHAR(255) NOT NULL DEFAULT app.current_principal_id(),

    access_type              VARCHAR(20)  NOT NULL
        CHECK (access_type IN ('METADATA', 'DOWNLOAD')),

    correlation_id           VARCHAR(255),
    accessed_at              TIMESTAMPTZ  NOT NULL DEFAULT now(),

    -- The log was accepting the literal string 'unknown' as a principal,
    -- because the handler substituted that when a request carried no identity.
    -- So the append-only record that exists to answer "who downloaded this
    -- RESTRICTED document" could answer "unknown", and read as though it had
    -- answered.
    CONSTRAINT document_access_log_principal_identified
        CHECK (accessed_by_principal_id <> '' AND accessed_by_principal_id <> 'unknown')
);

CREATE INDEX idx_document_access_log_document
    ON document_vault.document_access_log (document_id, accessed_at);

-- Read newest-first and paged; accessed_at alone is not a total order, so the
-- primary key rides along as the tiebreaker.
CREATE INDEX idx_document_access_log_document_paged
    ON document_vault.document_access_log (document_id, accessed_at DESC, access_log_id DESC);

CREATE TRIGGER document_access_log_immutable
    BEFORE UPDATE OR DELETE ON document_vault.document_access_log
    FOR EACH ROW EXECUTE FUNCTION app.reject_mutation();

-- ── Row-level security ───────────────────────────────────────────────────────
-- document_versions and document_access_log carry no tenant_id of their own —
-- they hang off documents. Scoping them through that parent rather than
-- denormalising a tenant column keeps ONE source of truth for which tenant owns
-- a document, and means a version or an access-log row can never disagree with
-- its document about it.
--
-- The EXISTS is itself subject to the documents policy, so a version whose
-- parent is invisible to this tenant is invisible too.

ALTER TABLE document_vault.documents           ENABLE ROW LEVEL SECURITY;
ALTER TABLE document_vault.documents           FORCE  ROW LEVEL SECURITY;
ALTER TABLE document_vault.document_versions   ENABLE ROW LEVEL SECURITY;
ALTER TABLE document_vault.document_versions   FORCE  ROW LEVEL SECURITY;
ALTER TABLE document_vault.document_access_log ENABLE ROW LEVEL SECURITY;
ALTER TABLE document_vault.document_access_log FORCE  ROW LEVEL SECURITY;

CREATE POLICY tenant_isolation ON document_vault.documents
    FOR ALL
    TO zoiko_backend
    USING      (tenant_id::text = app.current_tenant_id())
    WITH CHECK (tenant_id::text = app.current_tenant_id());

CREATE POLICY tenant_read ON document_vault.documents
    FOR SELECT
    TO authenticated
    USING (tenant_id::text = app.current_tenant_id());

CREATE POLICY tenant_isolation ON document_vault.document_versions
    FOR ALL
    TO zoiko_backend
    USING      (EXISTS (SELECT 1 FROM document_vault.documents d
                         WHERE d.document_id = document_versions.document_id))
    WITH CHECK (EXISTS (SELECT 1 FROM document_vault.documents d
                         WHERE d.document_id = document_versions.document_id));

CREATE POLICY tenant_read ON document_vault.document_versions
    FOR SELECT
    TO authenticated
    USING (EXISTS (SELECT 1 FROM document_vault.documents d
                    WHERE d.document_id = document_versions.document_id));

CREATE POLICY tenant_isolation ON document_vault.document_access_log
    FOR ALL
    TO zoiko_backend
    USING      (EXISTS (SELECT 1 FROM document_vault.documents d
                         WHERE d.document_id = document_access_log.document_id))
    WITH CHECK (EXISTS (SELECT 1 FROM document_vault.documents d
                         WHERE d.document_id = document_access_log.document_id));

CREATE POLICY tenant_read ON document_vault.document_access_log
    FOR SELECT
    TO authenticated
    USING (EXISTS (SELECT 1 FROM document_vault.documents d
                    WHERE d.document_id = document_access_log.document_id));

-- ── Grants ───────────────────────────────────────────────────────────────────

GRANT SELECT ON document_vault.documents           TO authenticated;
GRANT SELECT ON document_vault.document_versions   TO authenticated;
GRANT SELECT ON document_vault.document_access_log TO authenticated;

-- documents transitions (status, current_version), so UPDATE is granted. The
-- lineage and the access log never change.
GRANT SELECT, INSERT, UPDATE ON document_vault.documents           TO zoiko_backend;
GRANT SELECT, INSERT         ON document_vault.document_versions   TO zoiko_backend;
GRANT SELECT, INSERT         ON document_vault.document_access_log TO zoiko_backend;


-- ============================================================================
-- FILE: 0020_secret_vault_integration_svc.sql
-- ============================================================================

-- 0020_secret_vault_integration_svc.sql
-- secret-vault-integration-svc → schema `secret_vault_integration`
--
-- Squashed end state of 000001_initial_schema and
-- 000002_add_data_classification. Four tables: secret_policies,
-- secret_policy_versions, secret_leases, secret_access_audit_log.
--
-- ── This service stores no secret VALUES ─────────────────────────────────────
-- Only policy metadata, lease metadata, and audit records referencing an opaque
-- secret_path. The real material lives behind the VaultBackend interface, not
-- in this database. That is worth restating because it is the reason the tables
-- below can exist in a general-purpose Postgres at all.
--
-- ── No `authenticated` access to ANY table in this schema ────────────────────
-- Every other service in this migration set grants console sessions a
-- tenant-scoped SELECT. This one grants them nothing, and the schema is not
-- granted USAGE to them either.
--
-- The reason is that a secret PATH is itself sensitive: the set of paths, who
-- brokered which, and when, is a map of the platform's credentials and of who
-- holds them. secret_policies carries data_classification RESTRICTED by
-- default. Exposing these tables through PostgREST would put that map one JWT
-- away from any logged-in console user, which no route on this service does
-- today. Reads go through the service, which authorises them.

CREATE SCHEMA IF NOT EXISTS secret_vault_integration;

COMMENT ON SCHEMA secret_vault_integration IS
    'secret-vault-integration-svc. Vault policy, lease and access-audit metadata. Never secret values. Deliberately not exposed to the authenticated role.';

GRANT USAGE ON SCHEMA secret_vault_integration TO zoiko_backend;

-- ── secret_policies ──────────────────────────────────────────────────────────
-- No tenant dimension: a vault path is a platform-wide address, and scoping
-- happens on the versions below.

CREATE TABLE secret_vault_integration.secret_policies (
    secret_policy_id        UUID        PRIMARY KEY DEFAULT gen_random_uuid(),

    -- Data-driven, never a code switch/case.
    secret_class            VARCHAR(64) NOT NULL,

    -- The opaque reference/path in the underlying vault backend — never the
    -- secret value. This is the natural unique key ON ITS OWN: a vault path is
    -- already a unique address by construction, so the key is secret_path and
    -- not (secret_class, secret_path).
    secret_path             TEXT        NOT NULL,

    created_at              TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_by_principal_id TEXT        NOT NULL DEFAULT app.current_principal_id(),

    data_classification     VARCHAR(32) NOT NULL DEFAULT 'RESTRICTED',

    CONSTRAINT secret_policies_path_present
        CHECK (btrim(secret_path) <> '')
);

CREATE UNIQUE INDEX idx_secret_policies_path_unique
    ON secret_vault_integration.secret_policies (secret_path);
CREATE INDEX idx_secret_policies_class
    ON secret_vault_integration.secret_policies (secret_class);

-- ── secret_policy_versions ───────────────────────────────────────────────────

CREATE TABLE secret_vault_integration.secret_policy_versions (
    secret_policy_version_id   UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    secret_policy_id           UUID        NOT NULL
        REFERENCES secret_vault_integration.secret_policies(secret_policy_id),

    -- NULL tenant_id = global policy.
    tenant_id                  UUID,
    -- NULL legal_entity_id = applies to the whole tenant, or globally.
    legal_entity_id            UUID,

    -- Workload / service / principal identifiers permitted to broker this
    -- secret in this scope. JSONB array — data, not schema.
    allowed_workload_ids       JSONB       NOT NULL DEFAULT '[]',

    max_lease_duration_seconds INTEGER     NOT NULL,

    effective_from             TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    effective_to               TIMESTAMPTZ,

    -- DRAFT | ACTIVE | SUPERSEDED | RETIRED
    version_status             VARCHAR(32) NOT NULL DEFAULT 'DRAFT',

    created_at                 TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_by_principal_id    TEXT        NOT NULL DEFAULT app.current_principal_id(),

    CONSTRAINT secret_policy_versions_status_known
        CHECK (version_status IN ('DRAFT', 'ACTIVE', 'SUPERSEDED', 'RETIRED')),

    CONSTRAINT secret_policy_versions_lease_duration_positive
        CHECK (max_lease_duration_seconds > 0),

    CONSTRAINT secret_policy_versions_period_ordered
        CHECK (effective_to IS NULL OR effective_to > effective_from),

    -- allowed_workload_ids is consulted to decide who may broker this secret.
    -- A non-array there is not a permissive list, it is an unreadable one.
    CONSTRAINT secret_policy_versions_workloads_is_array
        CHECK (jsonb_typeof(allowed_workload_ids) = 'array')
);

-- Idempotent creation key for a version within a policy + scope + effective_from.
CREATE UNIQUE INDEX idx_secret_policy_versions_dedup
    ON secret_vault_integration.secret_policy_versions (
        secret_policy_id,
        COALESCE(tenant_id, '00000000-0000-0000-0000-000000000000'::UUID),
        COALESCE(legal_entity_id, '00000000-0000-0000-0000-000000000000'::UUID),
        effective_from
    );

CREATE INDEX idx_secret_policy_versions_scope
    ON secret_vault_integration.secret_policy_versions
       (secret_policy_id, tenant_id, legal_entity_id);

-- At most one ACTIVE version per scope. COALESCE for the same reason as
-- everywhere else: Postgres treats NULLs as distinct in a unique index, so
-- without it "one active global policy" would not hold at all.
CREATE UNIQUE INDEX idx_secret_policy_versions_one_active_per_scope
    ON secret_vault_integration.secret_policy_versions (
        secret_policy_id,
        COALESCE(tenant_id, '00000000-0000-0000-0000-000000000000'::UUID),
        COALESCE(legal_entity_id, '00000000-0000-0000-0000-000000000000'::UUID)
    )
    WHERE version_status = 'ACTIVE';

CREATE INDEX idx_secret_policy_versions_history
    ON secret_vault_integration.secret_policy_versions (secret_policy_id, effective_from DESC);

-- ── secret_leases ────────────────────────────────────────────────────────────
-- Grants only. A denial never becomes a lease — denials exist solely in
-- secret_access_audit_log. Effective-dated and revocable, never hard-deleted.

CREATE TABLE secret_vault_integration.secret_leases (
    lease_id                  UUID        PRIMARY KEY DEFAULT gen_random_uuid(),

    -- Caller-supplied idempotency key: a retried broker request with the same
    -- request_id must never mint a second lease.
    request_id                TEXT        NOT NULL,

    secret_policy_version_id  UUID        NOT NULL
        REFERENCES secret_vault_integration.secret_policy_versions(secret_policy_version_id),

    -- Denormalised from the resolved policy at grant time, so this row is
    -- self-contained evidence even after the policy is superseded.
    secret_class              VARCHAR(64) NOT NULL,
    secret_path               TEXT        NOT NULL,

    requested_by_principal_id TEXT        NOT NULL,
    tenant_id                 UUID,
    legal_entity_id           UUID,

    -- GRANTED | EXPIRED | REVOKED. EXPIRED is a COMPUTED read
    -- (status = 'GRANTED' AND expires_at < NOW()), never a background job
    -- flipping rows — so a lease that has run out is expired the instant it
    -- runs out, with no window in which a sweep has not caught up yet.
    status                    VARCHAR(32) NOT NULL DEFAULT 'GRANTED',

    granted_at                TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    expires_at                TIMESTAMPTZ NOT NULL,
    revoked_at                TIMESTAMPTZ,

    correlation_id            TEXT,
    created_at                TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT secret_leases_status_known
        CHECK (status IN ('GRANTED', 'EXPIRED', 'REVOKED')),

    -- A lease that expires before it is granted is not a lease.
    CONSTRAINT secret_leases_expiry_after_grant
        CHECK (expires_at > granted_at),

    -- A revoked lease must say when. Written as an equivalence so a revoked_at
    -- cannot linger on a row rewritten back to GRANTED.
    CONSTRAINT secret_leases_revoked_has_timestamp
        CHECK ((status = 'REVOKED') = (revoked_at IS NOT NULL))
);

CREATE UNIQUE INDEX idx_secret_leases_request_id_unique
    ON secret_vault_integration.secret_leases (request_id);
CREATE INDEX idx_secret_leases_principal
    ON secret_vault_integration.secret_leases (requested_by_principal_id);
CREATE INDEX idx_secret_leases_secret_path
    ON secret_vault_integration.secret_leases (secret_path);
CREATE INDEX idx_secret_leases_status
    ON secret_vault_integration.secret_leases (status) WHERE status = 'GRANTED';
CREATE INDEX idx_secret_leases_granted_at
    ON secret_vault_integration.secret_leases (granted_at);

-- ── secret_access_audit_log ──────────────────────────────────────────────────
-- Append-only, same guarantees as governance_decisions: no UPDATE, no DELETE,
-- ever. This is where a DENIED decision lives, so it is the only record that a
-- refusal happened at all.

CREATE TABLE secret_vault_integration.secret_access_audit_log (
    audit_log_id              UUID        PRIMARY KEY DEFAULT gen_random_uuid(),

    -- REQUESTED | GRANTED | DENIED | REVOKED | ROTATED
    event_type                VARCHAR(32) NOT NULL,

    secret_class              VARCHAR(64) NOT NULL,
    secret_path               TEXT        NOT NULL,

    requested_by_principal_id TEXT        NOT NULL,
    tenant_id                 UUID,
    legal_entity_id           UUID,

    -- NULL for REQUESTED and DENIED — nothing was granted to reference. Set for
    -- every lease revoked by a ROTATED event too.
    lease_id                  UUID
        REFERENCES secret_vault_integration.secret_leases(lease_id),

    -- NULL for DENIED when no policy existed at all for that path or scope.
    secret_policy_version_id  UUID
        REFERENCES secret_vault_integration.secret_policy_versions(secret_policy_version_id),

    -- Populated and deduped for ROTATED entries only: rotation needs its own
    -- idempotency path, distinct from secret_leases.request_id, because a
    -- rotate call creates no lease row.
    request_id                TEXT,

    outcome_detail            TEXT,
    correlation_id            TEXT,
    recorded_at               TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT secret_access_audit_log_event_type_known
        CHECK (event_type IN ('REQUESTED', 'GRANTED', 'DENIED', 'REVOKED', 'ROTATED')),

    -- A GRANTED audit entry that references no lease is a claim that access was
    -- given with nothing recording what was given.
    CONSTRAINT secret_access_audit_log_granted_has_lease
        CHECK (event_type <> 'GRANTED' OR lease_id IS NOT NULL)
);

CREATE UNIQUE INDEX idx_secret_access_audit_log_rotation_request_id
    ON secret_vault_integration.secret_access_audit_log (request_id)
    WHERE event_type = 'ROTATED' AND request_id IS NOT NULL;

CREATE INDEX idx_secret_access_audit_log_principal
    ON secret_vault_integration.secret_access_audit_log (requested_by_principal_id);
CREATE INDEX idx_secret_access_audit_log_secret_path
    ON secret_vault_integration.secret_access_audit_log (secret_path);
CREATE INDEX idx_secret_access_audit_log_event_type
    ON secret_vault_integration.secret_access_audit_log (event_type);
CREATE INDEX idx_secret_access_audit_log_recorded_at
    ON secret_vault_integration.secret_access_audit_log (recorded_at);

CREATE TRIGGER secret_access_audit_log_immutable
    BEFORE UPDATE OR DELETE ON secret_vault_integration.secret_access_audit_log
    FOR EACH ROW EXECUTE FUNCTION app.reject_mutation();

-- ── Row-level security ───────────────────────────────────────────────────────
-- secret_policies has no tenant column at all, so its policy is a plain
-- backend-only gate. The other three carry a NULLABLE tenant_id where NULL
-- means global, so they take the asymmetric shape used by
-- configuration-feature-flag: globals are readable by everyone, but writable
-- only by a connection that has installed no tenant — a tenant connection can
-- never mint a global.

ALTER TABLE secret_vault_integration.secret_policies          ENABLE ROW LEVEL SECURITY;
ALTER TABLE secret_vault_integration.secret_policies          FORCE  ROW LEVEL SECURITY;
ALTER TABLE secret_vault_integration.secret_policy_versions   ENABLE ROW LEVEL SECURITY;
ALTER TABLE secret_vault_integration.secret_policy_versions   FORCE  ROW LEVEL SECURITY;
ALTER TABLE secret_vault_integration.secret_leases            ENABLE ROW LEVEL SECURITY;
ALTER TABLE secret_vault_integration.secret_leases            FORCE  ROW LEVEL SECURITY;
ALTER TABLE secret_vault_integration.secret_access_audit_log  ENABLE ROW LEVEL SECURITY;
ALTER TABLE secret_vault_integration.secret_access_audit_log  FORCE  ROW LEVEL SECURITY;

CREATE POLICY backend_all ON secret_vault_integration.secret_policies
    FOR ALL TO zoiko_backend USING (true) WITH CHECK (true);

CREATE POLICY tenant_isolation ON secret_vault_integration.secret_policy_versions
    FOR ALL
    TO zoiko_backend
    USING (tenant_id IS NULL OR tenant_id::text = app.current_tenant_id())
    WITH CHECK (
        (tenant_id IS NOT NULL AND tenant_id::text = app.current_tenant_id())
        OR (tenant_id IS NULL AND app.current_tenant_id() IS NULL)
    );

CREATE POLICY tenant_isolation ON secret_vault_integration.secret_leases
    FOR ALL
    TO zoiko_backend
    USING (tenant_id IS NULL OR tenant_id::text = app.current_tenant_id())
    WITH CHECK (
        (tenant_id IS NOT NULL AND tenant_id::text = app.current_tenant_id())
        OR (tenant_id IS NULL AND app.current_tenant_id() IS NULL)
    );

CREATE POLICY tenant_isolation ON secret_vault_integration.secret_access_audit_log
    FOR ALL
    TO zoiko_backend
    USING (tenant_id IS NULL OR tenant_id::text = app.current_tenant_id())
    WITH CHECK (
        (tenant_id IS NOT NULL AND tenant_id::text = app.current_tenant_id())
        OR (tenant_id IS NULL AND app.current_tenant_id() IS NULL)
    );

-- ── Grants ───────────────────────────────────────────────────────────────────
-- No grants to `authenticated` anywhere in this schema — see the header.

GRANT SELECT, INSERT, UPDATE ON secret_vault_integration.secret_policies        TO zoiko_backend;
GRANT SELECT, INSERT, UPDATE ON secret_vault_integration.secret_policy_versions TO zoiko_backend;

-- Leases transition (GRANTED → REVOKED), so UPDATE. Never deleted.
GRANT SELECT, INSERT, UPDATE ON secret_vault_integration.secret_leases          TO zoiko_backend;

-- The audit log is append-only.
GRANT SELECT, INSERT         ON secret_vault_integration.secret_access_audit_log TO zoiko_backend;


-- ============================================================================
-- FILE: 0021_policy_svc.sql
-- ============================================================================

-- 0021_policy_svc.sql
-- policy-svc → schema `policy`
--
-- Squashed end state of 000001_initial_schema, 000002_add_activation_audit,
-- 000003_add_explicit_scope_type and 000004_add_control_tests. Five tables:
-- policies, policy_versions, control_test_definitions,
-- control_test_executions, attestations.
--
-- ── This service had NO row-level security at all ────────────────────────────
-- 000001 says why, and says it honestly: "policy_versions carries tenant_id but
-- is filtered by application-level scope match, not per-row RLS — reconsider
-- if/when this service takes direct multi-tenant traffic without a scope-aware
-- caller." Putting the tables behind PostgREST in a shared database is exactly
-- that moment, so RLS is added here for all five.
--
-- policy_versions uses the asymmetric nullable-tenant policy: a GLOBAL policy
-- version applies across every tenant, so any tenant being able to write one
-- would let a single tenant rewrite the approval thresholds the whole platform
-- evaluates against.
--
-- The three §E3/§E6 tables (control tests and attestations) have no tenant
-- column of their own — control_ref and subject_ref are free-text identifiers
-- backed by no registry anywhere on the platform. They are backend-only,
-- readable but not writable by console sessions.
--
-- ── The 000003 backfill is dropped ───────────────────────────────────────────
-- It derived scope_type from the existing nullness pattern of rows written
-- before the column existed. There are none here, so scope_type is simply NOT
-- NULL with no default — a writer must state the scope rather than fall into
-- 'GLOBAL', which is the point §F1 was making: "GLOBAL is an explicit scope,
-- not a default."

CREATE SCHEMA IF NOT EXISTS policy;

COMMENT ON SCHEMA policy IS
    'policy-svc. Policies and effective-dated versions, plus control test definitions/executions and attestations.';

GRANT USAGE ON SCHEMA policy TO zoiko_backend, authenticated;

-- ── policies ─────────────────────────────────────────────────────────────────

CREATE TABLE policy.policies (
    policy_id               UUID         PRIMARY KEY DEFAULT gen_random_uuid(),

    -- Stable human-readable identifier and idempotent-creation dedup key.
    -- DATA ONLY, never a code switch/case.
    policy_code             VARCHAR(128) NOT NULL,

    policy_name             TEXT         NOT NULL,

    -- APPROVAL_THRESHOLD | SPEND_CONTROL | SOD_RULE | SIGNATORY_MATRIX and
    -- whatever else arrives by data migration. Only the evaluation handler
    -- switches on this, and only for the types it actually implements.
    policy_type             VARCHAR(64)  NOT NULL,

    created_at              TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    created_by_principal_id TEXT         NOT NULL DEFAULT app.current_principal_id()
);

CREATE UNIQUE INDEX idx_policies_code_unique ON policy.policies (policy_code);
CREATE INDEX idx_policies_type ON policy.policies (policy_type);

-- ── policy_versions ──────────────────────────────────────────────────────────

CREATE TABLE policy.policy_versions (
    policy_version_id         UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    policy_id                 UUID        NOT NULL REFERENCES policy.policies(policy_id),

    -- NULL tenant_id = global, applying across all tenants.
    tenant_id                 UUID,
    -- NULL legal_entity_id = the whole tenant, or globally if tenant is NULL.
    legal_entity_id           UUID,

    -- "GLOBAL is an explicit scope, not a default." The CHECK ties scope_type
    -- to the nullness of the two columns above so the two can never drift.
    scope_type                VARCHAR(16) NOT NULL,

    -- Rule content; shape depends on the owning policy's policy_type, e.g.
    -- {"threshold_amount": 5000} for APPROVAL_THRESHOLD.
    rule_payload              JSONB       NOT NULL DEFAULT '{}',

    -- Point-in-time queries use the half-open interval:
    --   effective_from <= $at AND (effective_to IS NULL OR effective_to > $at)
    effective_from            TIMESTAMPTZ NOT NULL,
    effective_to              TIMESTAMPTZ,

    -- DRAFT | ACTIVE | SUPERSEDED | RETIRED
    version_status            VARCHAR(32) NOT NULL DEFAULT 'DRAFT',

    -- NULL means never activated (still DRAFT). Set once on the version's only
    -- real activation transition and never overwritten — when the version is
    -- later superseded, its own activation history stands unchanged.
    activated_by_principal_id TEXT,
    activated_at              TIMESTAMPTZ,

    created_at                TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_by_principal_id   TEXT        NOT NULL DEFAULT app.current_principal_id(),

    CONSTRAINT chk_policy_versions_scope_type CHECK (
        (scope_type = 'GLOBAL'       AND tenant_id IS NULL     AND legal_entity_id IS NULL)
     OR (scope_type = 'TENANT'       AND tenant_id IS NOT NULL AND legal_entity_id IS NULL)
     OR (scope_type = 'LEGAL_ENTITY' AND tenant_id IS NOT NULL AND legal_entity_id IS NOT NULL)
    ),

    CONSTRAINT policy_versions_status_known
        CHECK (version_status IN ('DRAFT', 'ACTIVE', 'SUPERSEDED', 'RETIRED')),

    CONSTRAINT policy_versions_period_ordered
        CHECK (effective_to IS NULL OR effective_to > effective_from),

    -- Activation is an attributed event: a version recorded as activated with
    -- no actor, or an actor with no timestamp, is half a record.
    CONSTRAINT policy_versions_activation_is_attributed
        CHECK ((activated_at IS NULL) = (activated_by_principal_id IS NULL)),

    -- A version that has never been activated cannot be ACTIVE or SUPERSEDED.
    CONSTRAINT policy_versions_live_was_activated
        CHECK (version_status IN ('DRAFT', 'RETIRED') OR activated_at IS NOT NULL)
);

-- Idempotent creation key for a version within a policy + scope +
-- effective_from. This exact expression list is targeted BY NAME in
-- pg_store.go's ON CONFLICT clause — keep them in sync if either changes.
CREATE UNIQUE INDEX idx_policy_versions_dedup ON policy.policy_versions (
    policy_id,
    COALESCE(tenant_id, '00000000-0000-0000-0000-000000000000'::UUID),
    COALESCE(legal_entity_id, '00000000-0000-0000-0000-000000000000'::UUID),
    effective_from
);

CREATE INDEX idx_policy_versions_scope
    ON policy.policy_versions (policy_id, tenant_id, legal_entity_id);

-- At most one ACTIVE version per scope at any time. Activation supersedes the
-- prior ACTIVE version in the SAME transaction, superseding first, so this is
-- never violated mid-transaction.
CREATE UNIQUE INDEX idx_policy_versions_one_active_per_scope
    ON policy.policy_versions (
        policy_id,
        COALESCE(tenant_id, '00000000-0000-0000-0000-000000000000'::UUID),
        COALESCE(legal_entity_id, '00000000-0000-0000-0000-000000000000'::UUID)
    )
    WHERE version_status = 'ACTIVE';

CREATE INDEX idx_policy_versions_history
    ON policy.policy_versions (policy_id, effective_from DESC);

-- ── control_test_definitions ─────────────────────────────────────────────────
-- A control is not effective because it exists. DESIGN_STATUS lives here — a
-- control has a defined test methodology or it does not. Immutable once
-- created: a changed methodology is a new row.

CREATE TABLE policy.control_test_definitions (
    control_test_definition_id UUID         PRIMARY KEY DEFAULT gen_random_uuid(),

    -- Free-text control identifier. This service owns no control registry —
    -- that concept exists nowhere in the codebase — so it is DATA, never a
    -- foreign key and never a switch/case.
    control_ref                VARCHAR(128) NOT NULL,

    test_code                  VARCHAR(128) NOT NULL,
    title                      TEXT         NOT NULL,

    methodology                TEXT         NOT NULL,
    sample_approach            TEXT,

    -- DESIGN | AD_HOC | CONTINUOUS
    test_frequency             VARCHAR(32)  NOT NULL DEFAULT 'AD_HOC',

    -- DESIGNED | RETIRED. Deliberately NOT effective/ineffective — that is
    -- OPERATING_EFFECTIVENESS, derived from executions, never this column.
    design_status              VARCHAR(32)  NOT NULL DEFAULT 'DESIGNED',

    created_at                 TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    created_by_principal_id    TEXT         NOT NULL DEFAULT app.current_principal_id(),

    CONSTRAINT control_test_definitions_design_status_known
        CHECK (design_status IN ('DESIGNED', 'RETIRED'))
);

CREATE UNIQUE INDEX idx_control_test_definitions_code_unique
    ON policy.control_test_definitions (test_code);

CREATE INDEX idx_control_test_definitions_control_ref
    ON policy.control_test_definitions (control_ref)
    WHERE design_status = 'DESIGNED';

-- ── control_test_executions ──────────────────────────────────────────────────
-- One actual test run. operating_effectiveness is DERIVED from these rows — the
-- latest execution's result for a control_ref — and never stored redundantly on
-- the control itself.

CREATE TABLE policy.control_test_executions (
    control_test_execution_id  UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    control_test_definition_id UUID        NOT NULL
        REFERENCES policy.control_test_definitions(control_test_definition_id),

    period_start               TIMESTAMPTZ NOT NULL,
    period_end                 TIMESTAMPTZ NOT NULL,

    population_description     TEXT,
    sample_description         TEXT,
    procedure_notes            TEXT,

    -- Evidence REFERENCES to the source evidence store — the evidence itself is
    -- never inlined here.
    evidence_refs              JSONB       NOT NULL DEFAULT '[]',

    tester_principal_id        TEXT        NOT NULL,

    -- EFFECTIVE | INEFFECTIVE | EXCEPTIONS_NOTED. This IS the
    -- OPERATING_EFFECTIVENESS signal, and it lives ONLY here.
    result                     VARCHAR(32) NOT NULL,
    exceptions_noted           TEXT,

    reviewer_principal_id      TEXT,
    reviewed_at                TIMESTAMPTZ,

    created_at                 TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    created_by_principal_id    TEXT        NOT NULL DEFAULT app.current_principal_id(),

    CONSTRAINT control_test_executions_result_known
        CHECK (result IN ('EFFECTIVE', 'INEFFECTIVE', 'EXCEPTIONS_NOTED')),

    CONSTRAINT control_test_executions_period_ordered
        CHECK (period_end > period_start),

    CONSTRAINT control_test_executions_evidence_is_array
        CHECK (jsonb_typeof(evidence_refs) = 'array'),

    -- A result of EXCEPTIONS_NOTED that notes no exceptions is not a result.
    CONSTRAINT control_test_executions_exceptions_are_described
        CHECK (result <> 'EXCEPTIONS_NOTED'
               OR (exceptions_noted IS NOT NULL AND btrim(exceptions_noted) <> '')),

    -- Review is an attributed event, both halves or neither.
    CONSTRAINT control_test_executions_review_is_attributed
        CHECK ((reviewed_at IS NULL) = (reviewer_principal_id IS NULL)),

    -- A tester may not review their own test. Segregation of duties is the
    -- entire reason an execution carries a reviewer field separate from a
    -- tester one.
    CONSTRAINT control_test_executions_reviewer_differs_from_tester
        CHECK (reviewer_principal_id IS NULL OR reviewer_principal_id <> tester_principal_id)
);

CREATE INDEX idx_control_test_executions_definition
    ON policy.control_test_executions (control_test_definition_id, period_end DESC);

CREATE TRIGGER control_test_executions_immutable
    BEFORE UPDATE OR DELETE ON policy.control_test_executions
    FOR EACH ROW EXECUTE FUNCTION app.reject_mutation();

-- ── attestations ─────────────────────────────────────────────────────────────
-- A signed, attributed assertion with scope and evidence — NOT automatic proof.
-- An attestation is never inferred from a control_test_execution's result and
-- never marks one effective on its own; the two objects stay independent.

CREATE TABLE policy.attestations (
    attestation_id          UUID         PRIMARY KEY DEFAULT gen_random_uuid(),

    statement               TEXT         NOT NULL,
    statement_version       VARCHAR(64)  NOT NULL,

    -- What this attestation is about — a control_ref, an obligation_id, a
    -- policy_code. Same "no registry backs it" doctrine as control_ref.
    subject_ref             VARCHAR(255) NOT NULL,

    period_start            TIMESTAMPTZ  NOT NULL,
    period_end              TIMESTAMPTZ  NOT NULL,

    signer_principal_id     TEXT         NOT NULL,
    -- CONTROL_OWNER | CFO | … — data only.
    signer_role             VARCHAR(64)  NOT NULL,
    signed_at               TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    evidence_refs           JSONB        NOT NULL DEFAULT '[]',
    expires_at              TIMESTAMPTZ,

    -- ACTIVE | CHALLENGED | REVOKED. A challenge or revocation is a status
    -- transition on this row, never a delete.
    attestation_status      VARCHAR(32)  NOT NULL DEFAULT 'ACTIVE',
    revocation_reason       TEXT,

    created_at              TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    created_by_principal_id TEXT         NOT NULL DEFAULT app.current_principal_id(),

    CONSTRAINT attestations_status_known
        CHECK (attestation_status IN ('ACTIVE', 'CHALLENGED', 'REVOKED')),

    CONSTRAINT attestations_period_ordered
        CHECK (period_end > period_start),

    CONSTRAINT attestations_evidence_is_array
        CHECK (jsonb_typeof(evidence_refs) = 'array'),

    -- A revoked attestation must say why. Withdrawing an assertion without a
    -- reason leaves the register unable to explain what changed.
    CONSTRAINT attestations_revoked_has_reason
        CHECK (attestation_status <> 'REVOKED'
               OR (revocation_reason IS NOT NULL AND btrim(revocation_reason) <> ''))
);

CREATE INDEX idx_attestations_subject
    ON policy.attestations (subject_ref, period_end DESC);

-- ── Row-level security ───────────────────────────────────────────────────────

ALTER TABLE policy.policies                   ENABLE ROW LEVEL SECURITY;
ALTER TABLE policy.policies                   FORCE  ROW LEVEL SECURITY;
ALTER TABLE policy.policy_versions            ENABLE ROW LEVEL SECURITY;
ALTER TABLE policy.policy_versions            FORCE  ROW LEVEL SECURITY;
ALTER TABLE policy.control_test_definitions   ENABLE ROW LEVEL SECURITY;
ALTER TABLE policy.control_test_definitions   FORCE  ROW LEVEL SECURITY;
ALTER TABLE policy.control_test_executions    ENABLE ROW LEVEL SECURITY;
ALTER TABLE policy.control_test_executions    FORCE  ROW LEVEL SECURITY;
ALTER TABLE policy.attestations               ENABLE ROW LEVEL SECURITY;
ALTER TABLE policy.attestations               FORCE  ROW LEVEL SECURITY;

-- policies is the named container and carries no scope of its own.
CREATE POLICY backend_all ON policy.policies
    FOR ALL TO zoiko_backend USING (true) WITH CHECK (true);
CREATE POLICY catalogue_read ON policy.policies
    FOR SELECT TO authenticated USING (true);

-- Asymmetric, as in configuration-feature-flag: a GLOBAL version applies to
-- every tenant, so a tenant connection must never be able to write one.
CREATE POLICY tenant_isolation ON policy.policy_versions
    FOR ALL
    TO zoiko_backend
    USING (tenant_id IS NULL OR tenant_id::text = app.current_tenant_id())
    WITH CHECK (
        (tenant_id IS NOT NULL AND tenant_id::text = app.current_tenant_id())
        OR (tenant_id IS NULL AND app.current_tenant_id() IS NULL)
    );

CREATE POLICY tenant_read ON policy.policy_versions
    FOR SELECT
    TO authenticated
    USING (tenant_id IS NULL OR tenant_id::text = app.current_tenant_id());

CREATE POLICY backend_all ON policy.control_test_definitions
    FOR ALL TO zoiko_backend USING (true) WITH CHECK (true);
CREATE POLICY catalogue_read ON policy.control_test_definitions
    FOR SELECT TO authenticated USING (true);

CREATE POLICY backend_all ON policy.control_test_executions
    FOR ALL TO zoiko_backend USING (true) WITH CHECK (true);
CREATE POLICY catalogue_read ON policy.control_test_executions
    FOR SELECT TO authenticated USING (true);

CREATE POLICY backend_all ON policy.attestations
    FOR ALL TO zoiko_backend USING (true) WITH CHECK (true);
CREATE POLICY catalogue_read ON policy.attestations
    FOR SELECT TO authenticated USING (true);

-- ── Grants ───────────────────────────────────────────────────────────────────

GRANT SELECT ON policy.policies                 TO authenticated;
GRANT SELECT ON policy.policy_versions          TO authenticated;
GRANT SELECT ON policy.control_test_definitions TO authenticated;
GRANT SELECT ON policy.control_test_executions  TO authenticated;
GRANT SELECT ON policy.attestations             TO authenticated;

-- policies and control_test_definitions are immutable once created: a change is
-- a new row, so neither gets UPDATE.
GRANT SELECT, INSERT         ON policy.policies                 TO zoiko_backend;
GRANT SELECT, INSERT         ON policy.control_test_definitions TO zoiko_backend;

-- policy_versions transitions DRAFT → ACTIVE → SUPERSEDED → RETIRED.
GRANT SELECT, INSERT, UPDATE ON policy.policy_versions          TO zoiko_backend;

-- An execution is the record of a test that was run; it is never revised.
GRANT SELECT, INSERT         ON policy.control_test_executions  TO zoiko_backend;

-- An attestation transitions ACTIVE → CHALLENGED / REVOKED.
GRANT SELECT, INSERT, UPDATE ON policy.attestations             TO zoiko_backend;


-- ============================================================================
-- FILE: 0022_employee_master_svc.sql
-- ============================================================================

-- 0022_employee_master_svc.sql
-- employee-master-svc → schema `employee_master`
--
-- Squashed end state of 000001_initial_schema and 000002_hr_profile_fields.
-- One table: employees.
--
-- ── This service is the employee identity other services resolve against ─────
-- leave-absence-svc, compensation-svc and payroll-run-svc all call
-- GET /v1/employees/{id} to learn which legal entity an employee belongs to,
-- and each fails closed when it cannot. That makes this table the root of the
-- HR domain's scope resolution, which is why it lands before the three
-- migrations that follow it.
--
-- ── Personal data is separated from employment data ──────────────────────────
-- The Go store reads two different projections: a full one for a single
-- employee, and a directory one for a listing that deliberately omits date of
-- birth, gender, personal email and both address fields. A caller enumerating a
-- legal entity is building a directory or a headcount rollup and needs none of
-- them.
--
-- That split is a projection in the service, not a boundary in the schema, so
-- it protects nothing here on its own. The `employee_directory` view below
-- makes it real for anything reaching the table through PostgREST: the
-- `authenticated` role is granted the view and nothing on the base table.
--
-- ── Gender is optional to disclose ───────────────────────────────────────────
-- NULL and 'UNSPECIFIED' mean different things and both are allowed. NULL is
-- "never asked"; UNSPECIFIED is a choice the employee made. Collapsing them
-- would discard the distinction and misreport the second as missing data.

CREATE SCHEMA IF NOT EXISTS employee_master;

COMMENT ON SCHEMA employee_master IS
    'employee-master-svc. Authoritative employee record and the legal-entity scope other HR services resolve against. Holds personal data — expose employee_directory through PostgREST, not the base table.';

GRANT USAGE ON SCHEMA employee_master TO zoiko_backend, authenticated;

-- ── employees ────────────────────────────────────────────────────────────────

CREATE TABLE employee_master.employees (
    employee_id         UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id           VARCHAR(255) NOT NULL,
    legal_entity_id     VARCHAR(255) NOT NULL,

    employee_number     VARCHAR(100) NOT NULL,
    first_name          VARCHAR(100) NOT NULL,
    last_name           VARCHAR(100) NOT NULL,
    email               VARCHAR(255) NOT NULL,
    phone               VARCHAR(50),
    job_title           VARCHAR(150) NOT NULL DEFAULT 'Employee',

    department_id       VARCHAR(255),
    manager_employee_id UUID,

    -- FULL_TIME | PART_TIME | CONTRACTOR
    worker_type         VARCHAR(50)  NOT NULL,
    -- ONBOARDING | ACTIVE | SUSPENDED | TERMINATED
    status              VARCHAR(50)  NOT NULL,

    hire_date           DATE         NOT NULL,
    termination_date    DATE,

    effective_from      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    effective_to        TIMESTAMPTZ,

    -- ── Personal profile ────────────────────────────────────────────────────
    date_of_birth       DATE,
    gender              VARCHAR(30),
    profile_picture_url VARCHAR(500),
    personal_email      VARCHAR(255),
    work_email          VARCHAR(255),

    -- ── Address ─────────────────────────────────────────────────────────────
    current_address     TEXT,
    permanent_address   TEXT,
    city                VARCHAR(100),
    state               VARCHAR(100),
    country             VARCHAR(100),
    postal_code         VARCHAR(20),

    -- ── Org placement ───────────────────────────────────────────────────────
    -- Reporting labels alongside the authoritative department_id.
    -- org-structure-svc owns the real hierarchy; these are the free-text
    -- groupings HR reporting and payroll cost splits need.
    company             VARCHAR(200),
    business_unit       VARCHAR(200),
    division            VARCHAR(200),
    team                VARCHAR(200),
    designation_id      VARCHAR(255),
    confirmation_date   DATE,

    created_at          TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    -- The vocabulary the domain defines, enforced in Go and — before this —
    -- nowhere else, so any other writer could leave a value no consumer knows
    -- how to read.
    CONSTRAINT employees_worker_type_known
        CHECK (worker_type IN ('FULL_TIME', 'PART_TIME', 'CONTRACTOR')),
    CONSTRAINT employees_status_known
        CHECK (status IN ('ONBOARDING', 'ACTIVE', 'SUSPENDED', 'TERMINATED')),

    -- Optional to disclose, so nullable; a controlled vocabulary when given.
    CONSTRAINT employees_gender_check
        CHECK (gender IS NULL OR gender IN ('MALE', 'FEMALE', 'NON_BINARY', 'OTHER', 'UNSPECIFIED')),

    -- Nobody was confirmed before they were hired.
    CONSTRAINT employees_confirmation_after_hire_check
        CHECK (confirmation_date IS NULL OR confirmation_date >= hire_date),

    -- Nor terminated before they were hired.
    CONSTRAINT employees_termination_after_hire_check
        CHECK (termination_date IS NULL OR termination_date >= hire_date),

    -- A TERMINATED employee must say when. Without this, a terminated row is a
    -- record that somebody left and no account of when — which is the whole
    -- reason downstream payroll reads the status at all.
    CONSTRAINT employees_terminated_has_date
        CHECK (status <> 'TERMINATED' OR termination_date IS NOT NULL),

    -- An employee is not their own manager. A self-reference would make the
    -- reporting chain a cycle of one and hang any recursive walk of it.
    CONSTRAINT employees_manager_not_self
        CHECK (manager_employee_id IS NULL OR manager_employee_id <> employee_id),

    -- The target of the composite self-reference below.
    CONSTRAINT employees_tenant_id_unique UNIQUE (tenant_id, employee_id)
);

-- A manager in another tenant is unrepresentable. The single-column form would
-- have accepted one: nothing made the referenced row's tenant agree with this
-- one's, and a reporting chain that crosses tenants leaks the org structure of
-- both.
ALTER TABLE employee_master.employees
    ADD CONSTRAINT employees_manager_same_tenant
    FOREIGN KEY (tenant_id, manager_employee_id)
    REFERENCES employee_master.employees (tenant_id, employee_id);

CREATE UNIQUE INDEX idx_employees_tenant_email
    ON employee_master.employees (tenant_id, email);
CREATE UNIQUE INDEX idx_employees_tenant_number
    ON employee_master.employees (tenant_id, employee_number);

-- Work email is an addressable identity inside a tenant, so it carries the same
-- uniqueness guarantee as the primary email. Partial: the many rows with no
-- work email must not collide with each other.
CREATE UNIQUE INDEX idx_employees_tenant_work_email
    ON employee_master.employees (tenant_id, work_email)
    WHERE work_email IS NOT NULL;

CREATE INDEX idx_employees_tenant_entity_status
    ON employee_master.employees (tenant_id, legal_entity_id, status);
CREATE INDEX idx_employees_tenant_dept
    ON employee_master.employees (tenant_id, department_id);
CREATE INDEX idx_employees_tenant_manager
    ON employee_master.employees (tenant_id, manager_employee_id);

-- Reporting rollups filter on these; without them a division-level headcount
-- query degrades to a full scan of the tenant's employees.
CREATE INDEX idx_employees_tenant_business_unit
    ON employee_master.employees (tenant_id, business_unit)
    WHERE business_unit IS NOT NULL;
CREATE INDEX idx_employees_tenant_division
    ON employee_master.employees (tenant_id, division)
    WHERE division IS NOT NULL;
CREATE INDEX idx_employees_tenant_designation
    ON employee_master.employees (tenant_id, designation_id)
    WHERE designation_id IS NOT NULL;

-- ── Row-level security ───────────────────────────────────────────────────────

ALTER TABLE employee_master.employees ENABLE ROW LEVEL SECURITY;
ALTER TABLE employee_master.employees FORCE  ROW LEVEL SECURITY;

CREATE POLICY tenant_isolation ON employee_master.employees
    FOR ALL
    TO zoiko_backend
    USING      (tenant_id = app.current_tenant_id())
    WITH CHECK (tenant_id = app.current_tenant_id());

-- ── employee_directory ───────────────────────────────────────────────────────
--
-- The directory projection, as a view rather than a convention. This is the
-- only employee data `authenticated` can reach: date of birth, gender, personal
-- email and both addresses are absent, and no grant on the base table restores
-- them.
--
-- security_invoker so the view runs under the caller's own privileges and the
-- table's RLS still applies. Without it the view would run as its owner and
-- hand every tenant's directory to every caller.

CREATE VIEW employee_master.employee_directory
WITH (security_invoker = true) AS
SELECT
    employee_id,
    tenant_id,
    legal_entity_id,
    employee_number,
    first_name,
    last_name,
    email,
    work_email,
    phone,
    job_title,
    department_id,
    manager_employee_id,
    worker_type,
    status,
    hire_date,
    termination_date,
    company,
    business_unit,
    division,
    team,
    designation_id,
    confirmation_date,
    created_at,
    updated_at
FROM employee_master.employees;

COMMENT ON VIEW employee_master.employee_directory IS
    'Employment data without personal data. Omits date_of_birth, gender, profile_picture_url, personal_email and both address fields. This is what authenticated callers read; the base table is reachable only by zoiko_backend.';

-- ── Grants ───────────────────────────────────────────────────────────────────

-- No DELETE: an employee record is the basis of every payslip, leave balance
-- and contract that referenced it. Departure is a status change, and
-- effective_to closes the row.
GRANT SELECT, INSERT, UPDATE ON employee_master.employees TO zoiko_backend;

-- Nothing on the base table for authenticated — only the directory view.
GRANT SELECT ON employee_master.employee_directory TO authenticated;


-- ============================================================================
-- FILE: 0023_leave_absence_svc.sql
-- ============================================================================

-- 0023_leave_absence_svc.sql
-- leave-absence-svc → schema `leave_absence`
--
-- Squashed end state of 000001_initial_schema, 000002_fix_race_and_idempotency
-- and 000003_leave_policy_and_holidays. Four tables: leave_types,
-- leave_balances, leave_requests, holidays.
--
-- Depends on 0022: an employee_id here is an employee_master employee, and the
-- service resolves the employee's legal entity through that service before it
-- authorizes anything.
--
-- ── Leave policy is enforced, not advisory ───────────────────────────────────
-- Before 000003 a leave type carried an accrual rate and a cap and nothing
-- else, so every request was reviewed by hand and nothing stopped someone
-- booking six months starting tomorrow. min_notice_days, max_consecutive_days
-- and requires_approval are checked by the service at submission time.
--
-- requires_approval DEFAULTs true. A leave type that arrives without the column
-- set must not silently stop being reviewed.
--
-- ── Holidays are retired, never deleted ──────────────────────────────────────
-- Leave approved against last year's calendar has to stay explicable, so a
-- holiday moves to INACTIVE and the row stays. The uniqueness index is partial
-- on ACTIVE so a retired date can be declared again.

CREATE SCHEMA IF NOT EXISTS leave_absence;

COMMENT ON SCHEMA leave_absence IS
    'leave-absence-svc. Leave types and their policy, per-employee balances, requests, and the holiday calendar. Policy on a leave type is enforced at submission, not advisory.';

GRANT USAGE ON SCHEMA leave_absence TO zoiko_backend, authenticated;

-- ── leave_types ──────────────────────────────────────────────────────────────

CREATE TABLE leave_absence.leave_types (
    leave_type_id           UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id               VARCHAR(255) NOT NULL,
    legal_entity_id         VARCHAR(255) NOT NULL,

    name                    VARCHAR(255) NOT NULL,
    -- VACATION | SICK_LEAVE | MATERNITY | PATERNITY | BEREAVEMENT | UNPAID | ...
    -- Deliberately not a CHECK: a legal entity may define its own statutory
    -- leave types, and the set is jurisdiction-dependent.
    code                    VARCHAR(50)  NOT NULL,

    is_paid                 BOOLEAN      NOT NULL DEFAULT true,
    accrual_rate_per_year   NUMERIC(10, 2) NOT NULL DEFAULT 0.00,
    max_balance             NUMERIC(10, 2) NOT NULL DEFAULT 0.00,

    -- ACTIVE | INACTIVE
    status                  VARCHAR(50)  NOT NULL,

    -- ── Policy ──────────────────────────────────────────────────────────────
    carry_forward_allowed   BOOLEAN      NOT NULL DEFAULT false,
    carry_forward_max_hours NUMERIC(10, 2) NOT NULL DEFAULT 0.00,

    -- Minimum days between submitting and the leave starting. 0 permits
    -- same-day and retroactive booking, which is what sick leave needs.
    min_notice_days         INTEGER      NOT NULL DEFAULT 0,

    -- Longest unbroken span, in calendar days, one request may cover.
    -- 0 means unlimited.
    max_consecutive_days    INTEGER      NOT NULL DEFAULT 0,

    -- false auto-approves on submission.
    requires_approval       BOOLEAN      NOT NULL DEFAULT true,

    -- Display metadata carried for the caller. The service never reads these.
    color_hex               VARCHAR(7),
    icon                    VARCHAR(50),

    created_at              TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at              TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    CONSTRAINT leave_types_status_known
        CHECK (status IN ('ACTIVE', 'INACTIVE')),

    CONSTRAINT leave_types_notice_non_negative_check
        CHECK (min_notice_days >= 0
           AND max_consecutive_days >= 0
           AND carry_forward_max_hours >= 0
           AND accrual_rate_per_year >= 0
           AND max_balance >= 0),

    -- Carrying forward with a zero cap would silently discard the whole balance
    -- at year end, which reads as a policy bug rather than a policy.
    CONSTRAINT leave_types_carry_forward_cap_check
        CHECK (NOT carry_forward_allowed OR carry_forward_max_hours > 0),

    CONSTRAINT leave_types_tenant_id_unique UNIQUE (tenant_id, leave_type_id)
);

-- A leave type code is the stable handle policy is configured against, so it
-- must not repeat within a legal entity.
CREATE UNIQUE INDEX idx_leave_types_tenant_entity_code
    ON leave_absence.leave_types (tenant_id, legal_entity_id, code);

CREATE INDEX idx_leave_types_tenant_entity
    ON leave_absence.leave_types (tenant_id, legal_entity_id);

-- ── leave_balances ───────────────────────────────────────────────────────────

CREATE TABLE leave_absence.leave_balances (
    balance_id      UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       VARCHAR(255) NOT NULL,
    employee_id     UUID         NOT NULL,
    leave_type_id   UUID         NOT NULL,

    allocated_hours NUMERIC(10, 2) NOT NULL DEFAULT 0.00,
    used_hours      NUMERIC(10, 2) NOT NULL DEFAULT 0.00,
    pending_hours   NUMERIC(10, 2) NOT NULL DEFAULT 0.00,

    updated_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    -- A balance in one tenant against another tenant's leave type is
    -- unrepresentable. The single-column reference in 000001 accepted it.
    CONSTRAINT leave_balances_type_same_tenant
        FOREIGN KEY (tenant_id, leave_type_id)
        REFERENCES leave_absence.leave_types (tenant_id, leave_type_id),

    CONSTRAINT unique_tenant_emp_leave_type
        UNIQUE (tenant_id, employee_id, leave_type_id),

    -- Hours are quantities, never negative. Used and pending hours that exceed
    -- what was allocated would report an available balance below zero, which
    -- the service treats as insufficient and would then never let anyone spend.
    CONSTRAINT leave_balances_hours_non_negative
        CHECK (allocated_hours >= 0 AND used_hours >= 0 AND pending_hours >= 0)
);

CREATE INDEX idx_leave_balances_tenant_emp
    ON leave_absence.leave_balances (tenant_id, employee_id);

-- ── leave_requests ───────────────────────────────────────────────────────────

CREATE TABLE leave_absence.leave_requests (
    request_id     UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id      VARCHAR(255) NOT NULL,
    employee_id    UUID         NOT NULL,
    leave_type_id  UUID         NOT NULL,

    start_date     DATE         NOT NULL,
    end_date       DATE         NOT NULL,
    total_hours    NUMERIC(10, 2) NOT NULL,
    reason         TEXT,

    -- SUBMITTED | APPROVED | REJECTED | CANCELLED
    status         VARCHAR(50)  NOT NULL,

    reviewer_id    VARCHAR(255),
    reviewer_notes TEXT,
    reviewed_at    TIMESTAMPTZ,

    correlation_id VARCHAR(255) NOT NULL DEFAULT '',

    created_at     TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at     TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    CONSTRAINT leave_requests_type_same_tenant
        FOREIGN KEY (tenant_id, leave_type_id)
        REFERENCES leave_absence.leave_types (tenant_id, leave_type_id),

    CONSTRAINT leave_requests_status_known
        CHECK (status IN ('SUBMITTED', 'APPROVED', 'REJECTED', 'CANCELLED')),

    -- Leave that ends before it starts is not a span. The service checks this;
    -- nothing else did.
    CONSTRAINT leave_requests_end_after_start
        CHECK (end_date >= start_date),

    CONSTRAINT leave_requests_hours_positive
        CHECK (total_hours > 0),

    -- A reviewed request must record who reviewed it and when. A row reading
    -- APPROVED with no reviewer is an approval nobody is accountable for.
    CONSTRAINT leave_requests_reviewed_has_reviewer
        CHECK (
            status IN ('SUBMITTED', 'CANCELLED')
            OR (reviewer_id IS NOT NULL AND reviewed_at IS NOT NULL)
        )
);

-- Idempotency: a retried submit resolves to the original request instead of
-- creating a duplicate and double-locking pending hours.
CREATE UNIQUE INDEX idx_leave_requests_tenant_correlation
    ON leave_absence.leave_requests (tenant_id, correlation_id)
    WHERE correlation_id <> '';

CREATE INDEX idx_leave_requests_tenant_emp
    ON leave_absence.leave_requests (tenant_id, employee_id);
CREATE INDEX idx_leave_requests_tenant_status
    ON leave_absence.leave_requests (tenant_id, status);

-- ── holidays ─────────────────────────────────────────────────────────────────
--
-- Public and company holidays per legal entity. Leave spanning a holiday should
-- not consume balance for that day, and before 000003 there was nowhere to
-- record which days those are.

CREATE TABLE leave_absence.holidays (
    holiday_id      UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       VARCHAR(255) NOT NULL,
    legal_entity_id VARCHAR(255) NOT NULL,

    name            VARCHAR(150) NOT NULL,
    holiday_date    DATE         NOT NULL,

    -- PUBLIC | COMPANY | OPTIONAL
    holiday_type    VARCHAR(50)  NOT NULL DEFAULT 'PUBLIC',

    -- Same calendar day every year.
    is_recurring    BOOLEAN      NOT NULL DEFAULT false,
    description     TEXT,

    -- ACTIVE | INACTIVE
    status          VARCHAR(50)  NOT NULL DEFAULT 'ACTIVE',

    created_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    CONSTRAINT holidays_type_check
        CHECK (holiday_type IN ('PUBLIC', 'COMPANY', 'OPTIONAL')),
    CONSTRAINT holidays_status_check
        CHECK (status IN ('ACTIVE', 'INACTIVE'))
);

-- One entry per day per entity. Partial on ACTIVE so a day can be retired and
-- then re-declared without tripping over the old row.
CREATE UNIQUE INDEX idx_holidays_tenant_entity_date
    ON leave_absence.holidays (tenant_id, legal_entity_id, holiday_date)
    WHERE status = 'ACTIVE';

-- The calendar is read by date range far more often than by anything else.
CREATE INDEX idx_holidays_tenant_entity_range
    ON leave_absence.holidays (tenant_id, legal_entity_id, holiday_date, status);

-- ── Row-level security ───────────────────────────────────────────────────────

ALTER TABLE leave_absence.leave_types    ENABLE ROW LEVEL SECURITY;
ALTER TABLE leave_absence.leave_types    FORCE  ROW LEVEL SECURITY;
ALTER TABLE leave_absence.leave_balances ENABLE ROW LEVEL SECURITY;
ALTER TABLE leave_absence.leave_balances FORCE  ROW LEVEL SECURITY;
ALTER TABLE leave_absence.leave_requests ENABLE ROW LEVEL SECURITY;
ALTER TABLE leave_absence.leave_requests FORCE  ROW LEVEL SECURITY;
ALTER TABLE leave_absence.holidays       ENABLE ROW LEVEL SECURITY;
ALTER TABLE leave_absence.holidays       FORCE  ROW LEVEL SECURITY;

CREATE POLICY tenant_isolation ON leave_absence.leave_types
    FOR ALL TO zoiko_backend
    USING      (tenant_id = app.current_tenant_id())
    WITH CHECK (tenant_id = app.current_tenant_id());

CREATE POLICY tenant_isolation ON leave_absence.leave_balances
    FOR ALL TO zoiko_backend
    USING      (tenant_id = app.current_tenant_id())
    WITH CHECK (tenant_id = app.current_tenant_id());

CREATE POLICY tenant_isolation ON leave_absence.leave_requests
    FOR ALL TO zoiko_backend
    USING      (tenant_id = app.current_tenant_id())
    WITH CHECK (tenant_id = app.current_tenant_id());

CREATE POLICY tenant_isolation ON leave_absence.holidays
    FOR ALL TO zoiko_backend
    USING      (tenant_id = app.current_tenant_id())
    WITH CHECK (tenant_id = app.current_tenant_id());

-- Leave types and the holiday calendar are policy an employee is entitled to
-- read: they say how much notice a request needs and which days are not working
-- days. Balances and requests are not — those are one employee's own record.
CREATE POLICY tenant_read ON leave_absence.leave_types
    FOR SELECT TO authenticated
    USING (tenant_id = app.current_tenant_id());

CREATE POLICY tenant_read ON leave_absence.holidays
    FOR SELECT TO authenticated
    USING (tenant_id = app.current_tenant_id() AND status = 'ACTIVE');

-- ── Grants ───────────────────────────────────────────────────────────────────

-- No DELETE anywhere: a leave request is the record of an absence that was
-- taken or refused, a balance is the running account behind it, and a holiday
-- explains a payslip. All three retire by status or end-date instead.
GRANT SELECT, INSERT, UPDATE ON leave_absence.leave_types    TO zoiko_backend;
GRANT SELECT, INSERT, UPDATE ON leave_absence.leave_balances TO zoiko_backend;
GRANT SELECT, INSERT, UPDATE ON leave_absence.leave_requests TO zoiko_backend;
GRANT SELECT, INSERT, UPDATE ON leave_absence.holidays       TO zoiko_backend;

GRANT SELECT ON leave_absence.leave_types TO authenticated;
GRANT SELECT ON leave_absence.holidays    TO authenticated;


-- ============================================================================
-- FILE: 0024_compensation_svc.sql
-- ============================================================================

-- 0024_compensation_svc.sql
-- compensation-svc → schema `compensation`
--
-- Squashed end state of 000001_initial_schema, 000002_fix_race_and_idempotency
-- and 000003_salary_components. Five tables: compensation_structures,
-- wage_revisions, bonus_grants, salary_components, structure_components.
--
-- Depends on 0022: an employee_id here is an employee_master employee.
--
-- ── What 000003 added, and why ───────────────────────────────────────────────
-- A compensation_structure was a min/max band and nothing else, so nothing
-- downstream could answer "what is this salary actually made of". Payroll needs
-- the breakdown: which elements are earnings, which are deductions, which are
-- taxable, and how each is derived from the base. payroll-run-svc reads it
-- through /v1/compensation/structures/{id}/breakdown and puts the resulting
-- lines on the payslip.
--
-- ── Derivations are modelled, not evaluated ──────────────────────────────────
-- zoiko-one, where this was ported from, stored the amount as a free-text
-- `amount_or_formula VARCHAR(255)`. That does not travel: a governance service
-- cannot evaluate arbitrary expressions and still explain a payslip. The two
-- derivations payroll actually needs are declared explicitly instead — a fixed
-- amount, or a percentage of the base.
--
-- Percentages resolve against the base, never against a running total, so the
-- result does not depend on the order the components happen to be stored in.
-- That property lives in the service; the schema keeps the inputs honest.

CREATE SCHEMA IF NOT EXISTS compensation;

COMMENT ON SCHEMA compensation IS
    'compensation-svc. Pay structures and what they are composed of, wage revision history, and bonus grants. The component breakdown is what payroll-run-svc resolves a payslip from.';

GRANT USAGE ON SCHEMA compensation TO zoiko_backend, authenticated;

-- ── compensation_structures ──────────────────────────────────────────────────

CREATE TABLE compensation.compensation_structures (
    structure_id        UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id           VARCHAR(255) NOT NULL,
    legal_entity_id     VARCHAR(255) NOT NULL,

    name                VARCHAR(150) NOT NULL,
    -- SALARY | HOURLY
    pay_type            VARCHAR(50)  NOT NULL,

    min_amount          NUMERIC(18, 4) NOT NULL,
    max_amount          NUMERIC(18, 4) NOT NULL,
    currency            VARCHAR(3)   NOT NULL,
    overtime_multiplier NUMERIC(5, 2) NOT NULL DEFAULT 1.50,

    correlation_id      VARCHAR(255) NOT NULL DEFAULT '',

    created_at          TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at          TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    CONSTRAINT comp_structures_pay_type_known
        CHECK (pay_type IN ('SALARY', 'HOURLY')),

    -- An inverted band admits no salary at all, and every later "is this wage
    -- inside its band" check would answer no for every possible amount.
    CONSTRAINT comp_structures_band_ordered
        CHECK (max_amount >= min_amount),
    CONSTRAINT comp_structures_amounts_non_negative
        CHECK (min_amount >= 0),

    -- Overtime paid below the normal rate is not overtime.
    CONSTRAINT comp_structures_overtime_at_least_one
        CHECK (overtime_multiplier >= 1.00),

    CONSTRAINT comp_structures_tenant_id_unique UNIQUE (tenant_id, structure_id)
);

CREATE UNIQUE INDEX idx_comp_struct_tenant_correlation
    ON compensation.compensation_structures (tenant_id, correlation_id)
    WHERE correlation_id <> '';

CREATE INDEX idx_comp_struct_tenant_entity
    ON compensation.compensation_structures (tenant_id, legal_entity_id);

-- ── wage_revisions ───────────────────────────────────────────────────────────

CREATE TABLE compensation.wage_revisions (
    revision_id    UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id      VARCHAR(255) NOT NULL,
    employee_id    UUID         NOT NULL,
    structure_id   UUID,

    -- SALARY | HOURLY
    pay_type       VARCHAR(50)  NOT NULL,
    amount         NUMERIC(18, 4) NOT NULL,
    currency       VARCHAR(3)   NOT NULL,

    effective_from DATE         NOT NULL,
    effective_to   DATE,

    reason         TEXT         NOT NULL,
    revised_by     VARCHAR(255) NOT NULL DEFAULT app.current_principal_id(),

    -- ACTIVE | SUPERSEDED
    status         VARCHAR(50)  NOT NULL,

    correlation_id VARCHAR(255) NOT NULL DEFAULT '',

    created_at     TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    -- A revision against another tenant's structure is unrepresentable.
    CONSTRAINT wage_revisions_structure_same_tenant
        FOREIGN KEY (tenant_id, structure_id)
        REFERENCES compensation.compensation_structures (tenant_id, structure_id),

    CONSTRAINT wage_revisions_pay_type_known
        CHECK (pay_type IN ('SALARY', 'HOURLY')),
    CONSTRAINT wage_revisions_status_known
        CHECK (status IN ('ACTIVE', 'SUPERSEDED')),
    CONSTRAINT wage_revisions_amount_non_negative
        CHECK (amount >= 0),

    -- A revision that ends before it starts was never in force.
    CONSTRAINT wage_revisions_period_ordered
        CHECK (effective_to IS NULL OR effective_to >= effective_from),

    -- The ACTIVE revision is the one in force now, so it has no end date.
    -- Without this, a row could read ACTIVE with an effective_to in the past
    -- and payroll would keep paying it.
    CONSTRAINT wage_revisions_active_is_open
        CHECK (status <> 'ACTIVE' OR effective_to IS NULL)
);

-- At most one ACTIVE wage revision per employee, at the database level. Without
-- it, two concurrent ReviseWage calls could both pass the application's
-- supersede-then-insert sequence and leave two ACTIVE rows — and
-- GetActiveWageRevision (LIMIT 1, no ORDER BY) would hand payroll an arbitrary
-- one of them.
CREATE UNIQUE INDEX idx_wage_revisions_one_active
    ON compensation.wage_revisions (tenant_id, employee_id)
    WHERE status = 'ACTIVE';

CREATE UNIQUE INDEX idx_wage_rev_tenant_correlation
    ON compensation.wage_revisions (tenant_id, correlation_id)
    WHERE correlation_id <> '';

CREATE INDEX idx_wage_rev_tenant_emp
    ON compensation.wage_revisions (tenant_id, employee_id);
CREATE INDEX idx_wage_rev_tenant_status
    ON compensation.wage_revisions (tenant_id, status);

-- ── bonus_grants ─────────────────────────────────────────────────────────────

CREATE TABLE compensation.bonus_grants (
    grant_id       UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id      VARCHAR(255) NOT NULL,
    employee_id    UUID         NOT NULL,

    -- PERFORMANCE | ANNUAL | SIGNING | RETENTION
    bonus_type     VARCHAR(50)  NOT NULL,
    amount         NUMERIC(18, 4) NOT NULL,
    currency       VARCHAR(3)   NOT NULL,
    grant_date     DATE         NOT NULL,

    -- PENDING | APPROVED | PAID | CANCELLED
    status         VARCHAR(50)  NOT NULL,
    approved_by    VARCHAR(255),

    correlation_id VARCHAR(255) NOT NULL DEFAULT '',

    created_at     TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    CONSTRAINT bonus_grants_type_known
        CHECK (bonus_type IN ('PERFORMANCE', 'ANNUAL', 'SIGNING', 'RETENTION')),
    CONSTRAINT bonus_grants_status_known
        CHECK (status IN ('PENDING', 'APPROVED', 'PAID', 'CANCELLED')),
    CONSTRAINT bonus_grants_amount_non_negative
        CHECK (amount >= 0),

    -- An approved or paid bonus names who approved it. Money that moved with
    -- nobody accountable for the decision is the thing this table exists to
    -- prevent.
    CONSTRAINT bonus_grants_approved_has_approver
        CHECK (status NOT IN ('APPROVED', 'PAID') OR approved_by IS NOT NULL)
);

CREATE UNIQUE INDEX idx_bonus_grants_tenant_correlation
    ON compensation.bonus_grants (tenant_id, correlation_id)
    WHERE correlation_id <> '';

CREATE INDEX idx_bonus_grants_tenant_emp
    ON compensation.bonus_grants (tenant_id, employee_id);
CREATE INDEX idx_bonus_grants_tenant_status
    ON compensation.bonus_grants (tenant_id, status);

-- ── salary_components ────────────────────────────────────────────────────────
--
-- The catalogue of pay elements a legal entity can compose into its structures.

CREATE TABLE compensation.salary_components (
    component_id    UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id       VARCHAR(255) NOT NULL,
    legal_entity_id VARCHAR(255) NOT NULL,

    name            VARCHAR(150) NOT NULL,
    -- HRA, TRANSPORT, PF, PROF_TAX, ... Entity-defined, so no CHECK.
    code            VARCHAR(50)  NOT NULL,

    -- EARNING | DEDUCTION
    component_type  VARCHAR(20)  NOT NULL,

    -- Taxable unless stated otherwise. Defaulting the other way would
    -- under-report income by omission.
    is_taxable      BOOLEAN      NOT NULL DEFAULT true,

    default_amount  NUMERIC(18, 4),
    currency        VARCHAR(3)   NOT NULL,
    description     TEXT,

    -- ACTIVE | INACTIVE
    status          VARCHAR(50)  NOT NULL DEFAULT 'ACTIVE',

    created_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    CONSTRAINT salary_components_type_check
        CHECK (component_type IN ('EARNING', 'DEDUCTION')),
    CONSTRAINT salary_components_status_check
        CHECK (status IN ('ACTIVE', 'INACTIVE')),

    -- A negative component would flip an earning into a deduction by stealth.
    CONSTRAINT salary_components_amount_check
        CHECK (default_amount IS NULL OR default_amount >= 0),

    CONSTRAINT salary_components_tenant_id_unique UNIQUE (tenant_id, component_id)
);

-- A component code is the stable handle payroll refers to, so it is unique
-- within a legal entity. Partial on ACTIVE so a retired code can be reissued.
CREATE UNIQUE INDEX idx_salary_components_entity_code
    ON compensation.salary_components (tenant_id, legal_entity_id, code)
    WHERE status = 'ACTIVE';

CREATE INDEX idx_salary_components_tenant_entity
    ON compensation.salary_components (tenant_id, legal_entity_id, status);

-- ── structure_components ─────────────────────────────────────────────────────
--
-- Which components make up a structure, and how each is derived.

CREATE TABLE compensation.structure_components (
    structure_component_id UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id              VARCHAR(255) NOT NULL,
    structure_id           UUID         NOT NULL,
    component_id           UUID         NOT NULL,

    -- FIXED | PERCENT_OF_BASE
    calculation_method     VARCHAR(30)  NOT NULL,
    calculation_value      NUMERIC(18, 4) NOT NULL,

    -- Payslip display order.
    sequence               INTEGER      NOT NULL DEFAULT 0,

    created_at             TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at             TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    -- Both parents must be in this row's tenant. A structure composed from
    -- another entity's components would produce a payslip that crosses a legal
    -- boundary, and the single-column form would have allowed it.
    CONSTRAINT structure_components_structure_same_tenant
        FOREIGN KEY (tenant_id, structure_id)
        REFERENCES compensation.compensation_structures (tenant_id, structure_id),
    CONSTRAINT structure_components_component_same_tenant
        FOREIGN KEY (tenant_id, component_id)
        REFERENCES compensation.salary_components (tenant_id, component_id),

    CONSTRAINT structure_components_method_check
        CHECK (calculation_method IN ('FIXED', 'PERCENT_OF_BASE')),
    CONSTRAINT structure_components_value_check
        CHECK (calculation_value >= 0),

    -- A percentage over 100 of the base is a data-entry slip, not a policy.
    CONSTRAINT structure_components_percent_range_check
        CHECK (calculation_method <> 'PERCENT_OF_BASE' OR calculation_value <= 100),

    -- One line per component per structure; changing the amount updates the row.
    CONSTRAINT structure_components_unique UNIQUE (structure_id, component_id)
);

-- Reading a structure's composition is the hot path: payroll does it per
-- employee per run, always in payslip order.
CREATE INDEX idx_structure_components_structure
    ON compensation.structure_components (tenant_id, structure_id, sequence);

-- ── Row-level security ───────────────────────────────────────────────────────

ALTER TABLE compensation.compensation_structures ENABLE ROW LEVEL SECURITY;
ALTER TABLE compensation.compensation_structures FORCE  ROW LEVEL SECURITY;
ALTER TABLE compensation.wage_revisions          ENABLE ROW LEVEL SECURITY;
ALTER TABLE compensation.wage_revisions          FORCE  ROW LEVEL SECURITY;
ALTER TABLE compensation.bonus_grants            ENABLE ROW LEVEL SECURITY;
ALTER TABLE compensation.bonus_grants            FORCE  ROW LEVEL SECURITY;
ALTER TABLE compensation.salary_components       ENABLE ROW LEVEL SECURITY;
ALTER TABLE compensation.salary_components       FORCE  ROW LEVEL SECURITY;
ALTER TABLE compensation.structure_components    ENABLE ROW LEVEL SECURITY;
ALTER TABLE compensation.structure_components    FORCE  ROW LEVEL SECURITY;

CREATE POLICY tenant_isolation ON compensation.compensation_structures
    FOR ALL TO zoiko_backend
    USING      (tenant_id = app.current_tenant_id())
    WITH CHECK (tenant_id = app.current_tenant_id());

CREATE POLICY tenant_isolation ON compensation.wage_revisions
    FOR ALL TO zoiko_backend
    USING      (tenant_id = app.current_tenant_id())
    WITH CHECK (tenant_id = app.current_tenant_id());

CREATE POLICY tenant_isolation ON compensation.bonus_grants
    FOR ALL TO zoiko_backend
    USING      (tenant_id = app.current_tenant_id())
    WITH CHECK (tenant_id = app.current_tenant_id());

CREATE POLICY tenant_isolation ON compensation.salary_components
    FOR ALL TO zoiko_backend
    USING      (tenant_id = app.current_tenant_id())
    WITH CHECK (tenant_id = app.current_tenant_id());

CREATE POLICY tenant_isolation ON compensation.structure_components
    FOR ALL TO zoiko_backend
    USING      (tenant_id = app.current_tenant_id())
    WITH CHECK (tenant_id = app.current_tenant_id());

-- Nothing here is readable by `authenticated`. Every table in this schema is
-- either an individual's pay or the bands and components that would let one
-- employee derive a colleague's. Reads go through the service, which resolves
-- the caller's own employee_id first.

-- ── Grants ───────────────────────────────────────────────────────────────────

-- wage_revisions and bonus_grants take no DELETE and no UPDATE beyond the
-- supersede/approve transitions the service performs: both are the history of
-- what somebody was paid and who decided it.
GRANT SELECT, INSERT, UPDATE ON compensation.compensation_structures TO zoiko_backend;
GRANT SELECT, INSERT, UPDATE ON compensation.wage_revisions          TO zoiko_backend;
GRANT SELECT, INSERT, UPDATE ON compensation.bonus_grants            TO zoiko_backend;
GRANT SELECT, INSERT, UPDATE ON compensation.salary_components       TO zoiko_backend;

-- structure_components is the exception that needs DELETE: a structure's
-- composition is replaced as a set, and a partial write would leave a structure
-- computing a payslip nobody intended. The service clears and re-inserts inside
-- one transaction.
GRANT SELECT, INSERT, UPDATE, DELETE ON compensation.structure_components TO zoiko_backend;


-- ============================================================================
-- FILE: 0025_payroll_run_svc.sql
-- ============================================================================

-- 0025_payroll_run_svc.sql
-- payroll-run-svc → schema `payroll_run`
--
-- Squashed end state of 000001_initial_schema, 000002_add_idempotency_index,
-- 000003_add_finalization_linkage and 000004_payslip_components. Four tables:
-- payroll_runs, pay_slips, pay_slip_items, shadow_payroll_comparisons.
--
-- Depends on 0022 and 0024: the service resolves each employee through
-- employee-master-svc, takes the base salary from employment-contracts-svc, and
-- reads the component composition from compensation-svc.
--
-- ── What 000004 added, and why ───────────────────────────────────────────────
-- A pay slip recorded four totals and nothing else, so nobody could answer "why
-- is my net pay this number". The lines behind the totals now come from
-- compensation-svc's breakdown endpoint and are stored with the slip that used
-- them.
--
-- ── The lines are copied, not referenced ─────────────────────────────────────
-- pay_slip_items carries calculation_method and calculation_value rather than
-- pointing at compensation.structure_components. If a structure changes 40% HRA
-- to 35% next quarter, this payslip must still show the 40% it was actually
-- paid on. A foreign key would make the slip re-read as whatever the structure
-- says today, which is the opposite of what a payslip is for.
--
-- That is also why this schema holds no FK into `compensation` at all:
-- structure_id is recorded as a plain UUID, an audit trail of which structure
-- was used, not a live join.
--
-- ── Finalized runs are immutable ─────────────────────────────────────────────
-- Two triggers below refuse UPDATE and DELETE of a COMPLETED run, and of any
-- slip belonging to one. A trigger rather than a grant or a policy because it
-- binds even a BYPASSRLS role such as Supabase's service_role, which neither of
-- those does.
--
-- They are service-local functions rather than the shared app.reject_mutation()
-- because these tables are not append-only: a run is updated repeatedly while it
-- is being calculated, and its slips are cleared and re-derived on every
-- recalculation. Only mutation AFTER finalization is refused, which is a
-- conditional the shared function does not express.

CREATE SCHEMA IF NOT EXISTS payroll_run;

COMMENT ON SCHEMA payroll_run IS
    'payroll-run-svc. Payroll runs, the payslips they produced and the lines behind each payslip. A COMPLETED run and its slips are immutable, enforced by trigger.';

GRANT USAGE ON SCHEMA payroll_run TO zoiko_backend, authenticated;

-- ── payroll_runs ─────────────────────────────────────────────────────────────

CREATE TABLE payroll_run.payroll_runs (
    run_id                 UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id              VARCHAR(255) NOT NULL,
    legal_entity_id        VARCHAR(255) NOT NULL,

    run_number             VARCHAR(100) NOT NULL,
    pay_period_start       DATE         NOT NULL,
    pay_period_end         DATE         NOT NULL,
    pay_date               DATE         NOT NULL,

    -- INITIATED | CALCULATED | BLOCKED | COMPLETED
    status                 VARCHAR(50)  NOT NULL,
    is_shadow_run          BOOLEAN      NOT NULL DEFAULT false,

    total_gross_pay        NUMERIC(18, 4) NOT NULL DEFAULT 0,
    total_net_pay          NUMERIC(18, 4) NOT NULL DEFAULT 0,
    total_tax_deductions   NUMERIC(18, 4) NOT NULL DEFAULT 0,
    total_other_deductions NUMERIC(18, 4) NOT NULL DEFAULT 0,
    employee_count         INT          NOT NULL DEFAULT 0,

    correlation_id         VARCHAR(255) NOT NULL DEFAULT '',

    created_at             TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at             TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    finalized_at           TIMESTAMPTZ,

    -- Populated only when the caller finalizing the run supplies one; no
    -- fabricated value when none exists yet.
    governance_decision_id TEXT,
    -- Computed by the service over the run's own locked totals at the moment of
    -- finalization — not invented, not caller-supplied.
    snapshot_hash          TEXT,

    CONSTRAINT payroll_runs_status_known
        CHECK (status IN ('INITIATED', 'CALCULATED', 'BLOCKED', 'COMPLETED')),

    -- A pay period that ends before it starts is not a period, and the pay date
    -- cannot precede the work it pays for.
    CONSTRAINT payroll_runs_period_ordered
        CHECK (pay_period_end >= pay_period_start),
    CONSTRAINT payroll_runs_pay_date_after_period
        CHECK (pay_date >= pay_period_start),

    CONSTRAINT payroll_runs_totals_non_negative
        CHECK (total_gross_pay >= 0
           AND total_tax_deductions >= 0
           AND total_other_deductions >= 0
           AND employee_count >= 0),

    -- A COMPLETED run must record when it was finalized and the hash that makes
    -- it reproducible. Without both, "finalized" is a status with nothing behind
    -- it and an auditor has only the final numbers to trust.
    CONSTRAINT payroll_runs_completed_is_evidenced
        CHECK (
            status <> 'COMPLETED'
            OR (finalized_at IS NOT NULL AND snapshot_hash IS NOT NULL)
        ),

    CONSTRAINT payroll_runs_tenant_id_unique UNIQUE (tenant_id, run_id)
);

-- Idempotency: a retried initiate (a client timeout on a request that actually
-- succeeded) resolves to the original run instead of creating a duplicate run
-- for the same period.
CREATE UNIQUE INDEX idx_payroll_runs_tenant_correlation
    ON payroll_run.payroll_runs (tenant_id, correlation_id)
    WHERE correlation_id <> '';

CREATE INDEX idx_payroll_runs_tenant_entity
    ON payroll_run.payroll_runs (tenant_id, legal_entity_id);
CREATE INDEX idx_payroll_runs_tenant_status
    ON payroll_run.payroll_runs (tenant_id, status);

-- ── pay_slips ────────────────────────────────────────────────────────────────

CREATE TABLE payroll_run.pay_slips (
    slip_id             UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id           VARCHAR(255) NOT NULL,
    run_id              UUID         NOT NULL,

    employee_id         UUID         NOT NULL,
    employee_number     VARCHAR(100) NOT NULL,
    employee_name       VARCHAR(200) NOT NULL,

    gross_pay           NUMERIC(18, 4) NOT NULL,
    tax_withheld        NUMERIC(18, 4) NOT NULL,
    benefits_deductions NUMERIC(18, 4) NOT NULL,
    net_pay             NUMERIC(18, 4) NOT NULL,

    currency            VARCHAR(3)   NOT NULL,
    effective_date      DATE         NOT NULL,

    -- The base tax was actually applied to. Not the same as gross: non-taxable
    -- earnings are excluded and taxable deductions come off it.
    taxable_amount      NUMERIC(18, 4) NOT NULL DEFAULT 0,

    -- The compensation structure this slip was computed from. Nullable: an
    -- employee paid a flat base salary has none, which is a valid state rather
    -- than missing data. Deliberately not a foreign key — see the header.
    structure_id        UUID,

    created_at          TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    -- A slip in one tenant against another tenant's run is unrepresentable.
    -- The single-column reference in 000001 accepted it.
    CONSTRAINT pay_slips_run_same_tenant
        FOREIGN KEY (tenant_id, run_id)
        REFERENCES payroll_run.payroll_runs (tenant_id, run_id) ON DELETE CASCADE,

    -- Gross, tax and deductions are quantities. Net is not: deductions can
    -- legitimately exceed pay — an advance recovery, say — and reporting that
    -- as anything other than negative would hide it from the payroll manager
    -- who has to act on it.
    CONSTRAINT pay_slips_amounts_non_negative
        CHECK (gross_pay >= 0
           AND tax_withheld >= 0
           AND benefits_deductions >= 0
           AND taxable_amount >= 0),

    -- Tax cannot be withheld on more than the whole gross.
    CONSTRAINT pay_slips_taxable_within_gross
        CHECK (taxable_amount <= gross_pay),

    CONSTRAINT pay_slips_tenant_id_unique UNIQUE (tenant_id, slip_id)
);

CREATE INDEX idx_pay_slips_tenant_run
    ON payroll_run.pay_slips (tenant_id, run_id);
CREATE INDEX idx_pay_slips_tenant_emp
    ON payroll_run.pay_slips (tenant_id, employee_id);

-- ── pay_slip_items ───────────────────────────────────────────────────────────

CREATE TABLE payroll_run.pay_slip_items (
    item_id            UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id          VARCHAR(255) NOT NULL,
    slip_id            UUID         NOT NULL,

    -- Which catalogue component this came from, for tracing. Not a foreign key
    -- into `compensation`: the component may be retired later, and this line
    -- must keep reading the same either way.
    component_id       UUID,

    component_code     VARCHAR(50)  NOT NULL,
    component_name     VARCHAR(150) NOT NULL,
    -- EARNING | DEDUCTION
    component_type     VARCHAR(20)  NOT NULL,
    is_taxable         BOOLEAN      NOT NULL DEFAULT true,

    -- FIXED | PERCENT_OF_BASE — copied, so the slip shows the derivation it was
    -- actually paid on rather than whatever the structure says today.
    calculation_method VARCHAR(30)  NOT NULL,
    calculation_value  NUMERIC(18, 4) NOT NULL,

    amount             NUMERIC(18, 4) NOT NULL,
    sequence           INTEGER      NOT NULL DEFAULT 0,

    created_at         TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    CONSTRAINT pay_slip_items_slip_same_tenant
        FOREIGN KEY (tenant_id, slip_id)
        REFERENCES payroll_run.pay_slips (tenant_id, slip_id) ON DELETE CASCADE,

    CONSTRAINT pay_slip_items_type_check
        CHECK (component_type IN ('EARNING', 'DEDUCTION')),
    CONSTRAINT pay_slip_items_method_check
        CHECK (calculation_method IN ('FIXED', 'PERCENT_OF_BASE')),
    CONSTRAINT pay_slip_items_amount_check
        CHECK (amount >= 0),
    CONSTRAINT pay_slip_items_value_check
        CHECK (calculation_value >= 0),
    CONSTRAINT pay_slip_items_percent_range_check
        CHECK (calculation_method <> 'PERCENT_OF_BASE' OR calculation_value <= 100),

    -- One line per component per slip.
    CONSTRAINT pay_slip_items_unique UNIQUE (slip_id, component_code)
);

-- Lines are always read for one slip, in payslip order.
CREATE INDEX idx_pay_slip_items_slip
    ON payroll_run.pay_slip_items (tenant_id, slip_id, sequence);

-- ── shadow_payroll_comparisons ───────────────────────────────────────────────

CREATE TABLE payroll_run.shadow_payroll_comparisons (
    comparison_id       UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id           VARCHAR(255) NOT NULL,
    run_id              UUID         NOT NULL,
    employee_id         UUID         NOT NULL,

    legacy_gross_pay    NUMERIC(18, 4) NOT NULL,
    legacy_net_pay      NUMERIC(18, 4) NOT NULL,
    legacy_tax_withheld NUMERIC(18, 4) NOT NULL,

    zoiko_gross_pay     NUMERIC(18, 4) NOT NULL,
    zoiko_net_pay       NUMERIC(18, 4) NOT NULL,
    zoiko_tax_withheld  NUMERIC(18, 4) NOT NULL,

    gross_variance      NUMERIC(18, 4) NOT NULL,
    net_variance        NUMERIC(18, 4) NOT NULL,
    tax_variance        NUMERIC(18, 4) NOT NULL,
    is_equivalent       BOOLEAN      NOT NULL,

    created_at          TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    CONSTRAINT shadow_comparisons_run_same_tenant
        FOREIGN KEY (tenant_id, run_id)
        REFERENCES payroll_run.payroll_runs (tenant_id, run_id) ON DELETE CASCADE
);

CREATE INDEX idx_shadow_comp_tenant_run
    ON payroll_run.shadow_payroll_comparisons (tenant_id, run_id);

-- ── Finalized runs are immutable ─────────────────────────────────────────────

CREATE OR REPLACE FUNCTION payroll_run.reject_finalized_run_mutation()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    -- On UPDATE, OLD is the row as it stands. A run may be updated freely up to
    -- the moment it completes; the transition INTO COMPLETED is itself an
    -- update of a not-yet-completed row, so it passes.
    IF OLD.status = 'COMPLETED' THEN
        RAISE EXCEPTION
            'payroll run % is finalized and immutable: % is not permitted',
            OLD.run_id, TG_OP;
    END IF;
    RETURN NEW;
END;
$$;

COMMENT ON FUNCTION payroll_run.reject_finalized_run_mutation() IS
    'Refuses UPDATE and DELETE of a COMPLETED payroll run. A trigger rather than a grant or policy because it binds even a BYPASSRLS role such as service_role.';

CREATE TRIGGER payroll_runs_finalized_immutable
    BEFORE UPDATE OR DELETE ON payroll_run.payroll_runs
    FOR EACH ROW
    EXECUTE FUNCTION payroll_run.reject_finalized_run_mutation();

CREATE OR REPLACE FUNCTION payroll_run.reject_finalized_slip_mutation()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
    run_status VARCHAR(50);
BEGIN
    SELECT status INTO run_status
    FROM payroll_run.payroll_runs
    WHERE run_id = OLD.run_id;

    IF run_status = 'COMPLETED' THEN
        RAISE EXCEPTION
            'pay slip % belongs to finalized run %: % is not permitted',
            OLD.slip_id, OLD.run_id, TG_OP;
    END IF;
    RETURN NEW;
END;
$$;

COMMENT ON FUNCTION payroll_run.reject_finalized_slip_mutation() IS
    'Refuses UPDATE and DELETE of a pay slip belonging to a COMPLETED run. Recalculation deletes and reinserts slips, which must stop once the run is finalized.';

CREATE TRIGGER pay_slips_finalized_immutable
    BEFORE UPDATE OR DELETE ON payroll_run.pay_slips
    FOR EACH ROW
    EXECUTE FUNCTION payroll_run.reject_finalized_slip_mutation();

-- ── Row-level security ───────────────────────────────────────────────────────

ALTER TABLE payroll_run.payroll_runs               ENABLE ROW LEVEL SECURITY;
ALTER TABLE payroll_run.payroll_runs               FORCE  ROW LEVEL SECURITY;
ALTER TABLE payroll_run.pay_slips                  ENABLE ROW LEVEL SECURITY;
ALTER TABLE payroll_run.pay_slips                  FORCE  ROW LEVEL SECURITY;
ALTER TABLE payroll_run.pay_slip_items             ENABLE ROW LEVEL SECURITY;
ALTER TABLE payroll_run.pay_slip_items             FORCE  ROW LEVEL SECURITY;
ALTER TABLE payroll_run.shadow_payroll_comparisons ENABLE ROW LEVEL SECURITY;
ALTER TABLE payroll_run.shadow_payroll_comparisons FORCE  ROW LEVEL SECURITY;

CREATE POLICY tenant_isolation ON payroll_run.payroll_runs
    FOR ALL TO zoiko_backend
    USING      (tenant_id = app.current_tenant_id())
    WITH CHECK (tenant_id = app.current_tenant_id());

CREATE POLICY tenant_isolation ON payroll_run.pay_slips
    FOR ALL TO zoiko_backend
    USING      (tenant_id = app.current_tenant_id())
    WITH CHECK (tenant_id = app.current_tenant_id());

CREATE POLICY tenant_isolation ON payroll_run.pay_slip_items
    FOR ALL TO zoiko_backend
    USING      (tenant_id = app.current_tenant_id())
    WITH CHECK (tenant_id = app.current_tenant_id());

CREATE POLICY tenant_isolation ON payroll_run.shadow_payroll_comparisons
    FOR ALL TO zoiko_backend
    USING      (tenant_id = app.current_tenant_id())
    WITH CHECK (tenant_id = app.current_tenant_id());

-- A payslip is addressed to one person, so the read is scoped to that person
-- rather than to the tenant. This is the same shape as notification-svc's
-- recipient_read and for the same reason.
--
-- It depends on app.current_principal_id() being the employee_id, which is only
-- true once identity-context principals carry it. Until then this policy
-- matches nothing, which fails closed — nobody reads a payslip they should not.
CREATE POLICY own_payslip_read ON payroll_run.pay_slips
    FOR SELECT TO authenticated
    USING (
        tenant_id = app.current_tenant_id()
        AND employee_id::text = app.current_principal_id()
    );

CREATE POLICY own_payslip_items_read ON payroll_run.pay_slip_items
    FOR SELECT TO authenticated
    USING (
        tenant_id = app.current_tenant_id()
        AND EXISTS (
            SELECT 1 FROM payroll_run.pay_slips s
            WHERE s.slip_id = pay_slip_items.slip_id
              AND s.tenant_id = pay_slip_items.tenant_id
              AND s.employee_id::text = app.current_principal_id()
        )
    );

-- ── Grants ───────────────────────────────────────────────────────────────────

-- No DELETE on payroll_runs: a run is the record that payroll was executed for
-- a period, including one that was blocked.
GRANT SELECT, INSERT, UPDATE ON payroll_run.payroll_runs TO zoiko_backend;

-- Slips, their lines and shadow comparisons DO take DELETE: recalculating a run
-- clears and re-derives them inside one transaction. The triggers above stop
-- that once the run is COMPLETED, which is the point at which the numbers stop
-- being provisional.
GRANT SELECT, INSERT, UPDATE, DELETE ON payroll_run.pay_slips                  TO zoiko_backend;
GRANT SELECT, INSERT, UPDATE, DELETE ON payroll_run.pay_slip_items             TO zoiko_backend;
GRANT SELECT, INSERT, UPDATE, DELETE ON payroll_run.shadow_payroll_comparisons TO zoiko_backend;

GRANT SELECT ON payroll_run.pay_slips      TO authenticated;
GRANT SELECT ON payroll_run.pay_slip_items TO authenticated;


-- ============================================================================
-- FILE: 0026_policies_apply_to_connecting_role.sql
-- ============================================================================

-- 0026_policies_apply_to_connecting_role.sql
-- Platform-wide correction. Creates no tables.
--
-- ── The defect ───────────────────────────────────────────────────────────────
--
-- Every tenant policy in 0001-0025 is written `FOR ALL TO zoiko_backend`, and
-- the services do not connect as zoiko_backend. deployments/supabase creates a
-- role per service — app_identity_context, app_employee_master and so on — and
-- docker-compose.supabase.yml points each service's DB_USER at its own.
--
-- A policy names the roles it applies to. With FORCE ROW LEVEL SECURITY and no
-- policy applicable to the connecting role, that role reads zero rows and
-- writes nothing. Verified: as app_employee_master the register returned
-- `(0 rows)` and an INSERT failed with "new row violates row-level security
-- policy" — for a row in its own tenant, in its own schema.
--
-- ── Why the obvious fix is worse ─────────────────────────────────────────────
--
-- GRANT zoiko_backend TO app_employee_master makes the policy match. It also
-- hands over everything zoiko_backend holds, and every migration grants that
-- role USAGE and DML on its own schema — so zoiko_backend accumulates access to
-- all 25. Verified: with that membership, app_employee_master read
-- payroll_run.pay_slips and inserted a row into it. Tenant isolation survived;
-- SERVICE isolation did not, and "USAGE on its own schema only" is the property
-- the role-per-service design exists to provide.
--
-- ── The fix ──────────────────────────────────────────────────────────────────
--
-- Drop the role restriction. A policy with no TO clause applies to every role,
-- and isolation comes from the grants that were already there: a role holds
-- USAGE on one schema and DML on that schema's tables, so it cannot reach
-- another service's tables whatever the policy says.
--
-- Verified on the same probe: own schema readable, a write to another tenant
-- refused by the policy, and a read of another service's schema refused with
-- "permission denied for schema payroll_run" — at the grant layer, before RLS
-- is consulted at all.
--
-- Widening to PUBLIC does not expose anything to `anon`. Table privileges are
-- checked before row security, and no migration grants anon anything, so anon
-- is refused at the ACL layer and never reaches a policy.
--
-- ── Why this is generated rather than written out ────────────────────────────
--
-- 58 policies name zoiko_backend across 25 files, plus 4 that name it alongside
-- `authenticated`. Transcribing 62 DROP/CREATE pairs by hand invites exactly one
-- typo in exactly one USING clause, which would silently widen a tenant
-- boundary. Reading each policy's own expression out of pg_policies and putting
-- it back verbatim cannot drift from what was reviewed.
--
-- The 38 policies that name ONLY `authenticated` are left alone. Those are the
-- deliberate console-session reads — a recipient reading their own notification,
-- an employee reading the holiday calendar — and they are correctly restricted.

-- ── 1. Policies apply to the connecting role ─────────────────────────────────

DO $$
DECLARE
    p        record;
    stmt     text;
    changed  int := 0;
BEGIN
    FOR p IN
        SELECT schemaname, tablename, policyname, cmd, qual, with_check
          FROM pg_policies
         WHERE 'zoiko_backend' = ANY (roles)
         ORDER BY schemaname, tablename, policyname
    LOOP
        EXECUTE format('DROP POLICY %I ON %I.%I',
                       p.policyname, p.schemaname, p.tablename);

        -- cmd comes from the catalogue as ALL | SELECT | INSERT | UPDATE |
        -- DELETE, so it is a keyword rather than anything caller-supplied.
        stmt := format('CREATE POLICY %I ON %I.%I FOR %s',
                       p.policyname, p.schemaname, p.tablename, p.cmd);

        -- qual is NULL for an INSERT-only policy and with_check is NULL for a
        -- SELECT or DELETE one. Emitting only what was there keeps each policy
        -- legal for its own command without a per-command branch.
        IF p.qual IS NOT NULL THEN
            stmt := stmt || format(' USING (%s)', p.qual);
        END IF;
        IF p.with_check IS NOT NULL THEN
            stmt := stmt || format(' WITH CHECK (%s)', p.with_check);
        END IF;

        EXECUTE stmt;
        changed := changed + 1;
    END LOOP;

    RAISE NOTICE 'policies rewritten to apply to the connecting role: %', changed;
END
$$;

-- ── 2. Every service role can call the identity helpers ──────────────────────
--
-- A policy expression is evaluated as the querying role, so a role that now
-- matches the policy must also be able to run app.current_tenant_id(). 0001
-- granted that to zoiko_backend, authenticated and anon only.
--
-- Guarded on the role existing: on a fresh project the migrations run before
-- deployments/supabase creates the roles, and a missing one must not abort the
-- batch. deployments/supabase performs the same grants, so a later run of it
-- covers roles created after this migration.

DO $$
DECLARE
    r       text;
    granted int := 0;
BEGIN
    FOREACH r IN ARRAY ARRAY[
        'app_identity_context',
        'app_tenant_entity_registry',
        'app_authorization',
        'app_governance_decision_log',
        'app_access_control',
        'app_employee_master',
        'app_leave_absence',
        'app_compensation',
        'app_payroll_run'
    ]
    LOOP
        IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) THEN
            CONTINUE;
        END IF;

        EXECUTE format('GRANT USAGE ON SCHEMA app TO %I', r);
        EXECUTE format('GRANT EXECUTE ON FUNCTION app.current_tenant_id() TO %I', r);
        EXECUTE format('GRANT EXECUTE ON FUNCTION app.current_principal_id() TO %I', r);

        -- Undo the membership if it was granted as a workaround for the defect
        -- this migration fixes. It is what carried cross-service access, and it
        -- is no longer needed for the policy to apply.
        --
        -- Left INHERIT: it is harmless with no memberships, and a role that is
        -- NOINHERIT while holding one would need an explicit SET ROLE per
        -- session, which no service issues.
        EXECUTE format('REVOKE zoiko_backend FROM %I', r);

        granted := granted + 1;
    END LOOP;

    RAISE NOTICE 'service roles granted the identity helpers: %', granted;
END
$$;

-- ── 3. Verification ──────────────────────────────────────────────────────────
--
-- Fails the migration if any policy still carries a role restriction naming
-- zoiko_backend. Cheaper to find here than as an empty register in a service.

DO $$
DECLARE leftover int;
BEGIN
    SELECT count(*) INTO leftover
      FROM pg_policies
     WHERE 'zoiko_backend' = ANY (roles);

    IF leftover > 0 THEN
        RAISE EXCEPTION
            '% policies still restricted to zoiko_backend; the rewrite did not complete',
            leftover;
    END IF;
END
$$;


-- ============================================================================
-- FILE: 0027_tenant_registry_fail_closed.sql
-- ============================================================================

-- 0027_tenant_registry_fail_closed.sql
-- tenant-entity-registry-svc → schema `tenant_entity_registry`. Creates no tables.
--
-- ── Why this schema is not covered by 0001-0026 ──────────────────────────────
--
-- tenant_entity_registry has no migration in this directory. It reached Supabase
-- by a different route: deployments/supabase applies each service's COMPOSE
-- migrations into a schema, and those were written for the database-per-service
-- estate where RLS was decorative — every service connected as the Postgres
-- superuser, so no policy ever executed.
--
-- The result is seven tables carrying the compose-era policy shape, in the
-- schema that is the root of all scope on this platform. Found by surveying the
-- live project rather than the migration set:
--
--   tenants, workspaces, legal_entities, entity_hierarchies,
--   entity_jurisdiction_assignments, tax_identity_bundles,
--   data_residency_policies
--
-- ── The defect: the cast raises where it should match nothing ────────────────
--
-- All seven policies compare `tenant_id = (current_setting('app.tenant_id', …))::uuid`.
-- The cast fails on any value that is not a UUID, and the empty string is not a
-- UUID — so a connection that installed no tenant, or a malformed one, gets
--
--     ERROR:  invalid input syntax for type uuid: ""
--
-- from every table in the schema, where the intended behaviour is zero rows.
-- Measured before this migration on a reproduction of the live shape: reads with
-- no tenant installed, and with a non-UUID tenant, both errored.
--
-- That is fail-LOUD, not fail-open, so it is not a leak. It is still wrong: a
-- service behaving correctly against a connection that has not yet installed a
-- tenant gets a 500 instead of an empty result, and the failure names a type
-- cast rather than the missing identity that caused it.
--
-- Comparing `tenant_id::text = app.current_tenant_id()` degrades to "matches
-- nothing" — the same correction 0004 made for accounts_payable, for the same
-- reason, and the shape every migration in this set uses.
--
-- `workspaces` additionally omitted missing_ok — `current_setting('app.tenant_id')`
-- with no second argument — which would raise on an unset setting even without
-- the cast. Removing the cast removes both failure modes at once.
--
-- ── What WITH CHECK does and does not fix here ────────────────────────────────
--
-- The seven policies carried USING and no WITH CHECK, and the obvious reading is
-- the one 0001 warns about: "with only USING, a caller can INSERT a row into
-- another tenant that it then cannot see."
--
-- That reading is WRONG for these policies, and the reproduction proved it. When
-- a FOR ALL policy omits WITH CHECK, Postgres applies the USING expression to
-- the write check as well — so a cross-tenant INSERT was already refused:
--
--     ERROR:  new row violates row-level security policy for table "workspaces"
--
-- The warning in 0001 holds where a permissive SELECT policy and a separate
-- INSERT policy exist side by side, not for a single FOR ALL policy. WITH CHECK
-- is written out below because being explicit is worth having when the next
-- reader asks the same question — not because it closes a hole.
--
-- ── What this migration does NOT do ──────────────────────────────────────────
--
-- FORCE is applied for consistency and for the day ownership changes, but on
-- Supabase today it is close to cosmetic: these tables are owned by `postgres`,
-- and `postgres` carries BYPASSRLS, which overrides FORCE. The load-bearing
-- change here is WITH CHECK, which applies to app_tenant_entity_registry — a
-- NOBYPASSRLS role that RLS already governed on the read side only.
--
-- It also leaves alone five tables in this project that have NO row security at
-- all, because none of them has a tenant_id column to write a policy against:
--
--   authorization_svc.principal_role_assignments   (principal_id, legal_entity_id)
--   authorization_svc.delegated_authorities        (legal_entity_id)
--   authorization_svc.permission_bundles           (no scope columns)
--   tenant_entity_registry.residency_regions       (no scope columns)
--   zoiko_platform.schema_migrations               (bookkeeping)
--
-- Giving the authorization_svc tables tenant isolation means ADDING a tenant
-- dimension, as 0018 had to for obligations. That is a schema change with live
-- data in the service every write on the platform consults, and it belongs in
-- its own migration with its own review. Their present exposure is bounded by
-- grants: only app_authorization can read them, and `authenticated` cannot.

-- ── Rewrite the seven policies ───────────────────────────────────────────────
--
-- Generated from the catalogue rather than transcribed. The seven differ from
-- each other only in table name, and reading each one back out of pg_policies
-- means the tenant column is discovered rather than assumed — a hand-written set
-- would invite one wrong column name in one USING clause, which is precisely a
-- silently widened tenant boundary.

DO $$
DECLARE
    p        record;
    rewrote  int := 0;
BEGIN
    FOR p IN
        SELECT c.relname AS tablename, pol.polname AS policyname
          FROM pg_policy pol
          JOIN pg_class c     ON c.oid = pol.polrelid
          JOIN pg_namespace n ON n.oid = c.relnamespace
         WHERE n.nspname = 'tenant_entity_registry'
           -- Only tables that actually carry a tenant column. Anything else in
           -- this schema is reference data and is not touched.
           AND EXISTS (
               SELECT 1 FROM pg_attribute a
                WHERE a.attrelid = c.oid AND a.attname = 'tenant_id'
                  AND a.attnum > 0 AND NOT a.attisdropped
           )
         ORDER BY c.relname
    LOOP
        EXECUTE format('DROP POLICY %I ON tenant_entity_registry.%I',
                       p.policyname, p.tablename);

        -- tenant_id::text against app.current_tenant_id():
        --   - NULL when no tenant is installed, and NULL is not true, so the
        --     connection sees nothing and can write nothing. Never rewrite as
        --     "app.current_tenant_id() IS NULL OR ..." — that is a filter which
        --     switches itself off exactly when identity is absent.
        --   - No cast on the setting, so a malformed value matches nothing
        --     rather than raising.
        EXECUTE format($fmt$
            CREATE POLICY %I ON tenant_entity_registry.%I
                FOR ALL
                USING      (tenant_id::text = app.current_tenant_id())
                WITH CHECK (tenant_id::text = app.current_tenant_id())
        $fmt$, p.policyname, p.tablename);

        EXECUTE format('ALTER TABLE tenant_entity_registry.%I ENABLE ROW LEVEL SECURITY', p.tablename);
        EXECUTE format('ALTER TABLE tenant_entity_registry.%I FORCE  ROW LEVEL SECURITY', p.tablename);

        rewrote := rewrote + 1;
    END LOOP;

    RAISE NOTICE 'tenant_entity_registry policies given a WITH CHECK and forced: %', rewrote;
END
$$;

-- ── Verification ─────────────────────────────────────────────────────────────
--
-- Fails the migration rather than leaving a half-applied state to be discovered
-- later as a write that should have been refused.

DO $$
DECLARE
    no_check   int;
    not_forced int;
BEGIN
    SELECT count(*) INTO no_check
      FROM pg_policies
     WHERE schemaname = 'tenant_entity_registry' AND with_check IS NULL;

    SELECT count(*) INTO not_forced
      FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
     WHERE n.nspname = 'tenant_entity_registry' AND c.relkind = 'r'
       AND c.relrowsecurity AND NOT c.relforcerowsecurity;

    IF no_check > 0 THEN
        RAISE EXCEPTION '% tenant_entity_registry policies still have no WITH CHECK', no_check;
    END IF;
    IF not_forced > 0 THEN
        RAISE EXCEPTION '% tenant_entity_registry tables are enabled but not forced', not_forced;
    END IF;
END
$$;
